def _rust_canonical_exports(
    source: str, names: frozenset[str]
) -> frozenset[str]:
    """Return exact names publicly defined or reexported in one Rust scope."""

    exported: set[str] = set()
    for declaration, _ in _rust_public_declarations(source):
        identifiers = [
            match.group(1) for match in RUST_IDENTIFIER.finditer(declaration)
        ]
        if identifiers[:2] == ["pub", "use"]:
            code = declaration
            for alias in re.finditer(
                r"(?<![A-Za-z0-9_#])(?:r#)?([A-Za-z_][A-Za-z0-9_]*)"
                r"[ \t\r\n]+as[ \t\r\n]+(?:r#)?([A-Za-z_][A-Za-z0-9_]*)",
                code,
            ):
                original, public_name = alias.groups()
                if public_name in names:
                    exported.add(public_name)
                if original in names:
                    code = (
                        code[: alias.start(1)]
                        + (" " * len(original))
                        + code[alias.end(1) :]
                    )
            exported.update(
                match.group(1)
                for match in RUST_IDENTIFIER.finditer(code)
                if match.group(1) in names
            )
            continue
        item = re.match(
            r"^[ \t]*pub[ \t\r\n]+(?:struct|enum|type|trait|union)"
            r"[ \t\r\n]+(?:r#)?([A-Za-z_][A-Za-z0-9_]*)",
            declaration,
        )
        if item is not None and item.group(1) in names:
            exported.add(item.group(1))
    return frozenset(exported)


def _rust_root_canonical_exports(
    source: str, names: frozenset[str]
) -> frozenset[str]:
    """Return canonical public names declared/reexported at the root scope."""

    exported: set[str] = set()
    for name in names:
        escaped = re.escape(name)
        patterns = (
            re.compile(
                rf"(?m)^[ \t]*pub[ \t\r\n]+(?:struct|enum|type|trait|union)"
                rf"[ \t\r\n]+(?:r#)?{escaped}\b"
            ),
            re.compile(
                rf"(?m)^[ \t]*pub[ \t\r\n]+use[^;\n]*"
                rf"(?:r#)?{escaped}\b"
            ),
        )
        if any(_rust_root_level_matches(source, pattern) for pattern in patterns):
            exported.add(name)
    return frozenset(exported)


def audit_iwa_keynote_drawable_comment_host_source_topology(
    root: Path = ROOT,
) -> list[str]:
    """Keep the retired direct-comment routes out of the Keynote host.

    The focused Keynote package owns the selector-first drawable-comment API.
    The migration host must therefore have no production or test-only
    identifier for any of the seven former ``KeynoteEditor`` routes.  Scan
    the complete iwa source tree after masking comments and literals so a
    private helper or public re-export cannot quietly recreate the old route.
    The generic ``IWorkDrawableCommentEditor`` remains an intentional shared
    host API for Pages and Numbers and is checked explicitly below.
    """

    source_root = root / IWA_CORE_SOURCE_ROOT
    if not source_root.is_dir():
        return []

    violations: list[str] = []
    for path in sorted(source_root.rglob("*.rs")):
        raw_source = path.read_text(encoding="utf-8")
        source = _mask_rust_non_code(raw_source)
        for match in RUST_IDENTIFIER.finditer(source):
            name = match.group(1)
            if name not in RETIRED_IWA_KEYNOTE_DRAWABLE_COMMENT_METHOD_SET:
                continue
            line_number = source.count("\n", 0, match.start(1)) + 1
            violations.append(
                "retired litchi-iwa Keynote drawable-comment host route "
                f"{name}: {path.relative_to(root)}:{line_number}"
            )

    shared_source_path = root / IWA_SHARED_DRAWABLE_COMMENT_SOURCE
    if not shared_source_path.is_file():
        violations.append(
            "shared litchi-iwa drawable-comment editor source is missing: "
            f"{IWA_SHARED_DRAWABLE_COMMENT_SOURCE}"
        )
    else:
        shared_source = _mask_rust_non_code(
            shared_source_path.read_text(encoding="utf-8")
        )
        if re.search(
            rf"\bpub\s+struct\s+{re.escape(IWA_SHARED_DRAWABLE_COMMENT_EDITOR_TYPE)}\b",
            shared_source,
        ) is None:
            violations.append(
                "shared litchi-iwa drawable-comment editor type is missing: "
                f"{IWA_SHARED_DRAWABLE_COMMENT_EDITOR_TYPE}: "
                f"{IWA_SHARED_DRAWABLE_COMMENT_SOURCE}"
            )

    export_source_path = root / IWA_SHARED_DRAWABLE_COMMENT_EXPORT_SOURCE
    if not export_source_path.is_file():
        violations.append(
            "shared litchi-iwa drawable-comment editor export source is missing: "
            f"{IWA_SHARED_DRAWABLE_COMMENT_EXPORT_SOURCE}"
        )
    else:
        export_source = _mask_rust_non_code(
            export_source_path.read_text(encoding="utf-8")
        )
        if re.search(
            rf"\bpub(?:\s*\([^)]*\))?\s+use\s+"
            rf"[^;\n]*\b{re.escape(IWA_SHARED_DRAWABLE_COMMENT_EDITOR_TYPE)}\b",
            export_source,
        ) is None:
            violations.append(
                "shared litchi-iwa drawable-comment editor export is missing: "
                f"{IWA_SHARED_DRAWABLE_COMMENT_EDITOR_TYPE}: "
                f"{IWA_SHARED_DRAWABLE_COMMENT_EXPORT_SOURCE}"
            )

    return sorted(set(violations))


def audit_iwa_keynote_source_topology(root: Path = ROOT) -> list[str]:
    """Prevent retired Keynote mutation surfaces from returning to the host."""

    source_root = root / IWA_KEYNOTE_SOURCE_ROOT
    violations: list[str] = []
    if source_root.is_dir():
        for path in sorted(source_root.rglob("*.rs")):
            source = path.read_text(encoding="utf-8")
            for name, line_number in _rust_function_declarations(source):
                if name not in RETIRED_IWA_KEYNOTE_METHOD_SET:
                    continue
                violations.append(
                    "retired litchi-iwa Keynote method "
                    f"{name}: {path.relative_to(root)}:{line_number}"
                )

    retired_example = root / RETIRED_IWA_KEYNOTE_SLIDE_NAME_EXAMPLE
    if retired_example.exists():
        violations.append(
            "retired litchi-iwa Keynote slide-name example returned: "
            + str(RETIRED_IWA_KEYNOTE_SLIDE_NAME_EXAMPLE)
        )

    readme_path = root / IWA_KEYNOTE_README
    if readme_path.exists():
        source = readme_path.read_text(encoding="utf-8")
        for match in IWA_KEYNOTE_README_SLIDE_NAME_CALL.finditer(source):
            line_number = source.count("\n", 0, match.start()) + 1
            violations.append(
                "retired litchi-iwa Keynote slide-name README call "
                f"{match.group('method')}: {IWA_KEYNOTE_README}:{line_number}"
            )

    violations.extend(
        _audit_iwa_standalone_retired_routes(
            root,
            ecosystem="Keynote",
            label="Keynote",
        )
    )
    return sorted(set(violations))


def audit_iwa_legacy_method_deprecation_source_topology(
    root: Path = ROOT,
) -> list[str]:
    """Keep retained Numbers/Pages raw-ID compatibility methods deprecated.

    These methods remain available because the migration host still handles
    sources that the focused package owners cannot edit.  Their signatures
    nevertheless accept native object identities, so dropping the marker
    would make a compatibility path look like a supported semantic API again.
    Keep this source-only check exact to the two migrated method families; it
    does not classify unrelated host capabilities that have no focused owner.
    """

    methods = (
        (
            IWA_NUMBERS_LEGACY_METHOD_SOURCE,
            "Numbers",
            IWA_NUMBERS_LEGACY_METHODS,
        ),
        (
            IWA_PAGES_LEGACY_METHOD_SOURCE,
            "Pages",
            IWA_PAGES_LEGACY_METHODS,
        ),
    )
    declaration = re.compile(
        r"(?<![A-Za-z0-9_#])pub[ \t\r\n]+fn[ \t\r\n]+"
        r"(?:r#)?([A-Za-z_][A-Za-z0-9_]*)\b"
    )
    violations: list[str] = []

    for relative, product, names in methods:
        path = root / relative
        if not path.is_file():
            continue
        source = _mask_rust_non_code(path.read_text(encoding="utf-8"))
        for match in declaration.finditer(source):
            name = match.group(1)
            if name not in names:
                continue

            prefix = source[: match.start()]
            attributes = list(
                re.finditer(r"^[ \t]*#[ \t]*\[", prefix, re.MULTILINE)
            )
            nearest = attributes[-1] if attributes else None
            deprecated = False
            if nearest is not None:
                attribute = prefix[nearest.start() :]
                if re.match(r"[ \t]*#[ \t]*\[[ \t]*deprecated\b", attribute):
                    closing = attribute.rfind("]")
                    deprecated = closing >= 0 and not attribute[closing + 1 :].strip()

            if not deprecated:
                line_number = source.count("\n", 0, match.start()) + 1
                violations.append(
                    f"litchi-iwa {product} legacy method must remain deprecated "
                    f"{name}: {relative}:{line_number}"
                )

    return sorted(set(violations))


def audit_iwa_numbers_comment_reader_retention_source_topology(
    root: Path = ROOT,
    *,
    require_retained: bool = True,
) -> list[str]:
    """Keep the legacy Numbers reply reader while migration debt is open.

    The focused package now projects a narrow semantic comment snapshot, but
    the compatibility host still handles reply identity and source-built
    reply graphs.  The root reader is retired by the separate evidence-gated
    ratchet below; ``require_retained`` is supplied by ``main`` from the
    checked-in migration policy so a future debt exit can remove this
    compatibility method without leaving a permanent source tombstone.
    """

    if not require_retained:
        return []

    path = root / IWA_NUMBERS_LEGACY_METHOD_SOURCE
    if not path.is_file():
        return [
            "retained litchi-iwa Numbers comment readers require their source "
            f"while migration debt 015 is open: {IWA_NUMBERS_LEGACY_METHOD_SOURCE}"
        ]

    source = _mask_rust_cfg_test_items(path.read_text(encoding="utf-8"))
    public_methods: set[str] = set()
    for declaration, _line_number in _rust_public_declarations(source):
        function = RUST_FUNCTION_DECLARATION.search(declaration)
        if function is not None:
            public_methods.add(function.group(1))

    violations = [
        "retained litchi-iwa Numbers comment reader is missing while migration "
        f"debt 015 is open {name}: {IWA_NUMBERS_LEGACY_METHOD_SOURCE}"
        for name in RETAINED_IWA_NUMBERS_COMMENT_READER_METHODS
        if name not in public_methods
    ]
    return sorted(violations)


def _iwa_numbers_cell_comment_reader_compat_module_is_private_hidden(
    root: Path,
) -> bool:
    """Recognize the one private module allowed to expose source bytes.

    The compatibility implementation is included from ``comments.rs`` under
    the internal source feature.  Require the complete hidden/path-gated
    declaration here so a similarly named module, a public module, or a
    copied file cannot widen the mutation-facade exception.
    """

    module_path = root / IWA_NUMBERS_CELL_COMMENT_READER_COMPAT_MODULE_SOURCE
    if not module_path.is_file():
        return False
    raw_source = _mask_rust_cfg_test_items(
        module_path.read_text(encoding="utf-8")
    )
    source = _mask_rust_non_code(raw_source)
    for match in IWA_NUMBERS_CELL_COMMENT_READER_COMPAT_MODULE.finditer(source):
        statement = match.group(0)
        if re.search(r"\bpub\b", statement) is not None:
            continue
        attributes = _rust_attribute_block_before(raw_source, match.start())
        if (
            IWA_INTERNAL_SOURCE_CFG_ATTRIBUTE.search(attributes) is None
            or IWA_DOC_HIDDEN_ATTRIBUTE.search(attributes) is None
            or IWA_NUMBERS_CELL_COMMENT_READER_COMPAT_PATH_ATTRIBUTE.search(
                attributes
            )
            is None
        ):
            continue
        return True
    return False


def _iwa_numbers_cell_comment_reader_compat_public_method_allowed(
    root: Path,
    path: Path,
    source: str,
    name: str,
    declaration: str,
    line_number: int,
) -> bool:
    """Allow only the four hidden methods in the private compatibility seam."""

    if path != root / IWA_NUMBERS_CELL_COMMENT_READER_COMPAT_SOURCE:
        return False
    if name not in IWA_NUMBERS_CELL_COMMENT_READER_COMPAT_PUBLIC_METHOD_SET:
        return False
    expected = IWA_NUMBERS_CELL_COMMENT_READER_COMPAT_PUBLIC_SIGNATURES.get(name)
    if expected is None or re.sub(r"\s+", " ", declaration).strip() != expected:
        return False
    if not _iwa_numbers_cell_comment_reader_compat_module_is_private_hidden(root):
        return False

    source_code = _mask_rust_non_code(source)
    method_pattern = re.compile(
        rf"(?<![A-Za-z0-9_#])pub(?![ \t\r\n]*\()[ \t\r\n]+"
        rf"(?:(?:unsafe|async|const)[ \t\r\n]+)*fn[ \t\r\n]+"
        rf"(?:r#)?{re.escape(name)}\b"
    )
    method_match = next(
        (
            match
            for match in method_pattern.finditer(source_code)
            if source_code.count("\n", 0, match.start()) + 1 == line_number
        ),
        None,
    )
    if method_match is None:
        return False
    attributes = _rust_attribute_block_before(source, method_match.start())
    return IWA_DOC_HIDDEN_ATTRIBUTE.search(attributes) is not None


def _iwa_numbers_cell_comment_reader_retirement_evidence_ready(
    root: Path,
) -> bool:
    """Return whether root-reader retirement has source and test evidence.

    The compatibility reader deliberately lives behind a private module, but
    a file appearing on disk is not enough to close the migration gate.  Keep
    the ratchet dormant until both selector-first compatibility methods are
    present, their source-built tests prove source preservation, and the
    existing wire-oracle/native suites still cover focused ingress.  This
    lets the source migration land atomically while preventing an untested
    half-seam from deleting the only reader for old packages.
    """

    compat_path = root / IWA_NUMBERS_CELL_COMMENT_READER_COMPAT_SOURCE
    compat_module_path = root / IWA_NUMBERS_CELL_COMMENT_READER_COMPAT_MODULE_SOURCE
    compat_test_path = root / IWA_NUMBERS_CELL_COMMENT_READER_COMPAT_TEST_SOURCE
    parity_path = root / IWA_NUMBERS_CELL_COMMENT_READER_PARITY_SOURCE
    native_path = root / IWA_NUMBERS_CELL_COMMENT_READER_NATIVE_SOURCE
    if not all(
        path.is_file()
        for path in (
            compat_path,
            compat_module_path,
            compat_test_path,
            parity_path,
            native_path,
        )
    ):
        return False

    if not _iwa_numbers_cell_comment_reader_compat_module_is_private_hidden(root):
        return False

    compat_raw = _mask_rust_cfg_test_items(compat_path.read_text(encoding="utf-8"))
    compat_methods = _rust_public_methods_in_impl(compat_raw, "Package")
    for method in IWA_NUMBERS_CELL_COMMENT_READER_COMPAT_PUBLIC_METHODS:
        records = [
            (declaration, line_number)
            for name, declaration, line_number in compat_methods
            if name == method
        ]
        if len(records) != 1:
            return False
        declaration, line_number = records[0]
        if not _iwa_numbers_cell_comment_reader_compat_public_method_allowed(
            root,
            compat_path,
            compat_raw,
            method,
            declaration,
            line_number,
        ):
            return False
    compat_code = _mask_rust_non_code(compat_raw)
    if any(marker.search(compat_code) is None for marker in IWA_NUMBERS_CELL_COMMENT_READER_COMPAT_SEAM_MARKERS):
        return False

    compat_test = _mask_rust_non_code(
        compat_test_path.read_text(encoding="utf-8")
    )
    if any(
        marker not in compat_test
        for marker in IWA_NUMBERS_CELL_COMMENT_READER_COMPAT_TEST_MARKERS
    ):
        return False
    if (
        IWA_NUMBERS_CELL_COMMENT_READER_COMPAT_TEST_SOURCE_PRESERVATION.search(
            compat_test
        )
        is None
    ):
        return False

    parity = _mask_rust_non_code(
        _mask_rust_cfg_test_items(parity_path.read_text(encoding="utf-8"))
    )
    if re.search(
        rf"(?<![A-Za-z0-9_])(?:fn|async[ \t\r\n]+fn)[ \t\r\n]+"
        rf"{re.escape(IWA_NUMBERS_CELL_COMMENT_READER_PARITY_TEST)}\b",
        parity,
    ) is None:
        return False
    if any(marker not in parity for marker in IWA_NUMBERS_CELL_COMMENT_READER_PARITY_MARKERS):
        return False

    native = _mask_rust_non_code(
        _mask_rust_cfg_test_items(native_path.read_text(encoding="utf-8"))
    )
    for test_name in IWA_NUMBERS_CELL_COMMENT_READER_NATIVE_TESTS:
        if re.search(
            rf"(?<![A-Za-z0-9_])(?:fn|async[ \t\r\n]+fn)[ \t\r\n]+"
            rf"{re.escape(test_name)}\b",
            native,
        ) is None:
            return False
    return all(marker in native for marker in IWA_NUMBERS_CELL_COMMENT_READER_NATIVE_MARKERS)


def audit_iwa_numbers_cell_comment_reader_retirement_source_topology(
    root: Path = ROOT,
) -> list[str]:
    """Retire only ``NumbersEditor::cell_comment`` after parity evidence.

    ``cell_comment_replies`` intentionally remains in the retention audit
    above.  This scan is limited to the Numbers host and its callers, so
    private Pages/Keynote helpers and private Numbers model witnesses remain
    valid compatibility implementation details.  It rejects the public root
    method, re-exports, and raw-ID calls once the compatibility seam and all
    required parity evidence are present.
    """

    if not _iwa_numbers_cell_comment_reader_retirement_evidence_ready(root):
        return []

    caller_roots = (
        root / IWA_NUMBERS_SOURCE_ROOT,
        root / Path("crates/litchi-iwa/tests"),
        root / Path("crates/litchi-iwa/examples"),
    )
    paths: set[Path] = set()
    for caller_root in caller_roots:
        if caller_root.is_dir():
            paths.update(caller_root.rglob("*.rs"))

    violations: list[str] = []
    for path in sorted(paths):
        raw_source = path.read_text(encoding="utf-8")
        source = _mask_rust_cfg_test_items(raw_source)
        code = _mask_rust_non_code(source)
        relative = path.relative_to(root)

        for declaration, line_number in _rust_public_declarations(source):
            function = RUST_FUNCTION_DECLARATION.search(declaration)
            if function is None or function.group(1) not in RETIRED_IWA_NUMBERS_CELL_COMMENT_READER_METHOD_SET:
                continue
            name = function.group(1)
            violations.append(
                "retired litchi-iwa NumbersEditor::cell_comment method returned: "
                f"{relative}:{line_number}"
            )
            for match in IWA_NUMBERS_CELL_COMMENT_READER_RAW_ID_PARAMETER.finditer(
                declaration
            ):
                parameter = re.sub(r"\s+", " ", match.group(0)).strip()
                parameter_line = line_number + declaration.count("\n", 0, match.start())
                violations.append(
                    "retired litchi-iwa Numbers cell_comment public method exposes "
                    f"raw identifier parameter {parameter}: {relative}:{parameter_line}"
                )

        for match in IWA_NUMBERS_CELL_COMMENT_READER_REEXPORT.finditer(code):
            line_number = code.count("\n", 0, match.start()) + 1
            violations.append(
                "retired litchi-iwa Numbers cell_comment re-export returned: "
                f"{relative}:{line_number}"
            )

        for match in IWA_NUMBERS_CELL_COMMENT_READER_CALL.finditer(code):
            line_number = code.count("\n", 0, match.start()) + 1
            violations.append(
                "retired litchi-iwa Numbers cell_comment raw-ID call returned: "
                f"{relative}:{line_number}"
            )

    return sorted(set(violations))


def audit_iwa_keynote_slide_info_source_topology(root: Path = ROOT) -> list[str]:
    """Keep migrated Keynote slide and text-storage IDs advisory-deprecated.

    ``KeynoteSlideInfo`` remains a migration-host compatibility value, but its
    slide-node, slide, title/body, and speaker-notes identities are native
    handles. The focused package owns semantic slide and title/body text
    paths now, so a future edit must not silently make the handles look like
    supported API again.
    """

    path = root / IWA_KEYNOTE_EDITOR_SOURCE
    if not path.is_file():
        return []

    source = _mask_rust_non_code(path.read_text(encoding="utf-8"))
    struct = _rust_named_struct_body(source, "KeynoteSlideInfo")
    if struct is None:
        return []
    body, body_offset = struct
    violations: list[str] = []

    for field_name in IWA_KEYNOTE_SLIDE_INFO_RAW_FIELDS:
        field = re.search(
            rf"^[ \t]*pub[ \t]+(?:r#)?{re.escape(field_name)}\b[ \t]*:",
            body,
            re.MULTILINE,
        )
        if field is None:
            continue

        prefix = body[: field.start()]
        attributes = list(re.finditer(r"^[ \t]*#[ \t]*\[", prefix, re.MULTILINE))
        nearest = attributes[-1] if attributes else None
        deprecated = False
        if nearest is not None and re.match(
            r"[ \t]*#[ \t]*\[[ \t]*deprecated\b",
            prefix[nearest.start() :],
        ):
            closing = prefix.find("]", nearest.end())
            if closing >= 0 and not prefix[closing + 1 :].strip():
                deprecated = True
        if deprecated:
            continue

        line_number = source.count("\n", 0, body_offset + field.start()) + 1
        violations.append(
            "litchi-iwa Keynote slide info native field must remain deprecated "
            f"{field_name}: {IWA_KEYNOTE_EDITOR_SOURCE}:{line_number}"
        )

    return sorted(set(violations))


