def audit_keynote_soundtrack_settings_facade_source_topology(
    root: Path = ROOT,
) -> list[str]:
    """Enforce the direct, archive-free Keynote soundtrack-settings API."""

    source_root = root / KEYNOTE_SOURCE_ROOT
    if not source_root.is_dir():
        return []
    dedicated_sources = {
        root / path
        for path in KEYNOTE_SOUNDTRACK_SETTINGS_IMPLEMENTATION_SOURCES
        if (root / path).is_file()
    }
    owner_helper_root = root / KEYNOTE_SOUNDTRACK_SETTINGS_OWNER_HELPER_ROOT
    if owner_helper_root.is_dir():
        dedicated_sources.update(owner_helper_root.rglob("*.rs"))
    export_sources = {
        root / path
        for path in KEYNOTE_SOUNDTRACK_SETTINGS_EXPORT_SOURCES
        if (root / path).is_file()
    }
    violations: list[str] = []

    semantic_path = root / KEYNOTE_SOUNDTRACK_SETTINGS_SEMANTIC_SOURCE
    semantic_source = (
        semantic_path.read_text(encoding="utf-8")
        if semantic_path.is_file()
        else ""
    )
    canonical_exports = _rust_canonical_exports(
        semantic_source, KEYNOTE_SOUNDTRACK_SETTINGS_SHORT_NAMES
    )
    for name in KEYNOTE_SOUNDTRACK_SETTINGS_CANONICAL_TYPES:
        if name in canonical_exports:
            continue
        violations.append(
            "focused litchi-keynote soundtrack settings public API is missing "
            f"canonical soundtrack type {name}: "
            f"{KEYNOTE_SOUNDTRACK_SETTINGS_SEMANTIC_SOURCE}"
        )

    semantic_code = _mask_rust_non_code(semantic_source)
    for match in PUBLIC_KEYNOTE_SOUNDTRACK_TRANSACTION_MODULE.finditer(semantic_code):
        line_number = semantic_code.count("\n", 0, match.start()) + 1
        violations.append(
            "focused litchi-keynote soundtrack settings public API exposes "
            "duplicate soundtrack::transaction module: "
            f"{KEYNOTE_SOUNDTRACK_SETTINGS_SEMANTIC_SOURCE}:{line_number}"
        )

    lib_export = root / KEYNOTE_SOURCE_ROOT / "lib.rs"
    lib_source = (
        _mask_rust_non_code(lib_export.read_text(encoding="utf-8"))
        if lib_export.is_file()
        else ""
    )
    if PUBLIC_KEYNOTE_SOUNDTRACK_MODULE.search(lib_source) is None:
        violations.append(
            "focused litchi-keynote soundtrack settings public API is missing "
            "canonical root soundtrack module: "
            f"{KEYNOTE_SOURCE_ROOT / 'lib.rs'}"
        )

    package_export = root / KEYNOTE_SOURCE_ROOT / "package.rs"
    if package_export.is_file():
        package_source = _mask_rust_non_code(
            package_export.read_text(encoding="utf-8")
        )
        if KEYNOTE_PACKAGE_SOUNDTRACK_SETTINGS_MODULE.search(package_source) is None:
            violations.append(
                "focused litchi-keynote soundtrack settings public API is missing "
                "private package owner module: "
                f"{package_export.relative_to(root)}"
            )
        for match in PUBLIC_KEYNOTE_PACKAGE_SOUNDTRACK_SETTINGS_MODULE.finditer(
            package_source
        ):
            line_number = package_source.count("\n", 0, match.start()) + 1
            violations.append(
                "focused litchi-keynote soundtrack settings public API exposes "
                "duplicate package::soundtrack_settings module: "
                f"{package_export.relative_to(root)}:{line_number}"
            )
    else:
        violations.append(
            "focused litchi-keynote soundtrack settings public API is missing "
            "private package owner module: "
            f"{KEYNOTE_SOURCE_ROOT / 'package.rs'}"
        )

    owner_path = root / KEYNOTE_SOUNDTRACK_SETTINGS_OWNER_SOURCE
    if not owner_path.is_file():
        violations.append(
            "focused litchi-keynote soundtrack settings public API is missing "
            "private package owner source: "
            f"{KEYNOTE_SOUNDTRACK_SETTINGS_OWNER_SOURCE}"
        )

    for path in sorted(dedicated_sources | export_sources):
        dedicated_source = path in dedicated_sources
        source = path.read_text(encoding="utf-8")
        declarations = [
            (declaration, line_number, True, dedicated_source)
            for declaration, line_number in _rust_public_declarations(source)
        ]
        if dedicated_source:
            declarations.extend(
                (declaration, line_number, False, False)
                for declaration, line_number in _rust_impl_headers(source)
            )
        for (
            declaration,
            line_number,
            public_declaration,
            complete_source_scope,
        ) in declarations:
            if not _is_keynote_soundtrack_settings_public_declaration(
                declaration, dedicated_source=complete_source_scope
            ):
                continue
            owner_declaration = _keynote_soundtrack_settings_owner_declaration(
                declaration
            )
            declaration_identifiers = [
                match.group(1) for match in RUST_IDENTIFIER.finditer(declaration)
            ]
            public_use_or_type = declaration_identifiers[:2] in (
                ["pub", "type"],
                ["pub", "use"],
            )
            if (
                public_declaration
                and path in export_sources
                and owner_declaration
                and declaration_identifiers[:2] == ["pub", "use"]
                and "*" in declaration
            ):
                violations.append(
                    "focused litchi-keynote soundtrack settings public API "
                    "retains root aliases via soundtrack glob: "
                    f"{path.relative_to(root)}:{line_number}"
                )
            if (
                public_declaration
                and path in export_sources
                and public_use_or_type
                and any(
                    identifier in {"soundtrack", "soundtrack_settings"}
                    for identifier in declaration_identifiers
                )
            ):
                violations.append(
                    "focused litchi-keynote soundtrack settings public API exposes "
                    "public soundtrack owner alias: "
                    f"{path.relative_to(root)}:{line_number}"
                )
            for match in RUST_IDENTIFIER.finditer(declaration):
                identifier = match.group(1)
                identifier_line = line_number + declaration.count(
                    "\n", 0, match.start(1)
                )
                if (
                    public_declaration
                    and identifier in KEYNOTE_SOUNDTRACK_SETTINGS_FLAT_ALIASES
                ):
                    violations.append(
                        "focused litchi-keynote soundtrack settings public API "
                        f"retains flat alias {identifier}: "
                        f"{path.relative_to(root)}:{identifier_line}"
                    )
                if (
                    public_declaration
                    and path in export_sources
                    and owner_declaration
                    and public_use_or_type
                    and identifier in KEYNOTE_SOUNDTRACK_SETTINGS_SHORT_NAMES
                ):
                    violations.append(
                        "focused litchi-keynote soundtrack settings public API "
                        f"retains root alias {identifier}: "
                        f"{path.relative_to(root)}:{identifier_line}"
                    )
                if (
                    public_declaration
                    and identifier
                    in KEYNOTE_SOUNDTRACK_SETTINGS_FORBIDDEN_PUBLIC_MEMBERS
                ):
                    violations.append(
                        "focused litchi-keynote soundtrack settings public API "
                        f"retains host-style public member {identifier}: "
                        f"{path.relative_to(root)}:{identifier_line}"
                    )
                reason = _keynote_soundtrack_settings_public_leak(identifier)
                if reason is None:
                    continue
                violations.append(
                    "focused litchi-keynote soundtrack settings public API exposes "
                    f"{reason} {identifier}: "
                    f"{path.relative_to(root)}:{identifier_line}"
                )
            for match in RUST_BYTE_SLICE.finditer(declaration):
                byte_slice = re.sub(r"\s+", "", match.group(0))
                byte_slice_line = line_number + declaration.count(
                    "\n", 0, match.start()
                )
                violations.append(
                    "focused litchi-keynote soundtrack settings public API exposes "
                    f"raw byte slice {byte_slice}: "
                    f"{path.relative_to(root)}:{byte_slice_line}"
                )

    return sorted(set(violations))


def _keynote_soundtrack_items_public_leak(identifier: str) -> str | None:
    """Classify physical vocabulary forbidden in soundtrack item values."""

    if identifier in KEYNOTE_SOUNDTRACK_ITEMS_PROTO_ORIGINS:
        return "protobuf type"
    if identifier in KEYNOTE_SOUNDTRACK_ITEMS_PHYSICAL_TYPES:
        return "archive/IWA type"
    if identifier == "wire" or identifier in KEYNOTE_SOUNDTRACK_ITEMS_WIRE_TYPES:
        return "wire type"
    if identifier in KEYNOTE_SOUNDTRACK_ITEMS_TOPOLOGY_NAMES:
        return "soundtrack media topology"
    return _iwork_public_leak(identifier)


def audit_keynote_soundtrack_items_facade_source_topology(
    root: Path = ROOT,
) -> list[str]:
    """Require the focused semantic soundtrack-item owner."""

    source_root = root / KEYNOTE_SOURCE_ROOT
    if not source_root.is_dir():
        return []

    violations: list[str] = []
    semantic_path = root / KEYNOTE_SOUNDTRACK_ITEMS_SEMANTIC_SOURCE
    owner_path = root / KEYNOTE_SOUNDTRACK_ITEMS_OWNER_SOURCE
    package_path = root / (KEYNOTE_SOURCE_ROOT / "package.rs")
    soundtrack_path = root / (KEYNOTE_SOURCE_ROOT / "soundtrack.rs")
    lib_path = root / (KEYNOTE_SOURCE_ROOT / "lib.rs")

    if not semantic_path.is_file():
        violations.append(
            "focused litchi-keynote soundtrack items public API is missing "
            f"semantic source: {KEYNOTE_SOUNDTRACK_ITEMS_SEMANTIC_SOURCE}"
        )
        return violations
    if not owner_path.is_file():
        violations.append(
            "focused litchi-keynote soundtrack items public API is missing "
            f"private package owner source: {KEYNOTE_SOUNDTRACK_ITEMS_OWNER_SOURCE}"
        )
    if not package_path.is_file():
        violations.append(
            "focused litchi-keynote soundtrack items public API is missing "
            f"package owner module source: {KEYNOTE_SOURCE_ROOT / 'package.rs'}"
        )

    semantic_source = semantic_path.read_text(encoding="utf-8")
    semantic_exports = _rust_canonical_exports(
        semantic_source, KEYNOTE_SOUNDTRACK_ITEMS_SHORT_NAMES
    )
    for name in KEYNOTE_SOUNDTRACK_ITEMS_CANONICAL_TYPES:
        if name in semantic_exports:
            continue
        violations.append(
            "focused litchi-keynote soundtrack items public API is missing "
            f"canonical soundtrack item type {name}: "
            f"{KEYNOTE_SOUNDTRACK_ITEMS_SEMANTIC_SOURCE}"
        )

    if soundtrack_path.is_file():
        soundtrack_source = _mask_rust_non_code(
            soundtrack_path.read_text(encoding="utf-8")
        )
        if KEYNOTE_SOUNDTRACK_ITEMS_MODULE.search(soundtrack_source) is None:
            violations.append(
                "focused litchi-keynote soundtrack items public API is missing "
                "public soundtrack::items module: "
                f"{KEYNOTE_SOURCE_ROOT / 'soundtrack.rs'}"
            )
    else:
        violations.append(
            "focused litchi-keynote soundtrack items public API is missing "
            f"semantic soundtrack module source: {KEYNOTE_SOURCE_ROOT / 'soundtrack.rs'}"
        )

    if package_path.is_file():
        package_source = _mask_rust_non_code(
            package_path.read_text(encoding="utf-8")
        )
        if KEYNOTE_PACKAGE_SOUNDTRACK_ITEMS_MODULE.search(package_source) is None:
            violations.append(
                "focused litchi-keynote soundtrack items public API is missing "
                "private package soundtrack_items module: "
                f"{KEYNOTE_SOURCE_ROOT / 'package.rs'}"
            )
        public_module = re.compile(
            r"^[ \t]*pub[ \t\r\n]+mod[ \t\r\n]+(?:r#)?soundtrack_items\b",
            re.MULTILINE,
        )
        for match in public_module.finditer(package_source):
            line_number = package_source.count("\n", 0, match.start()) + 1
            violations.append(
                "focused litchi-keynote soundtrack items public API exposes "
                "package::soundtrack_items module: "
                f"{KEYNOTE_SOURCE_ROOT / 'package.rs'}:{line_number}"
            )

    if lib_path.is_file():
        lib_source = _mask_rust_non_code(lib_path.read_text(encoding="utf-8"))
        if re.search(
            r"^[ \t]*pub[ \t\r\n]+mod[ \t\r\n]+(?:r#)?soundtrack\b",
            lib_source,
            re.MULTILINE,
        ) is None:
            violations.append(
                "focused litchi-keynote soundtrack items public API is missing "
                f"root soundtrack module: {KEYNOTE_SOURCE_ROOT / 'lib.rs'}"
            )

    implementation_sources = [semantic_path]
    if owner_path.is_file():
        implementation_sources.append(owner_path)
    declarations: list[tuple[Path, str, int]] = []
    for path in implementation_sources:
        source = path.read_text(encoding="utf-8")
        declarations.extend(
            (path, declaration, line_number)
            for declaration, line_number in _rust_public_declarations(source)
        )
    for path, declaration, line_number in declarations:
        for match in RUST_IDENTIFIER.finditer(declaration):
            identifier = match.group(1)
            reason = _keynote_soundtrack_items_public_leak(identifier)
            if reason is None:
                continue
            identifier_line = line_number + declaration.count(
                "\n", 0, match.start(1)
            )
            violations.append(
                "focused litchi-keynote soundtrack items public API exposes "
                f"{reason} {identifier}: {path.relative_to(root)}:{identifier_line}"
            )
        for match in RUST_BYTE_SLICE.finditer(declaration):
            method = re.search(
                r"\bfn[ \t\r\n]+(?:r#)?([A-Za-z_][A-Za-z0-9_]*)\b",
                declaration,
            )
            if method is not None and method.group(1) in (
                KEYNOTE_SOUNDTRACK_ITEMS_ALLOWED_RAW_SLICE_METHODS
            ):
                continue
            byte_slice = re.sub(r"\s+", "", match.group(0))
            byte_slice_line = line_number + declaration.count(
                "\n", 0, match.start()
            )
            violations.append(
                "focused litchi-keynote soundtrack items public API exposes "
                f"raw byte slice {byte_slice}: {path.relative_to(root)}:{byte_slice_line}"
            )

    method_sources = [package_path]
    if owner_path.is_file():
        method_sources.append(owner_path)
    methods: set[str] = set()
    for path in method_sources:
        methods.update(
            name for name, _line_number in _rust_function_declarations(
                path.read_text(encoding="utf-8")
            )
        )
    for method in KEYNOTE_SOUNDTRACK_ITEMS_PACKAGE_METHODS:
        if method in methods:
            continue
        violations.append(
            "focused litchi-keynote soundtrack items public API is missing "
            f"Package::{method}: {KEYNOTE_SOURCE_ROOT / 'package.rs'}"
        )

    return sorted(set(violations))


def audit_iwa_keynote_soundtrack_items_source_topology(root: Path = ROOT) -> list[str]:
    """Keep retired Keynote soundtrack-item CRUD out of the migration host."""
    violations: list[str] = []
    for path in RETIRED_IWA_KEYNOTE_SOUNDTRACK_ITEMS_SOURCES:
        if (root / path).exists():
            violations.append(f"retired litchi-iwa Keynote soundtrack-item source returned: {path}")
    if (root / RETIRED_IWA_KEYNOTE_SOUNDTRACK_ITEMS_EXAMPLE).exists():
        violations.append(f"retired litchi-iwa Keynote soundtrack-item example returned: {RETIRED_IWA_KEYNOTE_SOUNDTRACK_ITEMS_EXAMPLE}")
    source_root = root / IWA_KEYNOTE_SOURCE_ROOT
    if source_root.is_dir():
        for path in sorted(source_root.rglob("*.rs")):
            source = path.read_text(encoding="utf-8")
            for name, line_number in _rust_function_declarations(source):
                if name in RETIRED_IWA_KEYNOTE_SOUNDTRACK_ITEMS_METHODS:
                    violations.append(f"retired litchi-iwa Keynote soundtrack-item method {name}: {path.relative_to(root)}:{line_number}")
                if name in RETIRED_IWA_KEYNOTE_SOUNDTRACK_ITEMS_TESTS:
                    violations.append(f"retired litchi-iwa Keynote soundtrack-item test {name}: {path.relative_to(root)}:{line_number}")
    host_root = root / Path("crates/litchi-iwa")
    if host_root.is_dir():
        for path in sorted(host_root.rglob("*.rs")):
            source = _mask_rust_non_code(path.read_text(encoding="utf-8"))
            for match in RETIRED_IWA_KEYNOTE_SOUNDTRACK_ITEMS_CALL.finditer(source):
                receiver = source[match.start():match.end()].split(".", 1)[0].strip()
                if receiver == "KeynotePackage":
                    continue
                line_number = source.count("\n", 0, match.start()) + 1
                violations.append(f"retired litchi-iwa Keynote soundtrack-item call: {path.relative_to(root)}:{line_number}")
    for path in (IWA_KEYNOTE_EDITOR_SOURCE, IWA_KEYNOTE_SOURCE_ROOT / "mod.rs"):
        full = root / path
        if not full.is_file():
            continue
        source = _mask_rust_non_code(full.read_text(encoding="utf-8"))
        for module in ("soundtrack_items", "soundtrack_wire"):
            for match in re.finditer(rf"^[ \t]*(?:pub(?:\([^()]*\))?[ \t\r\n]+)?mod[ \t\r\n]+(?:r#)?{module}\b", source, re.MULTILINE):
                line_number = source.count("\n", 0, match.start()) + 1
                violations.append(f"retired litchi-iwa Keynote soundtrack-item module {module}: {path}:{line_number}")
        for match in re.finditer(r"\bKeynoteSoundtrackItemInfo\b", source):
            line_number = source.count("\n", 0, match.start()) + 1
            violations.append(f"retired litchi-iwa Keynote soundtrack-item type re-export KeynoteSoundtrackItemInfo: {path}:{line_number}")
    return sorted(set(violations))


def audit_iwa_keynote_slide_transition_source_topology(
    root: Path = ROOT,
) -> list[str]:
    """Keep retired Keynote transition mutations out of their former host."""

    violations: list[str] = []
    for retired in RETIRED_IWA_KEYNOTE_SLIDE_TRANSITION_SOURCES:
        if (root / retired).exists():
            violations.append(
                "retired litchi-iwa Keynote slide-transition source returned: "
                + str(retired)
            )
    for retired in RETIRED_IWA_KEYNOTE_SLIDE_TRANSITION_EXAMPLES:
        if (root / retired).exists():
            violations.append(
                "retired litchi-iwa Keynote slide-transition example returned: "
                + str(retired)
            )

    source_root = root / IWA_KEYNOTE_SOURCE_ROOT
    if source_root.is_dir():
        for path in sorted(source_root.rglob("*.rs")):
            source = path.read_text(encoding="utf-8")
            for name, line_number in _rust_function_declarations(source):
                if name not in RETIRED_IWA_KEYNOTE_SLIDE_TRANSITION_METHOD_SET:
                    continue
                violations.append(
                    "retired litchi-iwa Keynote slide-transition method "
                    f"{name}: {path.relative_to(root)}:{line_number}"
                )

    editor_path = root / IWA_KEYNOTE_EDITOR_SOURCE
    if editor_path.is_file():
        raw_source = editor_path.read_text(encoding="utf-8")
        source = _mask_rust_non_code(raw_source)
        for match in IWA_KEYNOTE_SLIDE_TRANSITION_MODULE.finditer(source):
            line_number = source.count("\n", 0, match.start()) + 1
            violations.append(
                "retired litchi-iwa Keynote slide-transition module "
                f"{match.group(1)}: {IWA_KEYNOTE_EDITOR_SOURCE}:{line_number}"
            )

        # Transition projection and semantic conversion now belong to the
        # focused Package owner.  Keep the migration host from retaining a
        # second converter while the old module is being removed.  The scan
        # is production-only so test fixtures cannot satisfy or bypass the
        # ownership boundary.
        production_source = _mask_rust_non_code(
            _mask_rust_cfg_test_items(raw_source)
        )
        for match in IWA_KEYNOTE_SLIDE_TRANSITION_HOST_DUPLICATE_CONVERTER.finditer(
            production_source
        ):
            line_number = production_source.count("\n", 0, match.start()) + 1
            violations.append(
                "retired litchi-iwa Keynote slide-transition duplicate host "
                f"converter {match.group(0)}: "
                f"{IWA_KEYNOTE_EDITOR_SOURCE}:{line_number}"
            )
        for match in IWA_KEYNOTE_SLIDE_TRANSITION_HOST_CODEC_REFERENCE.finditer(
            production_source
        ):
            line_number = production_source.count("\n", 0, match.start()) + 1
            violations.append(
                "retired litchi-iwa Keynote slide-transition host codec reference: "
                f"{IWA_KEYNOTE_EDITOR_SOURCE}:{line_number}"
            )

        # Once the host reaches the transition surface, it must call the
        # feature-gated Package seam.  Check the seam's actual owner path and
        # signature marker so a similarly named host helper cannot satisfy the
        # ratchet.
        host_uses_transition_surface = bool(
            IWA_KEYNOTE_SLIDE_TRANSITION_HOST_DUPLICATE_CONVERTER.search(
                production_source
            )
            or IWA_KEYNOTE_SLIDE_TRANSITION_HOST_CODEC_REFERENCE.search(
                production_source
            )
            or IWA_KEYNOTE_SLIDE_TRANSITION_HOST_SEAM_REFERENCE.search(
                production_source
            )
        )
        if host_uses_transition_surface:
            if (
                IWA_KEYNOTE_SLIDE_TRANSITION_HOST_SEAM_REFERENCE.search(
                    production_source
                )
                is None
            ):
                violations.append(
                    "focused litchi-keynote Package transition source seam is not "
                    "used by the migration host: "
                    f"{IWA_KEYNOTE_EDITOR_SOURCE}"
                )
            else:
                package_path = root / KEYNOTE_SLIDE_TRANSITION_IMPLEMENTATION_SOURCES[1]
                package_source = (
                    _mask_rust_comments(package_path.read_text(encoding="utf-8"))
                    if package_path.is_file()
                    else ""
                )
                if (
                    not package_path.is_file()
                    or KEYNOTE_SLIDE_TRANSITION_HIDDEN_SOURCE_SEAM_DECLARATION.search(
                        package_source
                    )
                    is None
                ):
                    violations.append(
                        "focused litchi-keynote Package transition source seam is "
                        "missing or not feature-gated/hidden: "
                        f"{KEYNOTE_SLIDE_TRANSITION_IMPLEMENTATION_SOURCES[1]}"
                    )

    readme_path = root / IWA_KEYNOTE_README
    if readme_path.is_file():
        source = readme_path.read_text(encoding="utf-8")
        for pattern in IWA_KEYNOTE_README_SLIDE_TRANSITION_CALLS:
            for match in pattern.finditer(source):
                line_number = source.count("\n", 0, match.start("method")) + 1
                violations.append(
                    "retired litchi-iwa Keynote slide-transition README call "
                    f"{match.group('method')}: {IWA_KEYNOTE_README}:{line_number}"
                )
        for match in IWA_KEYNOTE_README_SLIDE_TRANSITION_EXAMPLE.finditer(source):
            line_number = source.count("\n", 0, match.start("example")) + 1
            violations.append(
                "retired litchi-iwa Keynote slide-transition README example reference "
                f"{match.group('example')}: {IWA_KEYNOTE_README}:{line_number}"
            )

    return sorted(set(violations))


def audit_keynote_slide_transition_facade_source_topology(
    root: Path = ROOT,
) -> list[str]:
    """Enforce the canonical nested, archive-free slide-transition API."""

    source_root = root / KEYNOTE_SOURCE_ROOT
    if not source_root.is_dir():
        return []
    dedicated_sources = {
        root / path
        for path in KEYNOTE_SLIDE_TRANSITION_IMPLEMENTATION_SOURCES
        if (root / path).is_file()
    }
    export_sources = {
        root / path
        for path in KEYNOTE_SLIDE_TRANSITION_EXPORT_SOURCES
        if (root / path).is_file()
    }
    semantic_source = root / KEYNOTE_SOURCE_ROOT / "transition.rs"
    violations: list[str] = []

    canonical_exports = (
        _rust_canonical_exports(
            semantic_source.read_text(encoding="utf-8"),
            KEYNOTE_SLIDE_TRANSITION_SHORT_NAMES,
        )
        if semantic_source.is_file()
        else frozenset()
    )
    for name in KEYNOTE_SLIDE_TRANSITION_CANONICAL_TYPES:
        if name in canonical_exports:
            continue
        violations.append(
            "focused litchi-keynote slide-transition public API is missing "
            f"canonical transition type {name}: "
            f"{KEYNOTE_SOURCE_ROOT / 'transition.rs'}"
        )

    lib_export = root / KEYNOTE_SOURCE_ROOT / "lib.rs"
    lib_source = (
        _mask_rust_non_code(lib_export.read_text(encoding="utf-8"))
        if lib_export.is_file()
        else ""
    )
    if PUBLIC_KEYNOTE_TRANSITION_MODULE.search(lib_source) is None:
        violations.append(
            "focused litchi-keynote slide-transition public API is missing "
            "canonical root transition module: "
            f"{KEYNOTE_SOURCE_ROOT / 'lib.rs'}"
        )

    package_export = root / KEYNOTE_SOURCE_ROOT / "package.rs"
    if package_export.is_file():
        package_source = _mask_rust_non_code(
            package_export.read_text(encoding="utf-8")
        )
        for match in PUBLIC_KEYNOTE_PACKAGE_SLIDE_TRANSITION_MODULE.finditer(
            package_source
        ):
            line_number = package_source.count("\n", 0, match.start()) + 1
            violations.append(
                "focused litchi-keynote slide-transition public API exposes duplicate "
                "package::slide_transition module: "
                f"{package_export.relative_to(root)}:{line_number}"
            )

    for path in sorted(dedicated_sources | export_sources):
        dedicated_source = path in dedicated_sources
        source = path.read_text(encoding="utf-8")
        declarations = [
            (declaration, line_number, True, dedicated_source)
            for declaration, line_number in _rust_public_declarations(source)
        ]
        if dedicated_source:
            declarations.extend(
                (declaration, line_number, False, False)
                for declaration, line_number in _rust_impl_headers(source)
            )
        for (
            declaration,
            line_number,
            public_declaration,
            complete_source_scope,
        ) in declarations:
            if not _is_keynote_slide_transition_public_declaration(
                declaration, dedicated_source=complete_source_scope
            ):
                continue
            # This feature-gated hidden method is the narrow migration seam
            # used by litchi-iwa.  Its bounded wire input is intentionally
            # private to that compatibility edge; the public semantic API
            # below still rejects the same vocabulary everywhere else.
            declaration_identifiers = {
                match.group(1) for match in RUST_IDENTIFIER.finditer(declaration)
            }
            if (
                path
                == root / KEYNOTE_SLIDE_TRANSITION_IMPLEMENTATION_SOURCES[1]
                and KEYNOTE_SLIDE_TRANSITION_HIDDEN_SOURCE_SEAM
                in declaration_identifiers
            ):
                continue
            owner_declaration = _keynote_slide_transition_owner_declaration(
                declaration
            )
            declaration_identifiers = [
                match.group(1) for match in RUST_IDENTIFIER.finditer(declaration)
            ]
            public_use_or_type = declaration_identifiers[:2] in (
                ["pub", "type"],
                ["pub", "use"],
            )
            if (
                public_declaration
                and path in export_sources
                and owner_declaration
                and declaration_identifiers[:2] == ["pub", "use"]
                and "*" in declaration
            ):
                violations.append(
                    "focused litchi-keynote slide-transition public API retains "
                    "root aliases via transition glob: "
                    f"{path.relative_to(root)}:{line_number}"
                )
            for match in RUST_IDENTIFIER.finditer(declaration):
                identifier = match.group(1)
                identifier_line = line_number + declaration.count(
                    "\n", 0, match.start(1)
                )
                if (
                    public_declaration
                    and identifier in KEYNOTE_SLIDE_TRANSITION_FLAT_ALIASES
                ):
                    violations.append(
                        "focused litchi-keynote slide-transition public API "
                        f"retains flat alias {identifier}: "
                        f"{path.relative_to(root)}:{identifier_line}"
                    )
                if (
                    public_declaration
                    and identifier
                    in KEYNOTE_SLIDE_TRANSITION_FORBIDDEN_PUBLIC_MEMBERS
                ):
                    violations.append(
                        "focused litchi-keynote slide-transition public API "
                        f"retains adapter-only public member {identifier}: "
                        f"{path.relative_to(root)}:{identifier_line}"
                    )
                if (
                    public_declaration
                    and path in export_sources
                    and owner_declaration
                    and public_use_or_type
                    and identifier in KEYNOTE_SLIDE_TRANSITION_ROOT_ALIASES
                ):
                    violations.append(
                        "focused litchi-keynote slide-transition public API "
                        f"retains root alias {identifier}: "
                        f"{path.relative_to(root)}:{identifier_line}"
                    )
                reason = _keynote_slide_transition_public_leak(
                    identifier, semantic_source=path == semantic_source
                )
                if reason is None:
                    continue
                violations.append(
                    "focused litchi-keynote slide-transition public API exposes "
                    f"{reason} {identifier}: "
                    f"{path.relative_to(root)}:{identifier_line}"
                )
            allow_opaque_payload = path == semantic_source and bool(
                set(declaration_identifiers)
                & KEYNOTE_SLIDE_TRANSITION_SEMANTIC_OPAQUE_PAYLOAD_MEMBERS
            )
            if allow_opaque_payload:
                continue
            for match in RUST_BYTE_SLICE.finditer(declaration):
                byte_slice = re.sub(r"\s+", "", match.group(0))
                byte_slice_line = line_number + declaration.count(
                    "\n", 0, match.start()
                )
                violations.append(
                    "focused litchi-keynote slide-transition public API exposes "
                    f"raw byte slice {byte_slice}: "
                    f"{path.relative_to(root)}:{byte_slice_line}"
                )

    return sorted(set(violations))


def audit_iwa_keynote_slide_background_source_topology(
    root: Path = ROOT,
) -> list[str]:
    """Keep the retired slide-background host surface out of ``litchi-iwa``.

    The focused Package crate is the sole owner of slide-background behavior.
    The old host adapter, its two test-only oracle modules, the former
    implementation files, public type re-exports, host methods, and removed
    tests are all deletion ratchets.  Comments and literals are masked, while
    production scans mask individual ``cfg(test)`` items where a test-only
    fixture is not part of the retired host surface itself.
    """

    violations: list[str] = []

    for retired in IWA_KEYNOTE_SLIDE_BACKGROUND_LEGACY_SOURCES:
        path = root / retired
        if not path.exists():
            continue
        violations.append(
            "retired litchi-iwa Keynote slide-background source returned: "
            + str(retired)
        )

    example = root / RETIRED_IWA_KEYNOTE_SLIDE_BACKGROUND_EXAMPLE
    if example.exists():
        violations.append(
            "retired litchi-iwa Keynote slide-background example returned: "
            + str(RETIRED_IWA_KEYNOTE_SLIDE_BACKGROUND_EXAMPLE)
        )

    editor_path = root / IWA_KEYNOTE_EDITOR_SOURCE
    if editor_path.is_file():
        # These names are deleted module declarations, including the two
        # modules that used to be cfg(test) oracles.  A cfg(test) attribute
        # therefore does not make their return legitimate; only comments and
        # literals are ignored here.
        source = _mask_rust_non_code(editor_path.read_text(encoding="utf-8"))
        for match in IWA_KEYNOTE_SLIDE_BACKGROUND_MODULE.finditer(source):
            module = match.group("module")
            line_number = source.count("\n", 0, match.start()) + 1
            violations.append(
                "retired litchi-iwa Keynote slide-background module "
                f"{module}: {IWA_KEYNOTE_EDITOR_SOURCE}:{line_number}"
            )

        editor_production = _mask_rust_non_code(
            _mask_rust_cfg_test_items(editor_path.read_text(encoding="utf-8"))
        )
        for declaration, declaration_line in _rust_public_declarations(
            editor_production
        ):
            if not re.search(r"\bpub[ \t\r\n]+use\b", declaration):
                continue
            for identifier in RUST_IDENTIFIER.finditer(declaration):
                name = identifier.group(1)
                if name not in RETIRED_IWA_KEYNOTE_SLIDE_BACKGROUND_REEXPORT_SET:
                    continue
                line_number = declaration_line + declaration.count(
                    "\n", 0, identifier.start(1)
                )
                violations.append(
                    "retired litchi-iwa Keynote slide-background re-export "
                    f"{name}: {IWA_KEYNOTE_EDITOR_SOURCE}:{line_number}"
                )

    source_root = root / IWA_KEYNOTE_SOURCE_ROOT
    if source_root.is_dir():
        for path in sorted(source_root.rglob("*.rs")):
            if path == root / IWA_KEYNOTE_EDITOR_TEST_SOURCE:
                continue
            raw_source = path.read_text(encoding="utf-8")
            production_code = _mask_rust_non_code(
                _mask_rust_cfg_test_items(raw_source)
            )
            for match in re.finditer(
                r"(?<![A-Za-z0-9_])(?:"
                + "|".join(
                    re.escape(name)
                    for name in sorted(IWA_KEYNOTE_SLIDE_BACKGROUND_MODULE_NAMES)
                )
                + r")(?![A-Za-z0-9_])",
                production_code,
            ):
                line_number = production_code.count("\n", 0, match.start()) + 1
                violations.append(
                    "retired litchi-iwa Keynote slide-background production "
                    f"reference {match.group(0)}: {path.relative_to(root)}:{line_number}"
                )

        # Method names are retired on the host only.  Calls to the same names
        # on ``litchi-keynote::Package`` live in another crate and remain
        # valid; scanning declarations avoids mistaking those focused calls
        # for the deleted host API.
        for path in sorted(source_root.rglob("*.rs")):
            if path == root / IWA_KEYNOTE_EDITOR_TEST_SOURCE:
                continue
            production = _mask_rust_cfg_test_items(
                path.read_text(encoding="utf-8")
            )
            for name, line_number in _rust_function_declarations(production):
                if name not in RETIRED_IWA_KEYNOTE_SLIDE_BACKGROUND_METHOD_SET:
                    continue
                violations.append(
                    "retired litchi-iwa Keynote slide-background host method "
                    f"{name}: {path.relative_to(root)}:{line_number}"
                )

    # The old integration tests were part of the host surface too.  Keep an
    # exact-name inventory so a renamed or copied test cannot silently revive
    # those assumptions.  Test-only cfg attributes do not exempt a removed
    # test, but comments and strings are ignored by the declaration scanner.
    test_path = root / IWA_KEYNOTE_EDITOR_TEST_SOURCE
    if test_path.is_file():
        for name, line_number in _rust_function_declarations(
            test_path.read_text(encoding="utf-8")
        ):
            if name not in RETIRED_IWA_KEYNOTE_SLIDE_BACKGROUND_TEST_SET:
                continue
            violations.append(
                "retired litchi-iwa Keynote slide-background test "
                f"{name}: {IWA_KEYNOTE_EDITOR_TEST_SOURCE}:{line_number}"
            )

    return sorted(set(violations))


def audit_keynote_slide_background_facade_source_topology(
    root: Path = ROOT,
) -> list[str]:
    """Enforce selector-first focused Keynote slide-background ownership."""

    source_root = root / KEYNOTE_SOURCE_ROOT
    if not source_root.is_dir():
        return []

    violations: list[str] = []
    package_path = root / KEYNOTE_SLIDE_BACKGROUND_EXPORT_SOURCES[1]
    package_source = (
        _mask_rust_non_code(package_path.read_text(encoding="utf-8"))
        if package_path.is_file()
        else ""
    )
    if not package_path.is_file():
        violations.append(
            "focused litchi-keynote slide-background public API is missing "
            f"package owner module: {KEYNOTE_SLIDE_BACKGROUND_EXPORT_SOURCES[1]}"
        )
    elif KEYNOTE_PACKAGE_SLIDE_BACKGROUND_MODULE.search(package_source) is None:
        violations.append(
            "focused litchi-keynote slide-background public API is missing "
            f"private package owner module: {KEYNOTE_SLIDE_BACKGROUND_EXPORT_SOURCES[1]}"
        )
    for match in PUBLIC_KEYNOTE_PACKAGE_SLIDE_BACKGROUND_MODULE.finditer(
        package_source
    ):
        line_number = package_source.count("\n", 0, match.start()) + 1
        violations.append(
            "focused litchi-keynote slide-background public API exposes duplicate "
            "package::slide_background module: "
            f"{KEYNOTE_SLIDE_BACKGROUND_EXPORT_SOURCES[1]}:{line_number}"
        )

    owner_path = root / KEYNOTE_SLIDE_BACKGROUND_OWNER_SOURCE
    if not owner_path.is_file():
        violations.append(
            "focused litchi-keynote slide-background public API is missing private "
            f"package owner source: {KEYNOTE_SLIDE_BACKGROUND_OWNER_SOURCE}"
        )
        owner_source = ""
    else:
        owner_source = owner_path.read_text(encoding="utf-8")

    owner_public_methods = {
        name
        for declaration, _line_number in _rust_public_declarations(owner_source)
        for name, _nested_line in _rust_function_declarations(declaration)
    }
    for method in KEYNOTE_SLIDE_BACKGROUND_PACKAGE_METHODS:
        if method in owner_public_methods:
            continue
        violations.append(
            "focused litchi-keynote slide-background public API is missing Package "
            f"method {method}: {KEYNOTE_SLIDE_BACKGROUND_OWNER_SOURCE}"
        )

    for method in KEYNOTE_SLIDE_BACKGROUND_EDIT_METHODS:
        if method in owner_public_methods:
            continue
        violations.append(
            "focused litchi-keynote slide-background public API is missing "
            f"Edit method {method}: {KEYNOTE_SLIDE_BACKGROUND_OWNER_SOURCE}"
        )

    # Keep the owner and semantic value source free of generated Prost reads;
    # cfg(test) differential helpers remain legal through item masking.
    for path in (
        root / KEYNOTE_SLIDE_BACKGROUND_IMPLEMENTATION_SOURCES[0],
        owner_path,
    ):
        if not path.is_file():
            continue
        raw_source = path.read_text(encoding="utf-8")
        production_code = _mask_rust_non_code(
            _mask_rust_cfg_test_items(raw_source)
        )
        for label, pattern in KEYNOTE_NO_EAGER_PROST_SOURCE_PATTERNS:
            for match in pattern.finditer(production_code):
                line_number = production_code.count("\n", 0, match.start()) + 1
                violations.append(
                    "focused litchi-keynote slide-background production source uses "
                    f"{label}: {path.relative_to(root)}:{line_number}"
                )

    return sorted(set(violations))


