def _pages_table_hidden_axes_example_is_pages(
    path: Path, source: str, match_start: int
) -> bool:
    """Identify Pages branches before applying the hidden-axis retirement."""

    stem = path.stem.lower()
    # Shared examples intentionally keep Numbers and Keynote hidden-axis
    # compatibility.  A mixed filename is a Pages example only when it says
    # so explicitly; a Numbers/Keynote-only filename is never Pages traffic.
    line_start = source.rfind("\n", 0, match_start) + 1
    line_end = source.find("\n", match_start)
    if line_end < 0:
        line_end = len(source)
    line = source[line_start:line_end].lower()
    if any(token in line for token in ("numbers", "keynote")) and not any(
        token in line for token in ("pages", "pageseditor", "pages_editor")
    ):
        return False
    if "pages" in line or "pageseditor" in line or "pages_editor" in line:
        return True
    function_matches = list(
        re.finditer(
            r"\bfn\s+(?:r#)?([A-Za-z_][A-Za-z0-9_]*)\b",
            source[:match_start],
        )
    )
    if not function_matches:
        return "pages" in stem and not ("numbers" in stem or "keynote" in stem)
    function_name = function_matches[-1].group(1).lower()
    if "numbers" in function_name or "keynote" in function_name:
        return False
    if "pages" in function_name:
        return True
    if "numbers" in stem or "keynote" in stem:
        return False
    return "pages" in stem


def audit_iwa_pages_table_hidden_axes_source_topology(
    root: Path = ROOT,
) -> list[str]:
    """Keep the Pages hidden-axis migration-host debt explicit.

    The focused owner is selector-first and archive free, but it currently
    refuses to create the native hidden-state closure for source-built Pages
    tables.  Until the native changed-edit gate closes, the raw-ID
    ``PagesEditor`` route, its test coverage, and the mixed iWork example are
    required compatibility paths.  The host route must continue to use the
    shared executor, while the focused owner remains terminal and cannot call
    back into this compatibility seam.
    """

    # Until the complete focused owner is wired, the compatibility host is a
    # deliberate migration baseline.  This gate also avoids reporting a
    # partially assembled package from a concurrent source migration.
    if not _pages_table_hidden_axes_owner_present(root):
        return []
    # Once the focused native receipt and semantic parity tests are present,
    # the old retention requirements (host module, host tests, and example)
    # must stop blocking the retirement ratchet below.  That ratchet performs
    # the stricter residue scan and keeps the shared Numbers/Keynote helper
    # checks alive.
    if _pages_table_hidden_axes_retirement_evidence_ready(root):
        return []

    violations: list[str] = []

    host_route_path = root / IWA_PAGES_TABLE_HIDDEN_AXES_HOST_SOURCE
    if not host_route_path.is_file():
        violations.append(
            "retained litchi-iwa Pages table-hidden-axes migration-host source is missing: "
            f"{IWA_PAGES_TABLE_HIDDEN_AXES_HOST_SOURCE}"
        )
    else:
        host_source = _mask_rust_cfg_test_items(
            host_route_path.read_text(encoding="utf-8")
        )
        host_code = _mask_rust_non_code(host_source)
        for method in IWA_PAGES_TABLE_HIDDEN_AXES_HOST_METHODS:
            declaration = re.search(
                rf"(?m)^[ \t]*(?:pub(?:\([^()]*\))?[ \t\r\n]+)?"
                rf"fn[ \t\r\n]+(?:r#)?{re.escape(method)}\b"
                rf"(?P<signature>[^{{;]*)",
                host_code,
            )
            if declaration is None:
                violations.append(
                    "retained litchi-iwa Pages table-hidden-axes migration-host method "
                    f"{method} is missing: {IWA_PAGES_TABLE_HIDDEN_AXES_HOST_SOURCE}"
                )
            elif re.search(
                r"\bmodel_object_id[ \t\r\n]*:[ \t\r\n]*u64\b",
                declaration.group("signature"),
            ) is None:
                line_number = host_code.count("\n", 0, declaration.start()) + 1
                violations.append(
                    "retained litchi-iwa Pages table-hidden-axes migration-host method "
                    f"{method} must retain raw model_object_id: u64: "
                    f"{IWA_PAGES_TABLE_HIDDEN_AXES_HOST_SOURCE}:{line_number}"
                )

        for method in IWA_PAGES_TABLE_HIDDEN_AXES_HOST_METHODS:
            if re.search(
                rf"\bcrate[ \t\r\n]*::[ \t\r\n]*table_hidden_axes"
                rf"[ \t\r\n]*::[ \t\r\n]*{re.escape(method)}\b"
                rf"[ \t\r\n]*\(",
                host_code,
            ) is None:
                violations.append(
                    "retained litchi-iwa Pages table-hidden-axes migration-host method "
                    f"{method} must call the shared table-hidden-axes executor: "
                    f"{IWA_PAGES_TABLE_HIDDEN_AXES_HOST_SOURCE}"
                )

        # A host compatibility route may remain while the focused owner is
        # incomplete, but it must not quietly delegate every refusal back to
        # that owner.  Keep this check on executable source so the retained
        # documentation can explain the migration debt without tripping it.
        for pattern in PAGES_TABLE_HIDDEN_AXES_FOCUSED_FALLBACK_PATTERNS[:2]:
            match = pattern.search(host_code)
            if match is None:
                continue
            line_number = host_code.count("\n", 0, match.start()) + 1
            violations.append(
                "retained litchi-iwa Pages table-hidden-axes migration-host route must not "
                "fallback through the focused litchi-pages facade: "
                f"{IWA_PAGES_TABLE_HIDDEN_AXES_HOST_SOURCE}:{line_number}"
            )

    tables_module = root / IWA_PAGES_TABLES_MODULE_SOURCE
    if not tables_module.is_file():
        violations.append(
            "retained litchi-iwa Pages table-hidden-axes migration-host module is missing: "
            f"{IWA_PAGES_TABLES_MODULE_SOURCE}"
        )
    else:
        module_code = _mask_rust_non_code(
            _mask_rust_cfg_test_items(tables_module.read_text(encoding="utf-8"))
        )
        if IWA_PAGES_TABLE_HIDDEN_AXES_MODULE.search(module_code) is None:
            violations.append(
                "retained litchi-iwa Pages table-hidden-axes migration-host module "
                f"declaration is missing: {IWA_PAGES_TABLES_MODULE_SOURCE}"
            )
        elif re.search(
            r"(?m)^\s*pub(?:\([^()]*\))?[ \t\r\n]+mod[ \t\r\n]+"
            r"(?:r#)?hidden_axes\b",
            module_code,
        ):
            violations.append(
                "retained litchi-iwa Pages table-hidden-axes migration-host module "
                f"must remain private: {IWA_PAGES_TABLES_MODULE_SOURCE}"
            )

    host_test_path = root / IWA_PAGES_TABLE_HIDDEN_AXES_HOST_TEST_SOURCE
    if not host_test_path.is_file():
        violations.append(
            "retained litchi-iwa Pages table-hidden-axes migration-host test source is missing: "
            f"{IWA_PAGES_TABLE_HIDDEN_AXES_HOST_TEST_SOURCE}"
        )
    else:
        host_test_code = _mask_rust_non_code(
            host_test_path.read_text(encoding="utf-8")
        )
        if re.search(r"(?m)#\s*\[\s*test\s*\]", host_test_code) is None:
            violations.append(
                "retained litchi-iwa Pages table-hidden-axes migration-host test source "
                f"is missing #[test] coverage: {IWA_PAGES_TABLE_HIDDEN_AXES_HOST_TEST_SOURCE}"
            )
        for method in IWA_PAGES_TABLE_HIDDEN_AXES_HOST_METHODS:
            if re.search(
                rf"(?<![A-Za-z0-9_#])(?:r#)?{re.escape(method)}\b"
                rf"[ \t\r\n]*\(",
                host_test_code,
            ) is None:
                violations.append(
                    "retained litchi-iwa Pages table-hidden-axes migration-host test source "
                    f"must exercise {method}: {IWA_PAGES_TABLE_HIDDEN_AXES_HOST_TEST_SOURCE}"
                )
    shared_helper = root / PAGES_TABLE_HIDDEN_AXES_SHARED_HELPER_SOURCE
    if not shared_helper.is_file():
        violations.append(
            "shared Numbers/Keynote table-hidden-axes helper is missing: "
            f"{PAGES_TABLE_HIDDEN_AXES_SHARED_HELPER_SOURCE}"
        )
    else:
        shared_code = _mask_rust_non_code(
            shared_helper.read_text(encoding="utf-8")
        )
        for marker in PAGES_TABLE_HIDDEN_AXES_SHARED_HELPER_REQUIRED_MARKERS:
            if re.search(
                rf"\bfn[ \t\r\n]+(?:r#)?{re.escape(marker)}\b",
                shared_code,
            ):
                continue
            violations.append(
                "shared Numbers/Keynote table-hidden-axes helper is missing "
                f"{marker}: {PAGES_TABLE_HIDDEN_AXES_SHARED_HELPER_SOURCE}"
            )
    for host, host_path in (
        ("Numbers", PAGES_TABLE_HIDDEN_AXES_NUMBERS_HOST_SOURCE),
        ("Keynote", PAGES_TABLE_HIDDEN_AXES_KEYNOTE_HOST_SOURCE),
    ):
        absolute_host = root / host_path
        if not absolute_host.is_file():
            violations.append(
                f"{host} table-hidden-axes host route is missing its shared-helper adapter: "
                f"{host_path}"
            )
            continue
        host_code = _mask_rust_non_code(
            absolute_host.read_text(encoding="utf-8")
        )
        if PAGES_TABLE_HIDDEN_AXES_SHARED_IMPORT.search(host_code) is None:
            violations.append(
                f"{host} table-hidden-axes host must retain the shared helper import: "
                f"{host_path}"
            )

    source_root = root / IWA_PAGES_SOURCE_ROOT
    if source_root.is_dir():
        for path in sorted(source_root.rglob("*.rs")):
            # The canonical host source and the outer test module are the
            # retained migration-host route.  Production siblings must not
            # grow another raw-ID implementation or bypass the one shared
            # executor.
            if (
                path == host_route_path
                or path == host_test_path
                or path.name == "tests.rs"
            ):
                continue
            raw = path.read_text(encoding="utf-8")
            source = _mask_rust_cfg_test_items(raw)
            code = _mask_rust_non_code(source)
            for name, line_number in _rust_function_declarations(source):
                if name not in IWA_PAGES_TABLE_HIDDEN_AXES_HOST_METHOD_SET:
                    continue
                violations.append(
                    "duplicate litchi-iwa Pages table-hidden-axes migration-host method "
                    f"{name}: {path.relative_to(root)}:{line_number}"
                )
            for pattern in IWA_PAGES_TABLE_HIDDEN_AXES_IMPORTS:
                for match in pattern.finditer(code):
                    line_number = code.count("\n", 0, match.start()) + 1
                    violations.append(
                        "duplicate litchi-iwa Pages table-hidden-axes migration-host import: "
                        f"{path.relative_to(root)}:{line_number}"
                    )
            for match in IWA_PAGES_TABLE_HIDDEN_AXES_CALL.finditer(code):
                method = match.group("method")
                line_number = code.count("\n", 0, match.start("method")) + 1
                violations.append(
                    "duplicate litchi-iwa Pages table-hidden-axes migration-host call "
                    f"{method}: {path.relative_to(root)}:{line_number}"
                )

    # Examples are shared by all three iWork hosts.  The mixed example must
    # retain its Pages branch while Numbers and Keynote branches remain
    # outside this Pages debt check.  Other Pages examples must not become a
    # second compatibility recommendation.
    example_root = root / IWA_PAGES_TABLE_HIDDEN_AXES_EXAMPLE_ROOT
    retained_example_path = root / IWA_PAGES_TABLE_HIDDEN_AXES_HOST_EXAMPLE
    if not retained_example_path.is_file():
        violations.append(
            "retained litchi-iwa Pages table-hidden-axes migration-host example is missing: "
            f"{IWA_PAGES_TABLE_HIDDEN_AXES_HOST_EXAMPLE}"
        )
    if example_root.is_dir():
        for example_path in sorted(example_root.rglob("*.rs")):
            source = _mask_rust_cfg_test_items(
                example_path.read_text(encoding="utf-8")
            )
            code = _mask_rust_non_code(source)
            is_retained_example = example_path == retained_example_path
            pages_matches = []
            for match in IWA_PAGES_TABLE_HIDDEN_AXES_CALL.finditer(code):
                if _pages_table_hidden_axes_example_is_pages(
                    example_path, code, match.start()
                ):
                    pages_matches.append(match)
                    if not is_retained_example:
                        line_number = code.count(
                            "\n", 0, match.start("method")
                        ) + 1
                        violations.append(
                            "duplicate litchi-iwa Pages table-hidden-axes migration-host "
                            f"example call {match.group('method')}: "
                            f"{example_path.relative_to(root)}:{line_number}"
                        )
            if is_retained_example:
                if not pages_matches:
                    violations.append(
                        "retained litchi-iwa Pages table-hidden-axes migration-host example "
                        f"is missing a Pages branch: {IWA_PAGES_TABLE_HIDDEN_AXES_HOST_EXAMPLE}"
                    )
                for method in IWA_PAGES_TABLE_HIDDEN_AXES_HOST_METHODS:
                    if not any(match.group("method") == method for match in pages_matches):
                        violations.append(
                            "retained litchi-iwa Pages table-hidden-axes migration-host example "
                            f"must exercise {method}: {IWA_PAGES_TABLE_HIDDEN_AXES_HOST_EXAMPLE}"
                        )
            for pattern in IWA_PAGES_TABLE_HIDDEN_AXES_IMPORTS:
                for match in pattern.finditer(code):
                    if is_retained_example or not _pages_table_hidden_axes_example_is_pages(
                        example_path, code, match.start()
                    ):
                        continue
                    line_number = code.count("\n", 0, match.start()) + 1
                    violations.append(
                        "duplicate litchi-iwa Pages table-hidden-axes migration-host "
                        "example import: "
                        f"{example_path.relative_to(root)}:{line_number}"
                    )

    return sorted(set(violations))


audit_iwa_pages_body_table_hidden_axes_source_topology = (
    audit_iwa_pages_table_hidden_axes_source_topology
)


def audit_iwa_pages_table_hidden_axes_retirement_source_topology(
    root: Path = ROOT,
) -> list[str]:
    """Retire only the Pages raw-ID hidden-axis compatibility route.

    This audit activates after the focused Pages owner, semantic tests, and
    focused native save/reopen receipt all exist.  It scans the Pages host
    and Pages branches of shared examples for the two retired methods while
    deliberately leaving the common helper and the Numbers/Keynote adapters
    outside its source roots.
    """

    if not _pages_table_hidden_axes_retirement_evidence_ready(root):
        return []

    violations: list[str] = []
    shared_helper = root / PAGES_TABLE_HIDDEN_AXES_SHARED_HELPER_SOURCE
    if not shared_helper.is_file():
        violations.append(
            "shared Numbers/Keynote table-hidden-axes helper is missing after Pages retirement: "
            f"{PAGES_TABLE_HIDDEN_AXES_SHARED_HELPER_SOURCE}"
        )
    else:
        shared_code = _mask_rust_non_code(
            shared_helper.read_text(encoding="utf-8")
        )
        for marker in PAGES_TABLE_HIDDEN_AXES_SHARED_HELPER_REQUIRED_MARKERS:
            if re.search(
                rf"\bfn[ \t\r\n]+(?:r#)?{re.escape(marker)}\b",
                shared_code,
            ) is None:
                violations.append(
                    "shared Numbers/Keynote table-hidden-axes helper is missing "
                    f"{marker} after Pages retirement: "
                    f"{PAGES_TABLE_HIDDEN_AXES_SHARED_HELPER_SOURCE}"
                )
    for host, host_path in (
        ("Numbers", PAGES_TABLE_HIDDEN_AXES_NUMBERS_HOST_SOURCE),
        ("Keynote", PAGES_TABLE_HIDDEN_AXES_KEYNOTE_HOST_SOURCE),
    ):
        absolute_host = root / host_path
        if not absolute_host.is_file():
            violations.append(
                f"{host} table-hidden-axes host route is missing its shared-helper adapter "
                f"after Pages retirement: {host_path}"
            )
            continue
        host_code = _mask_rust_non_code(
            absolute_host.read_text(encoding="utf-8")
        )
        if PAGES_TABLE_HIDDEN_AXES_SHARED_IMPORT.search(host_code) is None:
            violations.append(
                f"{host} table-hidden-axes host must retain the shared helper import "
                f"after Pages retirement: {host_path}"
            )

    def scan_pages_source(path: Path) -> None:
        raw = path.read_text(encoding="utf-8")
        source = _mask_rust_non_code(raw)
        relative = path.relative_to(root)
        for name, line_number in _rust_function_declarations(source):
            if name in RETIRED_IWA_PAGES_TABLE_HIDDEN_AXES_METHOD_SET:
                violations.append(
                    "retired litchi-iwa Pages table-hidden-axes migration-host method "
                    f"{name}: {relative}:{line_number}"
                )
        for match in IWA_PAGES_TABLE_HIDDEN_AXES_MODULE.finditer(source):
            line_number = source.count("\n", 0, match.start()) + 1
            violations.append(
                "retired litchi-iwa Pages table-hidden-axes migration-host module "
                f"returned: {relative}:{line_number}"
            )
        for pattern in IWA_PAGES_TABLE_HIDDEN_AXES_IMPORTS:
            # The retained host test file may keep semantic ``AxisIndex`` and
            # ``HiddenAxes`` imports for the source-built focused transaction.
            # Legacy method calls in that file are still scanned below, but a
            # generic axis import alone is not a migration-host dependency.
            if path == root / IWA_PAGES_TABLE_HIDDEN_AXES_HOST_TEST_SOURCE:
                continue
            for match in pattern.finditer(source):
                line_number = source.count("\n", 0, match.start()) + 1
                violations.append(
                    "retired litchi-iwa Pages table-hidden-axes migration-host import "
                    f"returned: {relative}:{line_number}"
                )
        for match in PAGES_TABLE_HIDDEN_AXES_RETIREMENT_REEXPORT.finditer(source):
            line_number = source.count("\n", 0, match.start()) + 1
            violations.append(
                "retired litchi-iwa Pages table-hidden-axes migration-host re-export "
                f"returned: {relative}:{line_number}"
            )
        for match in IWA_PAGES_TABLE_HIDDEN_AXES_CALL.finditer(source):
            line_start = source.rfind("\n", 0, match.start()) + 1
            line_end = source.find("\n", match.end())
            line_end = len(source) if line_end < 0 else line_end
            line = source[line_start:line_end]
            if re.search(
                rf"\bfn[ \t\r\n]+{re.escape(match.group('method'))}\b", line
            ):
                continue
            line_number = source.count("\n", 0, match.start("method")) + 1
            violations.append(
                "retired litchi-iwa Pages table-hidden-axes migration-host call "
                f"{match.group('method')}: {relative}:{line_number}"
            )

    source_root = root / IWA_PAGES_SOURCE_ROOT
    if source_root.is_dir():
        for path in sorted(source_root.rglob("*.rs")):
            scan_pages_source(path)

    example_root = root / IWA_PAGES_TABLE_HIDDEN_AXES_EXAMPLE_ROOT
    if example_root.is_dir():
        for path in sorted(example_root.rglob("*.rs")):
            raw = path.read_text(encoding="utf-8")
            source = _mask_rust_non_code(raw)
            relative = path.relative_to(root)
            for match in IWA_PAGES_TABLE_HIDDEN_AXES_CALL.finditer(source):
                if not _pages_table_hidden_axes_example_is_pages(
                    path, source, match.start()
                ):
                    continue
                line_number = source.count("\n", 0, match.start("method")) + 1
                violations.append(
                    "retired litchi-iwa Pages table-hidden-axes migration-host example "
                    f"call {match.group('method')}: {relative}:{line_number}"
                )
            for pattern in IWA_PAGES_TABLE_HIDDEN_AXES_IMPORTS:
                for match in pattern.finditer(source):
                    if not _pages_table_hidden_axes_example_is_pages(
                        path, source, match.start()
                    ):
                        continue
                    line_number = source.count("\n", 0, match.start()) + 1
                    violations.append(
                        "retired litchi-iwa Pages table-hidden-axes migration-host "
                        f"example import: {relative}:{line_number}"
                    )

    return sorted(set(violations))


def _pages_table_sort_owner_present(root: Path) -> bool:
    owner_path = root / PAGES_TABLE_SORT_OWNER_SOURCE
    package_path = root / PAGES_TABLE_SORT_EXPORT_SOURCES[1]
    package_source = (
        _mask_rust_non_code(package_path.read_text(encoding="utf-8"))
        if package_path.is_file()
        else ""
    )
    return owner_path.is_file() and (
        PAGES_PACKAGE_TABLE_SORT_MODULE.search(package_source) is not None
    )


def audit_iwa_pages_table_sort_source_topology(root: Path = ROOT) -> list[str]:
    """Retire only the persisted Pages table-sort configuration surface.

    The host's ``apply_table_sort_order`` and
    ``apply_table_sort_order_to_rows`` methods remain physical executors: they
    reorder body rows and therefore stay in ``litchi-iwa``.  Read/set/clear
    configuration belongs to the selector-first Pages package owner.  The
    audit is gated on that owner so the existing host remains a migration
    baseline until the package transaction is actually present.
    """

    if not _pages_table_sort_owner_present(root):
        return []

    violations: list[str] = []
    source_root = root / IWA_PAGES_SOURCE_ROOT
    call_pattern = re.compile(
        r"(?<![A-Za-z0-9_#])(?:r#)?(?P<method>table_sort_order|"
        r"set_table_sort_order|clear_table_sort_order)\b[ \t\r\n]*\(",
    )
    if source_root.is_dir():
        for path in sorted(source_root.rglob("*.rs")):
            source = _mask_rust_cfg_test_items(path.read_text(encoding="utf-8"))
            code = _mask_rust_non_code(source)
            for name, line_number in _rust_function_declarations(source):
                if name in RETIRED_IWA_PAGES_TABLE_SORT_METHOD_SET:
                    violations.append(
                        "retired litchi-iwa Pages table-sort method "
                        f"{name}: {path.relative_to(root)}:{line_number}"
                    )
            for pattern in IWA_PAGES_TABLE_SORT_IMPORTS:
                for match in pattern.finditer(code):
                    line_number = code.count("\n", 0, match.start()) + 1
                    violations.append(
                        "retired litchi-iwa Pages table-sort import: "
                        f"{path.relative_to(root)}:{line_number}"
                    )
            for match in call_pattern.finditer(code):
                line_start = code.rfind("\n", 0, match.start()) + 1
                line_end = code.find("\n", match.end())
                if line_end < 0:
                    line_end = len(code)
                line = code[line_start:line_end]
                if re.search(
                    rf"\bfn[ \t\r\n]+{re.escape(match.group('method'))}\b",
                    line,
                ):
                    continue
                line_number = code.count("\n", 0, match.start("method")) + 1
                violations.append(
                    "retired litchi-iwa Pages table-sort call "
                    f"{match.group('method')}: {path.relative_to(root)}:{line_number}"
                )

    example_root = root / IWA_PAGES_TABLE_SORT_EXAMPLE_ROOT
    if example_root.is_dir():
        for example_path in sorted(example_root.rglob("*.rs")):
            # The shared examples intentionally retain Numbers and Keynote
            # adapters.  Only Pages examples are in this host retirement.
            stem = example_path.stem.lower()
            if ("numbers" in stem or "keynote" in stem) and "pages" not in stem:
                continue
            source = _mask_rust_non_code(
                _mask_rust_cfg_test_items(example_path.read_text(encoding="utf-8"))
            )
            for match in call_pattern.finditer(source):
                line_number = source.count("\n", 0, match.start("method")) + 1
                violations.append(
                    "retired litchi-iwa Pages table-sort example call "
                    f"{match.group('method')}: {example_path.relative_to(root)}:{line_number}"
                )

    readme_path = root / IWA_PAGES_README
    if readme_path.is_file():
        source = readme_path.read_text(encoding="utf-8")
        for pattern in IWA_PAGES_README_TABLE_SORT_CALLS:
            for match in pattern.finditer(source):
                line_number = source.count("\n", 0, match.start("method")) + 1
                violations.append(
                    "retired litchi-iwa Pages table-sort README call "
                    f"{match.group('method')}: {IWA_PAGES_README}:{line_number}"
                )

    return sorted(set(violations))


def audit_pages_table_sort_facade_source_topology(root: Path = ROOT) -> list[str]:
    """Enforce the selector-first, archive-free Pages table-sort owner."""

    source_root = root / PAGES_SOURCE_ROOT
    if not source_root.is_dir() or not _pages_table_sort_owner_present(root):
        return []

    violations: list[str] = []
    semantic_path = root / PAGES_TABLE_SORT_SEMANTIC_SOURCE
    semantic_source = (
        _mask_rust_cfg_test_items(semantic_path.read_text(encoding="utf-8"))
        if semantic_path.is_file()
        else ""
    )
    semantic_exports = _rust_canonical_exports(
        semantic_source, frozenset(PAGES_TABLE_SORT_SEMANTIC_TYPES)
    )
    for name in PAGES_TABLE_SORT_SEMANTIC_TYPES:
        if name not in semantic_exports:
            violations.append(
                "focused litchi-pages table-sort public API is missing "
                f"semantic table::sort type {name}: {PAGES_TABLE_SORT_SEMANTIC_SOURCE}"
            )
    if PUBLIC_PAGES_TABLE_SORT_TRANSACTION_MODULE.search(
        _mask_rust_non_code(semantic_source)
    ) is None:
        violations.append(
            "focused litchi-pages table-sort public API is missing canonical "
            f"table::sort::transaction module: {PAGES_TABLE_SORT_SEMANTIC_SOURCE}"
        )

    selector_path = root / PAGES_TABLE_SORT_SELECTOR_SOURCE
    selector_source = (
        _mask_rust_non_code(selector_path.read_text(encoding="utf-8"))
        if selector_path.is_file()
        else ""
    )
    if "BodyTableSelector" not in _rust_canonical_exports(
        selector_source, frozenset({"BodyTableSelector"})
    ):
        violations.append(
            "focused litchi-pages table-sort public API is missing canonical "
            f"BodyTableSelector: {PAGES_TABLE_SORT_SELECTOR_SOURCE}"
        )

    owner_path = root / PAGES_TABLE_SORT_OWNER_SOURCE
    owner_source = (
        _mask_rust_cfg_test_items(owner_path.read_text(encoding="utf-8"))
        if owner_path.is_file()
        else ""
    )
    owner_exports = _rust_canonical_exports(
        owner_source, frozenset(PAGES_TABLE_SORT_CANONICAL_TYPES)
    )
    for name in PAGES_TABLE_SORT_CANONICAL_TYPES:
        if name not in owner_exports:
            violations.append(
                "focused litchi-pages table-sort public API is missing "
                f"canonical package type {name}: {PAGES_TABLE_SORT_OWNER_SOURCE}"
            )
    owner_methods = {
        name: declaration
        for name, declaration, _line_number in _rust_public_methods_in_impl(
            owner_source, "Package"
        )
    }
    for method in PAGES_TABLE_SORT_PACKAGE_METHODS:
        declaration = owner_methods.get(method)
        if declaration is None:
            violations.append(
                "focused litchi-pages table-sort public API is missing "
                f"Package method {method}: {PAGES_TABLE_SORT_OWNER_SOURCE}"
            )
            continue
        if method != "apply_body_table_sort_order":
            if "BodyTableSelector" not in declaration:
                violations.append(
                    "focused litchi-pages table-sort Package method "
                    f"{method} must accept selector-first BodyTableSelector: "
                    f"{PAGES_TABLE_SORT_OWNER_SOURCE}"
                )
    for method in sorted(PAGES_TABLE_SORT_FLAT_METHODS & owner_methods.keys()):
        violations.append(
            "focused litchi-pages table-sort public API retains flat Package method "
            f"{method}: {PAGES_TABLE_SORT_OWNER_SOURCE}"
        )
    owner_code = _mask_rust_non_code(owner_source)
    for label, marker in PAGES_TABLE_SORT_OWNER_REQUIRED_MARKERS.items():
        if marker.search(owner_code) is None:
            violations.append(
                "focused litchi-pages table-sort owner is missing "
                f"{label} transaction marker: {PAGES_TABLE_SORT_OWNER_SOURCE}"
            )

    lib_path = root / PAGES_TABLE_SORT_EXPORT_SOURCES[0]
    lib_source = (
        _mask_rust_non_code(lib_path.read_text(encoding="utf-8"))
        if lib_path.is_file()
        else ""
    )
    if PUBLIC_PAGES_TABLE_MODULE.search(lib_source) is None:
        violations.append(
            "focused litchi-pages table-sort public API is missing canonical root "
            f"table module: {PAGES_TABLE_SORT_EXPORT_SOURCES[0]}"
        )
    if "BodyTableSelector" not in _rust_canonical_exports(
        lib_source, frozenset({"BodyTableSelector"})
    ):
        violations.append(
            "focused litchi-pages table-sort public API is missing root "
            f"BodyTableSelector re-export: {PAGES_TABLE_SORT_EXPORT_SOURCES[0]}"
        )
    table_path = root / PAGES_TABLE_SORT_EXPORT_SOURCES[2]
    table_source = (
        _mask_rust_non_code(table_path.read_text(encoding="utf-8"))
        if table_path.is_file()
        else ""
    )
    if PUBLIC_PAGES_TABLE_SORT_MODULE.search(table_source) is None:
        violations.append(
            "focused litchi-pages table-sort public API is missing canonical "
            f"table::sort module: {PAGES_TABLE_SORT_EXPORT_SOURCES[2]}"
        )
    package_path = root / PAGES_TABLE_SORT_EXPORT_SOURCES[1]
    package_source = (
        _mask_rust_non_code(package_path.read_text(encoding="utf-8"))
        if package_path.is_file()
        else ""
    )
    if PAGES_PACKAGE_TABLE_SORT_MODULE.search(package_source) is None:
        violations.append(
            "focused litchi-pages table-sort public API is missing private package "
            f"owner module: {PAGES_TABLE_SORT_EXPORT_SOURCES[1]}"
        )
    for match in PUBLIC_PAGES_PACKAGE_TABLE_SORT_MODULE.finditer(package_source):
        line_number = package_source.count("\n", 0, match.start()) + 1
        violations.append(
            "focused litchi-pages table-sort public API exposes duplicate "
            f"package::body_table_sort module: {PAGES_TABLE_SORT_EXPORT_SOURCES[1]}:{line_number}"
        )

    codec_path = root / PAGES_TABLE_SORT_CODEC_SOURCE
    if not codec_path.is_file():
        violations.append(
            "focused litchi-pages table-sort public API is missing strict hidden "
            f"codec source: {PAGES_TABLE_SORT_CODEC_SOURCE}"
        )
    else:
        codec_source = _mask_rust_cfg_test_items(codec_path.read_text(encoding="utf-8"))
        codec_code = _mask_rust_non_code(codec_source)
        for api in PAGES_TABLE_SORT_CODEC_REQUIRED_APIS:
            if re.search(
                rf"\b(?:pub\s+)?(?:fn|struct|type)\s+{re.escape(api)}\b",
                codec_code,
            ) is None:
                violations.append(
                    "focused litchi-pages table-sort hidden codec is missing "
                    f"strict API {api}: {codec_path.relative_to(root)}"
                )
        for marker in PAGES_TABLE_SORT_CODEC_REQUIRED_MARKERS:
            if re.search(re.escape(marker), codec_source) is None:
                violations.append(
                    "focused litchi-pages table-sort hidden codec is missing "
                    f"strict {marker} marker: {codec_path.relative_to(root)}"
                )
        codec_lib_path = root / PAGES_TABLE_SORT_CODEC_PUBLIC_SOURCE
        codec_lib_source = (
            _mask_rust_cfg_test_items(codec_lib_path.read_text(encoding="utf-8"))
            if codec_lib_path.is_file()
            else ""
        )
        if re.search(
            rf"#\s*\[\s*doc\s*\(\s*hidden\s*\)\s*\][\s\r\n]*"
            rf"pub\s+mod\s+{re.escape(PAGES_TABLE_SORT_CODEC_MODULE)}\b",
            codec_lib_source,
        ) is None:
            violations.append(
                "focused litchi-pages table-sort public API is missing hidden codec "
                f"module {PAGES_TABLE_SORT_CODEC_MODULE}: {PAGES_TABLE_SORT_CODEC_PUBLIC_SOURCE}"
            )

    for target in (
        PAGES_TABLE_SORT_CODEC_FUZZ_SOURCE,
        PAGES_TABLE_SORT_FUZZ_SOURCE,
    ):
        absolute = root / target
        if not absolute.is_file():
            violations.append(
                "focused litchi-pages table-sort boundary is missing fuzz target: "
                f"{target}"
            )
        elif "fuzz_target!" not in absolute.read_text(encoding="utf-8"):
            violations.append(
                "focused litchi-pages table-sort fuzz target is missing "
                f"fuzz_target! harness: {target}"
            )
    for corpus in (PAGES_TABLE_SORT_CODEC_FUZZ_CORPUS, PAGES_TABLE_SORT_FUZZ_CORPUS):
        if not (root / corpus).is_dir():
            violations.append(
                "focused litchi-pages table-sort boundary is missing fuzz corpus: "
                f"{corpus}"
            )

    dedicated_sources = {
        root / path
        for path in PAGES_TABLE_SORT_IMPLEMENTATION_SOURCES
        if (root / path).is_file()
    }
    helper_root = root / PAGES_TABLE_SORT_OWNER_HELPER_ROOT
    if helper_root.is_dir():
        dedicated_sources.update(helper_root.rglob("*.rs"))
    export_sources = {
        root / path
        for path in PAGES_TABLE_SORT_EXPORT_SOURCES
        if (root / path).is_file()
    }

    # Scan the whole facade tree.  In particular, cfg(test) is masked item by
    # item so a production sibling cannot launder a raw-ID or glob route.
    for path in sorted(source_root.rglob("*.rs")):
        source = _mask_rust_cfg_test_items(path.read_text(encoding="utf-8"))
        for declaration, line_number in _rust_public_declarations(source):
            identifiers = [
                match.group(1) for match in RUST_IDENTIFIER.finditer(declaration)
            ]
            if identifiers[:3] == ["pub", "mod", "body_table_sort"]:
                violations.append(
                    "focused litchi-pages table-sort public API exposes duplicate "
                    f"body_table_sort module: {path.relative_to(root)}:{line_number}"
                )
            if identifiers[:2] == ["pub", "use"] and "*" in declaration:
                if {"body_table_sort", "sort", "package"} & set(identifiers):
                    violations.append(
                        "focused litchi-pages table-sort public API retains root "
                        f"aliases via table::sort glob: {path.relative_to(root)}:{line_number}"
                    )
            if identifiers[:2] == ["pub", "use"] and "as" in identifiers:
                alias_index = identifiers.index("as")
                target_identifiers = identifiers[2:alias_index]
                alias = (
                    identifiers[alias_index + 1]
                    if alias_index + 1 < len(identifiers)
                    else ""
                )
                target = target_identifiers[-1] if target_identifiers else ""
                if (
                    target in PAGES_TABLE_SORT_ALIAS_TARGETS
                    or "body_table_sort" in target_identifiers
                    or "sort" in target_identifiers
                ) and alias and alias != target:
                    if path == semantic_path and alias in PAGES_TABLE_SORT_TRANSACTION_TYPES:
                        continue
                    if alias in PAGES_TABLE_SORT_PUBLIC_NAMES:
                        continue
                    violations.append(
                        "focused litchi-pages table-sort public API retains "
                        f"alternate alias {alias} for {target}: {path.relative_to(root)}:{line_number}"
                    )
            if identifiers[:2] == ["pub", "type"] and len(identifiers) >= 4:
                alias = identifiers[2]
                target_identifiers = identifiers[3:]
                target = target_identifiers[-1] if target_identifiers else ""
                if (
                    target in PAGES_TABLE_SORT_ALIAS_TARGETS
                    or "body_table_sort" in target_identifiers
                    or "sort" in target_identifiers
                ) and alias != target and alias not in PAGES_TABLE_SORT_PUBLIC_NAMES:
                    violations.append(
                        "focused litchi-pages table-sort public API retains "
                        f"alternate alias {alias} for {target}: {path.relative_to(root)}:{line_number}"
                    )

    for path in sorted(dedicated_sources | export_sources):
        dedicated_source = path in dedicated_sources
        source = _mask_rust_cfg_test_items(path.read_text(encoding="utf-8"))
        for method, line_number in _rust_function_declarations(source):
            if method not in PAGES_TABLE_HIDDEN_AXES_FLAT_METHODS:
                continue
            violations.append(
                "focused litchi-pages body-table hidden-axes public API retains flat function "
                f"{method}: {path.relative_to(root)}:{line_number}"
            )
        declarations = [
            (declaration, line_number, True, dedicated_source)
            for declaration, line_number in _rust_public_declarations(source)
        ]
        if dedicated_source:
            declarations.extend(
                (declaration, line_number, False, False)
                for declaration, line_number in _rust_impl_headers(source)
            )
        for declaration, line_number, public_declaration, complete_scope in declarations:
            if not _is_pages_table_sort_public_declaration(
                declaration, dedicated_source=complete_scope
            ):
                continue
            identifiers = [
                match.group(1) for match in RUST_IDENTIFIER.finditer(declaration)
            ]
            if (
                public_declaration
                and path in export_sources
                and identifiers[:2] == ["pub", "use"]
                and "*" in declaration
            ):
                violations.append(
                    "focused litchi-pages table-sort public API retains root aliases "
                    f"via table::sort glob: {path.relative_to(root)}:{line_number}"
                )
            for match in RUST_IDENTIFIER.finditer(declaration):
                identifier = match.group(1)
                identifier_line = line_number + declaration.count(
                    "\n", 0, match.start(1)
                )
                if public_declaration and identifier in PAGES_TABLE_SORT_FLAT_ALIASES:
                    violations.append(
                        "focused litchi-pages table-sort public API retains flat alias "
                        f"{identifier}: {path.relative_to(root)}:{identifier_line}"
                    )
                reason = _pages_table_sort_public_leak(identifier)
                if reason is not None:
                    violations.append(
                        "focused litchi-pages table-sort public API exposes "
                        f"{reason} {identifier}: {path.relative_to(root)}:{identifier_line}"
                    )
            for match in RUST_BYTE_SLICE.finditer(declaration):
                byte_slice = re.sub(r"\s+", "", match.group(0))
                byte_slice_line = line_number + declaration.count(
                    "\n", 0, match.start()
                )
                violations.append(
                    "focused litchi-pages table-sort public API exposes raw byte slice "
                    f"{byte_slice}: {path.relative_to(root)}:{byte_slice_line}"
                )

            if public_declaration and PAGES_TABLE_SORT_RAW_PARAMETER.search(declaration):
                match = PAGES_TABLE_SORT_RAW_PARAMETER.search(declaration)
                assert match is not None
                violations.append(
                    "focused litchi-pages table-sort public API exposes raw identifier/bytes "
                    f"{match.group(0)}: {path.relative_to(root)}:{line_number}"
                )

    return sorted(set(violations))


def _pages_header_footer_owner_present(root: Path) -> bool:
    return (root / PAGES_HEADER_FOOTER_OWNER_SOURCE).is_file()


def audit_iwa_pages_table_appearance_source_topology(root: Path = ROOT) -> list[str]:
    """Retire the raw Pages body-table appearance host once its owner lands.

    Public appearance transactions use the focused package facade. One
    private, read-only storage helper remains for legacy editor table listing;
    it cannot publish a mutation or mask package-owner validation failures.
    Test modules, comments, and string literals are masked; Numbers and
    Keynote branches in shared examples are left alone, while a Pages branch
    is required to use the focused route.
    """

    if not _pages_table_appearance_owner_present(root):
        return []

    violations: list[str] = []
    # The package catalog owner is feature-gated at its module and re-export
    # boundaries.  Once it exists, the host must use both scalar edge and
    # semantic appearance callbacks; otherwise a local generated decoder can
    # quietly replace the bounded focused route.
    catalog_owner_path = root / PAGES_TABLE_APPEARANCE_SOURCE_OWNER
    if catalog_owner_path.is_file():
        catalog_source = _mask_rust_cfg_test_items(
            catalog_owner_path.read_text(encoding="utf-8")
        )
        for seam in PAGES_TABLE_APPEARANCE_SOURCE_SEAMS:
            if (
                PAGES_TABLE_APPEARANCE_SOURCE_SEAM_DECLARATIONS[seam].search(
                    catalog_source
                )
                is None
            ):
                violations.append(
                    "focused litchi-pages catalog appearance owner is missing "
                    f"the hidden seam {seam}: {PAGES_TABLE_APPEARANCE_SOURCE_OWNER}"
                )

        package_path = root / PAGES_TABLE_APPEARANCE_SOURCE_PACKAGE
        package_source = (
            _mask_rust_cfg_test_items(package_path.read_text(encoding="utf-8"))
            if package_path.is_file()
            else ""
        )
        if PAGES_TABLE_APPEARANCE_SOURCE_MODULE.search(package_source) is None:
            violations.append(
                "focused litchi-pages catalog appearance owner module is not "
                "feature-gated: "
                f"{PAGES_TABLE_APPEARANCE_SOURCE_PACKAGE}"
            )
        if PAGES_TABLE_APPEARANCE_SOURCE_PACKAGE_REEXPORT.search(package_source) is None:
            violations.append(
                "focused litchi-pages catalog appearance package re-export is not "
                "feature-gated: "
                f"{PAGES_TABLE_APPEARANCE_SOURCE_PACKAGE}"
            )

        lib_path = root / PAGES_TABLE_APPEARANCE_SOURCE_LIB
        lib_source = (
            _mask_rust_cfg_test_items(lib_path.read_text(encoding="utf-8"))
            if lib_path.is_file()
            else ""
        )
        if PAGES_TABLE_APPEARANCE_SOURCE_REEXPORT.search(lib_source) is None:
            violations.append(
                "focused litchi-pages catalog appearance root re-export is not "
                "feature-gated and hidden: "
                f"{PAGES_TABLE_APPEARANCE_SOURCE_LIB}"
            )

        host_path = root / PAGES_TABLE_APPEARANCE_SOURCE_HOST
        host_source = (
            _mask_rust_cfg_test_items(host_path.read_text(encoding="utf-8"))
            if host_path.is_file()
            else ""
        )
        host_code = _mask_rust_non_code(host_source)
        for seam, call in PAGES_TABLE_APPEARANCE_SOURCE_SEAM_CALLS.items():
            if call.search(host_code) is None:
                violations.append(
                    "litchi-iwa Pages table-appearance host is missing the focused "
                    f"hidden seam call {seam}: {PAGES_TABLE_APPEARANCE_SOURCE_HOST}"
                )

    source_root = root / IWA_PAGES_SOURCE_ROOT
    if source_root.is_dir():
        for path in sorted(source_root.rglob("*.rs")):
            if path.name == "tests.rs" or "tests" in path.parts:
                continue
            source = _mask_rust_cfg_test_items(path.read_text(encoding="utf-8"))
            code = _mask_rust_non_code(source)
            for name, line_number in _rust_function_declarations(source):
                if name in RETIRED_IWA_PAGES_TABLE_APPEARANCE_METHOD_SET:
                    violations.append(
                        "retired litchi-iwa Pages table-appearance method "
                        f"{name}: {path.relative_to(root)}:{line_number}"
                    )
            for pattern in IWA_PAGES_TABLE_APPEARANCE_IMPORTS:
                for match in pattern.finditer(code):
                    line_number = code.count("\n", 0, match.start()) + 1
                    violations.append(
                        "retired litchi-iwa Pages table-appearance import: "
                        f"{path.relative_to(root)}:{line_number}"
                    )
            for match in IWA_PAGES_TABLE_APPEARANCE_CALL.finditer(code):
                if _pages_table_appearance_legacy_read_compatibility_call(
                    root, path, code, match
                ):
                    continue
                line_start = code.rfind("\n", 0, match.start()) + 1
                line_end = code.find("\n", match.end())
                if line_end < 0:
                    line_end = len(code)
                line = code[line_start:line_end]
                if _pages_table_appearance_focused_package_call(code, match):
                    continue
                if re.search(
                    rf"\bfn[ \t\r\n]+{re.escape(match.group('method'))}\b", line
                ):
                    continue
                line_number = code.count("\n", 0, match.start("method")) + 1
                violations.append(
                    "retired litchi-iwa Pages table-appearance call "
                    f"{match.group('method')}: {path.relative_to(root)}:{line_number}"
                )

    example_root = root / IWA_PAGES_TABLE_APPEARANCE_EXAMPLE_ROOT
    if example_root.is_dir():
        for example_path in sorted(example_root.rglob("*.rs")):
            raw_source = example_path.read_text(encoding="utf-8")
            source = _mask_rust_cfg_test_items(raw_source)
            code = _mask_rust_non_code(source)
            for pattern in IWA_PAGES_TABLE_APPEARANCE_IMPORTS:
                for match in pattern.finditer(code):
                    if not _pages_table_appearance_example_is_pages(
                        example_path, code, match.start()
                    ):
                        continue
                    line_number = code.count("\n", 0, match.start()) + 1
                    violations.append(
                        "retired litchi-iwa Pages table-appearance example import: "
                        f"{example_path.relative_to(root)}:{line_number}"
                    )
            for match in IWA_PAGES_TABLE_APPEARANCE_CALL.finditer(code):
                if _pages_table_appearance_focused_package_call(code, match):
                    continue
                if not _pages_table_appearance_example_is_pages(
                    example_path, code, match.start()
                ):
                    continue
                line_number = code.count("\n", 0, match.start("method")) + 1
                violations.append(
                    "retired litchi-iwa Pages table-appearance example call "
                    f"{match.group('method')}: {example_path.relative_to(root)}:{line_number}"
                )

    readme_path = root / IWA_PAGES_README
    if readme_path.is_file():
        source = _mask_rust_non_code(readme_path.read_text(encoding="utf-8"))
        for pattern in IWA_PAGES_README_TABLE_APPEARANCE_CALLS:
            for match in pattern.finditer(source):
                line_number = source.count("\n", 0, match.start("method")) + 1
                violations.append(
                    "retired litchi-iwa Pages table-appearance README call "
                    f"{match.group('method')}: {IWA_PAGES_README}:{line_number}"
                )
    return sorted(set(violations))


def _pages_table_appearance_example_is_pages(
    path: Path, source: str, match_start: int
) -> bool:
    """Identify Pages branches in the shared iWork examples."""

    stem = path.stem.lower()
    if "pages" in stem:
        return True
    line_start = source.rfind("\n", 0, match_start) + 1
    line_end = source.find("\n", match_start)
    if line_end < 0:
        line_end = len(source)
    line = source[line_start:line_end].lower()
    if "pages" in line or "pageseditor" in line or "pages_editor" in line:
        return True
    function_matches = list(
        re.finditer(r"\bfn\s+(?:r#)?([A-Za-z_][A-Za-z0-9_]*)\b", source[:match_start])
    )
    return bool(function_matches and "pages" in function_matches[-1].group(1).lower())


def _pages_table_appearance_focused_package_call(
    source: str, match: re.Match[str]
) -> bool:
    """Allow only calls proven to target the focused Pages package.

    The package facade intentionally reuses the ``body_table_appearance``
    spelling of the retired editor reader.  A method-name-only scan would
    therefore flag valid calls such as ``pages_package.body_table_appearance``
    as legacy host traffic.  Treat an explicitly qualified ``Package`` type
    as proof, and require local type/binding evidence for variable receivers;
    a receiver name alone is not an exemption for a raw editor/helper alias.
    """

    receiver = match.group("receiver")
    if receiver is None:
        return False
    if receiver in {"Package", "PagesPackage"}:
        return True

    # Limit inference to the current function.  This prevents an unrelated
    # `package` binding in an earlier function from blessing a raw call later
    # in the file.
    function_matches = list(
        re.finditer(
            r"\bfn\s+(?:r#)?[A-Za-z_][A-Za-z0-9_]*\b",
            source[: match.start()],
        )
    )
    function_start = function_matches[-1].start() if function_matches else 0
    context = source[function_start : match.start()]
    receiver_pattern = re.escape(receiver)
    package_type = r"(?:litchi_pages::)?(?:Package|PagesPackage)"
    return bool(
        re.search(
            rf"\b(?:let\s+(?:mut\s+)?{receiver_pattern}|{receiver_pattern})"
            rf"\s*(?::\s*(?:&\s*(?:mut\s*)?)?{package_type}\b"
            rf"|\s*=\s*{package_type}::[A-Za-z_][A-Za-z0-9_]*\s*\()",
            context,
        )
    )


def _pages_table_appearance_legacy_read_compatibility_call(
    root: Path, path: Path, source: str, match: re.Match[str]
) -> bool:
    """Allow the sole read-only legacy fallback used by table listing.

    The exact package owner intentionally rejects producer profiles it cannot
    rewrite safely. Legacy ``PagesEditor`` physical table discovery must still
    report their existing appearance, but this exception is confined to one
    private helper and never permits a write or package-owner fallback.
    """

    expected = root / IWA_PAGES_SOURCE_ROOT / "editor/tables/storage.rs"
    if path != expected or match.group("method") != "table_appearance":
        return False
    function_matches = list(
        re.finditer(
            r"\bfn\s+(?:r#)?([A-Za-z_][A-Za-z0-9_]*)\b",
            source[: match.start()],
        )
    )
    return bool(
        function_matches
        and function_matches[-1].group(1)
        == "legacy_table_appearance_compatibility_read"
    )


def audit_pages_table_appearance_facade_source_topology(
    root: Path = ROOT,
) -> list[str]:
    """Enforce the selector-first, archive-free Pages appearance owner."""

    if not _pages_table_appearance_owner_present(root):
        return []

    owner_path = root / PAGES_TABLE_APPEARANCE_OWNER_SOURCE
    semantic_path = root / PAGES_TABLE_APPEARANCE_SEMANTIC_SOURCE
    selector_path = root / PAGES_TABLE_APPEARANCE_SELECTOR_SOURCE
    package_path = root / PAGES_TABLE_APPEARANCE_EXPORT_SOURCES[1]
    lib_path = root / PAGES_TABLE_APPEARANCE_EXPORT_SOURCES[0]
    table_path = root / PAGES_TABLE_APPEARANCE_EXPORT_SOURCES[2]
    paths = (owner_path, semantic_path, selector_path, package_path, lib_path, table_path)
    sources = {
        path: _mask_rust_cfg_test_items(path.read_text(encoding="utf-8"))
        if path.is_file()
        else ""
        for path in paths
    }
    code = {path: _mask_rust_non_code(source) for path, source in sources.items()}
    violations: list[str] = []

    package_code = code[package_path]
    if re.search(
        r"(?m)^pub[ \t]+mod[ \t]+body_table_appearance\b",
        package_code + code[lib_path],
    ):
        violations.append(
            "focused litchi-pages body-table appearance owner module must remain private: "
            f"{PAGES_TABLE_APPEARANCE_EXPORT_SOURCES[1]}"
        )
    if PAGES_PACKAGE_TABLE_APPEARANCE_MODULE.search(package_code) is None:
        violations.append(
            "focused litchi-pages body-table appearance owner module is missing: "
            f"{PAGES_TABLE_APPEARANCE_EXPORT_SOURCES[1]}"
        )

    semantic_exports = _rust_canonical_exports(
        sources[semantic_path], frozenset(PAGES_TABLE_APPEARANCE_SEMANTIC_TYPES)
    )
    for name in PAGES_TABLE_APPEARANCE_SEMANTIC_TYPES:
        if name not in semantic_exports:
            violations.append(
                "focused litchi-pages body-table appearance semantic API is missing "
                f"{name}: {PAGES_TABLE_APPEARANCE_SEMANTIC_SOURCE}"
            )
    if PUBLIC_PAGES_TABLE_APPEARANCE_TRANSACTION_MODULE.search(
        code[semantic_path]
    ) is None:
        violations.append(
            "focused litchi-pages body-table appearance semantic API is missing "
            f"table::appearance::transaction: {PAGES_TABLE_APPEARANCE_SEMANTIC_SOURCE}"
        )
    transaction_exports = _rust_canonical_exports(
        sources[semantic_path], frozenset(PAGES_TABLE_APPEARANCE_TRANSACTION_TYPES)
    )
    for name in PAGES_TABLE_APPEARANCE_TRANSACTION_TYPES:
        if name not in transaction_exports:
            violations.append(
                "focused litchi-pages body-table appearance transaction API is missing "
                f"{name}: {PAGES_TABLE_APPEARANCE_SEMANTIC_SOURCE}"
            )

    selector_exports = _rust_canonical_exports(
        sources[selector_path], frozenset({"BodyTableSelector"})
    )
    if "BodyTableSelector" not in selector_exports:
        violations.append(
            "focused litchi-pages body-table appearance public API is missing canonical "
            f"BodyTableSelector: {PAGES_TABLE_APPEARANCE_SELECTOR_SOURCE}"
        )
    if "BodyTableSelector" not in _rust_canonical_exports(
        sources[lib_path], frozenset({"BodyTableSelector"})
    ):
        violations.append(
            "focused litchi-pages body-table appearance public API is missing root "
            f"BodyTableSelector re-export: {PAGES_TABLE_APPEARANCE_EXPORT_SOURCES[0]}"
        )

    owner_exports = _rust_canonical_exports(
        sources[owner_path], frozenset(PAGES_TABLE_APPEARANCE_CANONICAL_TYPES)
    )
    for name in PAGES_TABLE_APPEARANCE_CANONICAL_TYPES:
        if name not in owner_exports:
            violations.append(
                "focused litchi-pages body-table appearance public API is missing canonical "
                f"type {name}: {PAGES_TABLE_APPEARANCE_OWNER_SOURCE}"
            )
    for name in PAGES_TABLE_APPEARANCE_CANONICAL_TYPES:
        for path in (package_path, lib_path):
            if name not in _rust_canonical_exports(
                sources[path], frozenset({name})
            ):
                violations.append(
                    "focused litchi-pages body-table appearance public API is missing root "
                    f"re-export {name}: {path.relative_to(root)}"
                )

    owner_methods = {
        name: declaration
        for name, declaration, _line_number in _rust_public_methods_in_impl(
            sources[owner_path], "Package"
        )
    }
    for method in PAGES_TABLE_APPEARANCE_PACKAGE_METHODS:
        declaration = owner_methods.get(method)
        if declaration is None:
            violations.append(
                "focused litchi-pages body-table appearance Package method is missing "
                f"{method}: {PAGES_TABLE_APPEARANCE_OWNER_SOURCE}"
            )
            continue
        if method != "apply_body_table_appearance" and "BodyTableSelector" not in declaration:
            violations.append(
                "focused litchi-pages body-table appearance Package method "
                f"{method} must accept selector-first BodyTableSelector: "
                f"{PAGES_TABLE_APPEARANCE_OWNER_SOURCE}"
            )
    apply_declaration = owner_methods.get("apply_body_table_appearance")
    if apply_declaration is not None and "BodyTableAppearancePatch" not in apply_declaration:
        violations.append(
            "focused litchi-pages body-table appearance apply method must accept "
            f"BodyTableAppearancePatch: {PAGES_TABLE_APPEARANCE_OWNER_SOURCE}"
        )
    edit_methods = {
        name
        for edit_type in ("BodyTableAppearanceEdit", "Edit")
        for name, _declaration, _line_number in _rust_public_methods_in_impl(
            sources[owner_path], edit_type
        )
    }
    for name in sorted(PAGES_TABLE_APPEARANCE_EDIT_METHODS - edit_methods):
        violations.append(
            "focused litchi-pages body-table appearance edit is missing "
            f"{name}: {PAGES_TABLE_APPEARANCE_OWNER_SOURCE}"
        )
    for name in ("clear", "reset"):
        if name in edit_methods:
            violations.append(
                "focused litchi-pages body-table appearance edit must not expose "
                f"{name}: {PAGES_TABLE_APPEARANCE_OWNER_SOURCE}"
            )
    flat_methods = {"table_appearance", "edit_table_appearance", "apply_table_appearance"}
    for method in sorted(flat_methods & owner_methods.keys()):
        violations.append(
            "focused litchi-pages body-table appearance public API retains flat Package method "
            f"{method}: {PAGES_TABLE_APPEARANCE_OWNER_SOURCE}"
        )

    if PUBLIC_PAGES_TABLE_MODULE.search(code[lib_path]) is None:
        violations.append(
            "focused litchi-pages body-table appearance public API is missing canonical root "
            f"table module: {PAGES_TABLE_APPEARANCE_EXPORT_SOURCES[0]}"
        )
    if PUBLIC_PAGES_TABLE_APPEARANCE_MODULE.search(code[table_path]) is None:
        violations.append(
            "focused litchi-pages body-table appearance public API is missing canonical "
            f"table::appearance module: {PAGES_TABLE_APPEARANCE_EXPORT_SOURCES[2]}"
        )

    codec_path = root / PAGES_TABLE_APPEARANCE_CODEC_SOURCE
    if not codec_path.is_file():
        violations.append(
            "focused litchi-pages body-table appearance public API is missing strict hidden "
            f"codec source: {PAGES_TABLE_APPEARANCE_CODEC_SOURCE}"
        )
    else:
        codec_raw = codec_path.read_text(encoding="utf-8")
        codec_source = _mask_rust_cfg_test_items(codec_raw)
        codec_code = _mask_rust_non_code(codec_source)
        for api in PAGES_TABLE_APPEARANCE_CODEC_REQUIRED_APIS:
            if re.search(
                rf"\b(?:pub\s+)?(?:fn|struct|enum|type)\s+{re.escape(api)}\b",
                codec_code,
            ) is None:
                violations.append(
                    "focused litchi-pages body-table appearance hidden codec is missing "
                    f"strict API {api}: {PAGES_TABLE_APPEARANCE_CODEC_SOURCE}"
                )
        for label, markers in PAGES_TABLE_APPEARANCE_CODEC_REQUIRED_MARKER_GROUPS.items():
            if not all(marker in codec_code for marker in markers):
                violations.append(
                    "focused litchi-pages body-table appearance hidden codec is missing "
                    f"{label} marker: {PAGES_TABLE_APPEARANCE_CODEC_SOURCE}"
                )
        codec_lib_path = root / PAGES_TABLE_APPEARANCE_CODEC_PUBLIC_SOURCE
        codec_lib_source = (
            _mask_rust_cfg_test_items(codec_lib_path.read_text(encoding="utf-8"))
            if codec_lib_path.is_file()
            else ""
        )
        if re.search(
            rf"#\s*\[\s*doc\s*\(\s*hidden\s*\)\s*\][\s\r\n]*"
            rf"pub\s+mod\s+{re.escape(PAGES_TABLE_APPEARANCE_CODEC_MODULE)}\b",
            codec_lib_source,
        ) is None:
            violations.append(
                "focused litchi-pages body-table appearance public API is missing hidden "
                f"codec module {PAGES_TABLE_APPEARANCE_CODEC_MODULE}: {PAGES_TABLE_APPEARANCE_CODEC_PUBLIC_SOURCE}"
            )
        if re.search(r"(?m)#\s*\[\s*cfg\(\s*test\s*\)\s*\]", codec_raw) is None or re.search(
            r"(?m)#\s*\[\s*test\s*\]", codec_raw
        ) is None:
            violations.append(
                "focused litchi-pages body-table appearance hidden codec is missing cfg(test) #[test] coverage: "
                f"{PAGES_TABLE_APPEARANCE_CODEC_SOURCE}"
            )

    for test_path in PAGES_TABLE_APPEARANCE_TEST_SOURCES:
        absolute = root / test_path
        if not absolute.is_file():
            violations.append(
                "focused litchi-pages body-table appearance boundary is missing integration test: "
                f"{test_path}"
            )
        else:
            test_code = _mask_rust_non_code(absolute.read_text(encoding="utf-8"))
            if re.search(r"(?m)#\s*\[\s*test\s*\]", test_code) is None:
                violations.append(
                    "focused litchi-pages body-table appearance integration test is missing #[test] coverage: "
                    f"{test_path}"
                )
            if not re.search(
                r"\b(?:body_table_appearance|edit_body_table_appearance|apply_body_table_appearance)\b",
                test_code,
            ):
                violations.append(
                    "focused litchi-pages body-table appearance integration test does not exercise the owner: "
                    f"{test_path}"
                )
    for fuzz_path in PAGES_TABLE_APPEARANCE_FUZZ_SOURCES:
        absolute = root / fuzz_path
        if not absolute.is_file():
            violations.append(
                "focused litchi-pages body-table appearance boundary is missing fuzz target: "
                f"{fuzz_path}"
            )
        elif "fuzz_target!" not in absolute.read_text(encoding="utf-8"):
            violations.append(
                "focused litchi-pages body-table appearance fuzz target is missing fuzz_target! harness: "
                f"{fuzz_path}"
            )
    for corpus in PAGES_TABLE_APPEARANCE_FUZZ_CORPORA:
        if not (root / corpus).is_dir():
            violations.append(
                "focused litchi-pages body-table appearance boundary is missing fuzz corpus: "
                f"{corpus}"
            )

    dedicated_sources = {
        root / path
        for path in PAGES_TABLE_APPEARANCE_IMPLEMENTATION_SOURCES
        if (root / path).is_file()
    }
    helper_root = root / PAGES_TABLE_APPEARANCE_OWNER_HELPER_ROOT
    if helper_root.is_dir():
        dedicated_sources.update(helper_root.rglob("*.rs"))
    export_sources = {
        root / path
        for path in PAGES_TABLE_APPEARANCE_EXPORT_SOURCES
        if (root / path).is_file()
    }
    facade_names = (
        set(PAGES_TABLE_APPEARANCE_CANONICAL_TYPES)
        | set(PAGES_TABLE_APPEARANCE_SEMANTIC_TYPES)
        | {"BodyTableSelector"}
        | set(PAGES_TABLE_APPEARANCE_PACKAGE_METHODS)
        | set(PAGES_TABLE_APPEARANCE_FLAT_ALIASES)
    )
    for path in sorted(dedicated_sources | export_sources):
        dedicated = path in dedicated_sources
        source = _mask_rust_cfg_test_items(path.read_text(encoding="utf-8"))
        declarations = [
            (declaration, line_number, True, dedicated)
            for declaration, line_number in _rust_public_declarations(source)
        ]
        if dedicated:
            declarations.extend(
                (declaration, line_number, False, False)
                for declaration, line_number in _rust_impl_headers(source)
            )
        for declaration, line_number, public_declaration, complete_scope in declarations:
            if not _is_pages_table_appearance_public_declaration(
                declaration, dedicated_source=complete_scope
            ):
                continue
            identifiers = {
                match.group(1) for match in RUST_IDENTIFIER.finditer(declaration)
            }
            if public_declaration and "pub use" in declaration and "*" in declaration:
                violations.append(
                    "focused litchi-pages body-table appearance public API retains a glob re-export: "
                    f"{path.relative_to(root)}:{line_number}"
                )
            for identifier in sorted(identifiers):
                reason = _pages_table_appearance_public_leak(identifier)
                if reason is not None:
                    violations.append(
                        "focused litchi-pages body-table appearance public API exposes "
                        f"{reason} {identifier}: {path.relative_to(root)}:{line_number}"
                    )
                if public_declaration and identifier in PAGES_TABLE_APPEARANCE_FLAT_ALIASES:
                    violations.append(
                        "focused litchi-pages body-table appearance public API retains flat alias "
                        f"{identifier}: {path.relative_to(root)}:{line_number}"
                    )
            for match in PAGES_TABLE_APPEARANCE_PUBLIC_RAW_ID_PARAMETER.finditer(declaration):
                violations.append(
                    "focused litchi-pages body-table appearance public API exposes raw parameter "
                    f"{match.group(0).strip()}: {path.relative_to(root)}:{line_number}"
                )
            for match in RUST_BYTE_SLICE.finditer(declaration):
                byte_slice = re.sub(r"\s+", "", match.group(0))
                violations.append(
                    "focused litchi-pages body-table appearance public API exposes raw byte slice "
                    f"{byte_slice}: {path.relative_to(root)}:{line_number}"
                )

    # Catch public aliases and duplicate module routes in sibling facade files.
    for path in sorted((root / PAGES_SOURCE_ROOT).rglob("*.rs")):
        source = _mask_rust_cfg_test_items(path.read_text(encoding="utf-8"))
        for declaration, line_number in _rust_public_declarations(source):
            identifiers = [
                match.group(1) for match in RUST_IDENTIFIER.finditer(declaration)
            ]
            if identifiers[:3] == ["pub", "mod", "body_table_appearance"] and path != lib_path:
                violations.append(
                    "focused litchi-pages body-table appearance public API exposes duplicate "
                    f"body_table_appearance module: {path.relative_to(root)}:{line_number}"
                )
            if identifiers[:2] == ["pub", "use"] and "*" in declaration:
                if {"body_table_appearance", "appearance", "package"} & set(identifiers):
                    violations.append(
                        "focused litchi-pages body-table appearance public API retains root aliases via glob: "
                        f"{path.relative_to(root)}:{line_number}"
                    )
            if identifiers[:2] == ["pub", "use"] and "as" in identifiers:
                alias_index = identifiers.index("as")
                target = identifiers[alias_index - 1] if alias_index > 2 else ""
                alias = identifiers[alias_index + 1] if alias_index + 1 < len(identifiers) else ""
                if target in PAGES_TABLE_APPEARANCE_ALIAS_TARGETS and alias and alias != target:
                    if path == semantic_path and alias in PAGES_TABLE_APPEARANCE_TRANSACTION_TYPES:
                        continue
                    if alias in PAGES_TABLE_APPEARANCE_PUBLIC_NAMES:
                        continue
                    violations.append(
                        "focused litchi-pages body-table appearance public API retains alternate alias "
                        f"{alias} for {target}: {path.relative_to(root)}:{line_number}"
                    )
            if identifiers[:2] == ["pub", "type"] and len(identifiers) >= 4:
                alias = identifiers[2]
                target = identifiers[-1]
                if target in PAGES_TABLE_APPEARANCE_ALIAS_TARGETS and alias != target and alias not in PAGES_TABLE_APPEARANCE_PUBLIC_NAMES:
                    violations.append(
                        "focused litchi-pages body-table appearance public API retains alternate alias "
                        f"{alias} for {target}: {path.relative_to(root)}:{line_number}"
                    )
    return sorted(set(violations))


def audit_iwa_shared_table_appearance_source_topology(
    root: Path = ROOT,
) -> list[str]:
    """Keep the retired monolithic table-appearance route deleted.

    Numbers, Pages, and Keynote retain narrowly scoped source-built callbacks
    in their focused packages.  The old host module has no remaining owner;
    this guard therefore checks physical resurrection and production imports
    while ignoring comments, literals, and cfg(test) compatibility oracles.
    """

    violations: list[str] = []
    for relative_path in RETIRED_IWA_SHARED_TABLE_APPEARANCE_SOURCES:
        path = root / relative_path
        if path.is_file():
            violations.append(
                "retired shared litchi-iwa table-appearance source was restored: "
                f"{relative_path}"
            )

    source_root = root / IWA_HOST_SOURCE_ROOT
    if not source_root.is_dir():
        return sorted(set(violations))

    for path in sorted(source_root.rglob("*.rs")):
        if not path.is_file():
            continue
        production_source = _mask_rust_cfg_test_items(
            path.read_text(encoding="utf-8")
        )
        code = _mask_rust_non_code(production_source)
        for match in RETIRED_IWA_SHARED_TABLE_APPEARANCE_MODULE.finditer(code):
            line_number = code.count("\n", 0, match.start()) + 1
            violations.append(
                "retired shared litchi-iwa table-appearance module declaration: "
                f"{path.relative_to(root)}:{line_number}"
            )
        for match in RETIRED_IWA_SHARED_TABLE_APPEARANCE_REFERENCE.finditer(code):
            line_number = code.count("\n", 0, match.start()) + 1
            violations.append(
                "retired shared litchi-iwa table-appearance production reference: "
                f"{path.relative_to(root)}:{line_number}"
            )

    return sorted(set(violations))


def audit_pages_table_hidden_axes_facade_source_topology(
    root: Path = ROOT,
) -> list[str]:
    """Enforce the selector-first, archive-free Pages hidden-axis owner."""

    source_root = root / PAGES_SOURCE_ROOT
    if not source_root.is_dir() or not _pages_table_hidden_axes_owner_present(root):
        return []

    owner_path = root / PAGES_TABLE_HIDDEN_AXES_OWNER_SOURCE
    semantic_path = root / PAGES_TABLE_HIDDEN_AXES_SEMANTIC_SOURCE
    selector_path = root / PAGES_TABLE_HIDDEN_AXES_SELECTOR_SOURCE
    lib_path = root / PAGES_TABLE_HIDDEN_AXES_EXPORT_SOURCES[0]
    package_path = root / PAGES_TABLE_HIDDEN_AXES_EXPORT_SOURCES[1]
    table_path = root / PAGES_TABLE_HIDDEN_AXES_EXPORT_SOURCES[2]
    paths = (owner_path, semantic_path, selector_path, lib_path, package_path, table_path)
    sources = {
        path: _mask_rust_cfg_test_items(path.read_text(encoding="utf-8"))
        if path.is_file()
        else ""
        for path in paths
    }
    code = {path: _mask_rust_non_code(source) for path, source in sources.items()}
    violations: list[str] = []

    package_code = code[package_path]
    package_raw = sources[package_path]
    lib_code = code[lib_path]
    if PUBLIC_PAGES_PACKAGE_TABLE_HIDDEN_AXES_MODULE.search(
        package_raw + sources[lib_path]
    ):
        violations.append(
            "focused litchi-pages body-table hidden-axes owner module must remain private: "
            f"{PAGES_TABLE_HIDDEN_AXES_EXPORT_SOURCES[1]}"
        )
    if PAGES_PACKAGE_TABLE_HIDDEN_AXES_MODULE.search(package_code) is None:
        violations.append(
            "focused litchi-pages body-table hidden-axes owner module is missing: "
            f"{PAGES_TABLE_HIDDEN_AXES_EXPORT_SOURCES[1]}"
        )

    semantic_exports = _rust_canonical_exports(
        sources[semantic_path], frozenset(PAGES_TABLE_HIDDEN_AXES_SEMANTIC_TYPES)
    )
    for name in PAGES_TABLE_HIDDEN_AXES_SEMANTIC_TYPES:
        if name not in semantic_exports:
            violations.append(
                "focused litchi-pages body-table hidden-axes semantic API is missing "
                f"{name}: {PAGES_TABLE_HIDDEN_AXES_SEMANTIC_SOURCE}"
            )
    if PUBLIC_PAGES_TABLE_HIDDEN_AXES_TRANSACTION_MODULE.search(
        code[semantic_path]
    ) is None:
        violations.append(
            "focused litchi-pages body-table hidden-axes semantic API is missing "
            f"table::hidden_axes::transaction: {PAGES_TABLE_HIDDEN_AXES_SEMANTIC_SOURCE}"
        )
    transaction_exports = _rust_canonical_exports(
        sources[semantic_path], frozenset(PAGES_TABLE_HIDDEN_AXES_TRANSACTION_TYPES)
    )
    for name in PAGES_TABLE_HIDDEN_AXES_TRANSACTION_TYPES:
        if name not in transaction_exports:
            violations.append(
                "focused litchi-pages body-table hidden-axes transaction API is missing "
                f"{name}: {PAGES_TABLE_HIDDEN_AXES_SEMANTIC_SOURCE}"
            )

    if "BodyTableSelector" not in _rust_canonical_exports(
        sources[selector_path], frozenset({"BodyTableSelector"})
    ):
        violations.append(
            "focused litchi-pages body-table hidden-axes public API is missing canonical "
            f"BodyTableSelector: {PAGES_TABLE_HIDDEN_AXES_SELECTOR_SOURCE}"
        )
    if "BodyTableSelector" not in _rust_canonical_exports(
        sources[lib_path], frozenset({"BodyTableSelector"})
    ):
        violations.append(
            "focused litchi-pages body-table hidden-axes public API is missing root "
            f"BodyTableSelector re-export: {PAGES_TABLE_HIDDEN_AXES_EXPORT_SOURCES[0]}"
        )

    owner_exports = _rust_canonical_exports(
        sources[owner_path], frozenset(PAGES_TABLE_HIDDEN_AXES_CANONICAL_TYPES)
    )
    for name in PAGES_TABLE_HIDDEN_AXES_CANONICAL_TYPES:
        if name not in owner_exports:
            violations.append(
                "focused litchi-pages body-table hidden-axes public API is missing canonical "
                f"type {name}: {PAGES_TABLE_HIDDEN_AXES_OWNER_SOURCE}"
            )
        for export_path in (package_path, lib_path):
            if name not in _rust_canonical_exports(
                sources[export_path], frozenset({name})
            ):
                violations.append(
                    "focused litchi-pages body-table hidden-axes public API is missing root "
                    f"re-export {name}: {export_path.relative_to(root)}"
                )

    owner_methods = {
        name: declaration
        for name, declaration, _line_number in _rust_public_methods_in_impl(
            sources[owner_path], "Package"
        )
    }
    for method in PAGES_TABLE_HIDDEN_AXES_PACKAGE_METHODS:
        declaration = owner_methods.get(method)
        if declaration is None:
            violations.append(
                "focused litchi-pages body-table hidden-axes Package method is missing "
                f"{method}: {PAGES_TABLE_HIDDEN_AXES_OWNER_SOURCE}"
            )
            continue
        if method != "apply_body_table_hidden_axes" and "BodyTableSelector" not in declaration:
            violations.append(
                "focused litchi-pages body-table hidden-axes Package method "
                f"{method} must accept selector-first BodyTableSelector: "
                f"{PAGES_TABLE_HIDDEN_AXES_OWNER_SOURCE}"
            )
    apply_declaration = owner_methods.get("apply_body_table_hidden_axes")
    if apply_declaration is not None and "BodyTableHiddenAxesPatch" not in apply_declaration:
        violations.append(
            "focused litchi-pages body-table hidden-axes apply method must accept "
            f"BodyTableHiddenAxesPatch: {PAGES_TABLE_HIDDEN_AXES_OWNER_SOURCE}"
        )

    edit_methods = {
        name
        for edit_type in ("BodyTableHiddenAxesEdit", "Edit")
        for name, _declaration, _line_number in _rust_public_methods_in_impl(
            sources[owner_path], edit_type
        )
    }
    for name in sorted(PAGES_TABLE_HIDDEN_AXES_EDIT_METHODS - edit_methods):
        violations.append(
            "focused litchi-pages body-table hidden-axes edit is missing "
            f"{name}: {PAGES_TABLE_HIDDEN_AXES_OWNER_SOURCE}"
        )
    for method in sorted(PAGES_TABLE_HIDDEN_AXES_FLAT_METHODS & owner_methods.keys()):
        violations.append(
            "focused litchi-pages body-table hidden-axes public API retains flat Package "
            f"method {method}: {PAGES_TABLE_HIDDEN_AXES_OWNER_SOURCE}"
        )

    if PUBLIC_PAGES_TABLE_MODULE.search(lib_code) is None:
        violations.append(
            "focused litchi-pages body-table hidden-axes public API is missing canonical root "
            f"table module: {PAGES_TABLE_HIDDEN_AXES_EXPORT_SOURCES[0]}"
        )
    if PUBLIC_PAGES_TABLE_HIDDEN_AXES_MODULE.search(code[table_path]) is None:
        violations.append(
            "focused litchi-pages body-table hidden-axes public API is missing canonical "
            f"table::hidden_axes module: {PAGES_TABLE_HIDDEN_AXES_EXPORT_SOURCES[2]}"
        )

    # The focused owner must not recover unsupported source-built edits by
    # delegating to the migration host.  Keep this executable-source check
    # separate from the public declaration leak scan below: a private helper
    # can still create an implicit fallback without changing the facade type
    # signatures.
    for path in (owner_path, semantic_path):
        for pattern in PAGES_TABLE_HIDDEN_AXES_FOCUSED_FALLBACK_PATTERNS:
            match = pattern.search(code[path])
            if match is None:
                continue
            line_number = code[path].count("\n", 0, match.start()) + 1
            violations.append(
                "focused litchi-pages body-table hidden-axes owner must not fallback "
                "through the migration host: "
                f"{path.relative_to(root)}:{line_number}"
            )

    # Keep the Buffa sidecar wholly behind the protos crate's hidden module.
    # The generated module must be private and use the expected OUT_DIR file;
    # downstream Pages code may import the strict codec, never generated
    # archive types or Prost's eager message API.
    owner_code = code[owner_path]
    if PAGES_TABLE_HIDDEN_AXES_UID_MAP_OWNER_MARKER.search(owner_code) is None:
        violations.append(
            "focused litchi-pages body-table hidden-axes owner is missing the "
            f"canonical UID-map message type {PAGES_TABLE_HIDDEN_AXES_UID_MAP_MESSAGE_TYPE}: "
            f"{PAGES_TABLE_HIDDEN_AXES_OWNER_SOURCE}"
        )
    if PAGES_TABLE_HIDDEN_AXES_LEGACY_OWNER_MARKER.search(owner_code) is None:
        violations.append(
            "focused litchi-pages body-table hidden-axes owner is missing its explicit "
            f"legacy UID-map marker {PAGES_TABLE_HIDDEN_AXES_LEGACY_UID_MAP_MESSAGE_TYPE}: "
            f"{PAGES_TABLE_HIDDEN_AXES_OWNER_SOURCE}"
        )
    if PAGES_TABLE_HIDDEN_AXES_LEGACY_OPT_IN_MARKER.search(owner_code) is None:
        violations.append(
            "focused litchi-pages body-table hidden-axes owner must qualify legacy "
            "UID-map support through an explicit allow_legacy path: "
            f"{PAGES_TABLE_HIDDEN_AXES_OWNER_SOURCE}"
        )
    for pattern in PAGES_TABLE_HIDDEN_AXES_FORBIDDEN_CREATION_MARKERS:
        match = pattern.search(owner_code)
        if match is None:
            continue
        line_number = owner_code.count("\n", 0, match.start()) + 1
        violations.append(
            "focused litchi-pages body-table hidden-axes owner retains forbidden "
            f"owner-creation helper {match.group(0)}: "
            f"{PAGES_TABLE_HIDDEN_AXES_OWNER_SOURCE}:{line_number}"
        )

    codec_path = root / PAGES_TABLE_HIDDEN_AXES_CODEC_SOURCE
    codec_lib_path = root / PAGES_TABLE_HIDDEN_AXES_CODEC_PUBLIC_SOURCE
    codec_code = ""
    if not codec_path.is_file():
        violations.append(
            "focused litchi-pages body-table hidden-axes public API is missing strict hidden "
            f"codec source: {PAGES_TABLE_HIDDEN_AXES_CODEC_SOURCE}"
        )
    else:
        codec_raw = codec_path.read_text(encoding="utf-8")
        codec_source = _mask_rust_cfg_test_items(codec_raw)
        codec_code = _mask_rust_non_code(codec_source)
        if PAGES_TABLE_HIDDEN_AXES_UID_MAP_CODEC_MARKER.search(codec_code) is None:
            violations.append(
                "focused litchi-pages body-table hidden-axes codec is missing the "
                f"canonical UID-map message type {PAGES_TABLE_HIDDEN_AXES_UID_MAP_MESSAGE_TYPE}: "
                f"{PAGES_TABLE_HIDDEN_AXES_CODEC_SOURCE}"
            )
        if PAGES_TABLE_HIDDEN_AXES_LEGACY_CODEC_MARKER.search(codec_code) is None:
            violations.append(
                "focused litchi-pages body-table hidden-axes codec is missing its explicit "
                f"legacy UID-map marker {PAGES_TABLE_HIDDEN_AXES_LEGACY_UID_MAP_MESSAGE_TYPE}: "
                f"{PAGES_TABLE_HIDDEN_AXES_CODEC_SOURCE}"
            )
        if PAGES_TABLE_HIDDEN_AXES_LEGACY_OPT_IN_MARKER.search(codec_code) is None:
            violations.append(
                "focused litchi-pages body-table hidden-axes codec must qualify legacy "
                "UID-map support through an explicit allow_legacy path: "
                f"{PAGES_TABLE_HIDDEN_AXES_CODEC_SOURCE}"
            )
        for api in PAGES_TABLE_HIDDEN_AXES_CODEC_REQUIRED_APIS:
            if re.search(
                rf"\b(?:pub\s+)?(?:fn|struct|enum|type)\s+{re.escape(api)}\b",
                codec_code,
            ) is None:
                violations.append(
                    "focused litchi-pages body-table hidden-axes hidden codec is missing "
                    f"strict API {api}: {PAGES_TABLE_HIDDEN_AXES_CODEC_SOURCE}"
                )
        # Keep cfg(test) names visible for behavior markers (the overlong
        # unknown-field case is intentionally named in the codec tests), but
        # still mask comments so prose cannot satisfy the ratchet.
        codec_markers = _mask_rust_comments(codec_raw)
        for marker in PAGES_TABLE_HIDDEN_AXES_CODEC_REQUIRED_MARKERS:
            if marker not in codec_markers:
                violations.append(
                    "focused litchi-pages body-table hidden-axes hidden codec is missing "
                    f"strict marker {marker}: {PAGES_TABLE_HIDDEN_AXES_CODEC_SOURCE}"
                )
        for pattern in PAGES_TABLE_HIDDEN_AXES_CODEC_FORBIDDEN_PATTERNS:
            match = pattern.search(codec_code)
            if match is None:
                continue
            line_number = codec_code.count("\n", 0, match.start()) + 1
            violations.append(
                "focused litchi-pages body-table hidden-axes hidden codec retains forbidden "
                f"generated/Prost encoding {match.group(0).strip()}: "
                f"{PAGES_TABLE_HIDDEN_AXES_CODEC_SOURCE}:{line_number}"
            )
        if re.search(r"(?m)#\s*\[\s*cfg\(\s*test\s*\)\s*\]", codec_raw) is None or re.search(
            r"(?m)#\s*\[\s*test\s*\]", codec_raw
        ) is None:
            violations.append(
                "focused litchi-pages body-table hidden-axes hidden codec is missing cfg(test) #[test] coverage: "
                f"{PAGES_TABLE_HIDDEN_AXES_CODEC_SOURCE}"
            )
    for path, source_code in (
        (owner_path, owner_code),
        (codec_path, codec_code),
    ):
        if not source_code:
            continue
        for match in PAGES_TABLE_HIDDEN_AXES_FORBIDDEN_UID_MAP_LITERAL.finditer(
            source_code
        ):
            line_number = source_code.count("\n", 0, match.start()) + 1
            violations.append(
                "focused litchi-pages body-table hidden-axes source uses the forbidden "
                f"Numbers table-data UID-map message type {PAGES_TABLE_HIDDEN_AXES_WRONG_UID_MAP_MESSAGE_TYPE}: "
                f"{path.relative_to(root)}:{line_number}"
            )

    if not codec_lib_path.is_file():
        codec_lib_source = ""
    else:
        codec_lib_source = _mask_rust_cfg_test_items(
            codec_lib_path.read_text(encoding="utf-8")
        )
    codec_lib_code = _mask_rust_non_code(codec_lib_source)
    alias_route = PAGES_TABLE_HIDDEN_AXES_CODEC_ALIAS_ROUTE.search(codec_lib_code)
    if alias_route is not None:
        line_number = codec_lib_code.count("\n", 0, alias_route.start()) + 1
        violations.append(
            "focused litchi-pages body-table hidden-axes codec retains its retired "
            f"alias module {PAGES_TABLE_HIDDEN_AXES_CODEC_ALIAS_MODULE}: "
            f"{PAGES_TABLE_HIDDEN_AXES_CODEC_PUBLIC_SOURCE}:{line_number}"
        )
    hidden_module_pattern = re.compile(
        rf"#\s*\[\s*doc\s*\(\s*hidden\s*\)\s*\][\s\r\n]*"
        rf"pub\s+mod\s+{re.escape(PAGES_TABLE_HIDDEN_AXES_CODEC_MODULE)}\b"
    )
    if hidden_module_pattern.search(codec_lib_source) is None:
        violations.append(
            "focused litchi-pages body-table hidden-axes public API is missing hidden "
            f"codec module {PAGES_TABLE_HIDDEN_AXES_CODEC_MODULE}: "
            f"{PAGES_TABLE_HIDDEN_AXES_CODEC_PUBLIC_SOURCE}"
        )
    generated_module = re.compile(
        rf"#\s*\[\s*doc\s*\(\s*hidden\s*\)\s*\][\s\r\n]*"
        rf"mod\s+{re.escape(PAGES_TABLE_HIDDEN_AXES_CODEC_GENERATED_MODULE)}\b"
    )
    if generated_module.search(codec_lib_source) is None:
        violations.append(
            "focused litchi-pages body-table hidden-axes Buffa generated module must remain private: "
            f"{PAGES_TABLE_HIDDEN_AXES_CODEC_PUBLIC_SOURCE}"
        )
    if PAGES_TABLE_HIDDEN_AXES_CODEC_GENERATED_INCLUDE not in codec_lib_source:
        violations.append(
            "focused litchi-pages body-table hidden-axes Buffa generated module has the wrong include: "
            f"{PAGES_TABLE_HIDDEN_AXES_CODEC_PUBLIC_SOURCE}"
        )
    if re.search(
        rf"(?m)^\s*pub\s+mod\s+{re.escape(PAGES_TABLE_HIDDEN_AXES_CODEC_GENERATED_MODULE)}\b",
        codec_lib_source,
    ):
        violations.append(
            "focused litchi-pages body-table hidden-axes Buffa generated module must not be public: "
            f"{PAGES_TABLE_HIDDEN_AXES_CODEC_PUBLIC_SOURCE}"
        )

    projection_path = root / PAGES_TABLE_HIDDEN_AXES_CODEC_PROJECTION_SOURCE
    if not projection_path.is_file():
        violations.append(
            "focused litchi-pages body-table hidden-axes boundary is missing Buffa projection: "
            f"{PAGES_TABLE_HIDDEN_AXES_CODEC_PROJECTION_SOURCE}"
        )
    else:
        projection_raw = projection_path.read_text(encoding="utf-8")
        projection_code = _mask_rust_comments(projection_raw)
        for marker in PAGES_TABLE_HIDDEN_AXES_PROJECTION_MARKERS:
            if marker not in projection_code:
                violations.append(
                    "focused litchi-pages body-table hidden-axes Buffa projection is missing "
                    f"marker {marker}: {PAGES_TABLE_HIDDEN_AXES_CODEC_PROJECTION_SOURCE}"
                )
        repeated = re.search(r"\brepeated\b", projection_code)
        if repeated is not None:
            line_number = projection_code.count("\n", 0, repeated.start()) + 1
            violations.append(
                "focused litchi-pages body-table hidden-axes Buffa projection must not expose repeated generated fields: "
                f"{PAGES_TABLE_HIDDEN_AXES_CODEC_PROJECTION_SOURCE}:{line_number}"
            )

    # Positive owner tests/fuzz are part of the focused seam.  Keep these
    # checks here (rather than a broad workspace scan) so shared Numbers and
    # Keynote compatibility fixtures do not become accidental Pages routes.
    for test_path in PAGES_TABLE_HIDDEN_AXES_TEST_SOURCES:
        absolute = root / test_path
        if not absolute.is_file():
            violations.append(
                "focused litchi-pages body-table hidden-axes boundary is missing integration test: "
                f"{test_path}"
            )
        else:
            test_code = _mask_rust_non_code(absolute.read_text(encoding="utf-8"))
            if re.search(r"(?m)#\s*\[\s*test\s*\]", test_code) is None:
                violations.append(
                    "focused litchi-pages body-table hidden-axes integration test is missing #[test] coverage: "
                    f"{test_path}"
                )
            if not re.search(
                r"\b(?:body_table_hidden_axes|edit_body_table_hidden_axes|apply_body_table_hidden_axes)\b",
                test_code,
            ):
                violations.append(
                    "focused litchi-pages body-table hidden-axes integration test does not exercise the owner: "
                    f"{test_path}"
                )
            if test_path == PAGES_TABLE_HIDDEN_AXES_TEST_SOURCES[0]:
                expected_uid_map = str(PAGES_TABLE_HIDDEN_AXES_UID_MAP_MESSAGE_TYPE)
                wrong_uid_map = str(PAGES_TABLE_HIDDEN_AXES_WRONG_UID_MAP_MESSAGE_TYPE)
                if not re.search(
                    rf"\b(?:MESSAGE_TYPE|message_type|uid_map)[A-Za-z0-9_]*\b"
                    rf"[^;\n]*\b{re.escape(expected_uid_map[:1])}_?"
                    rf"{re.escape(expected_uid_map[1:])}\b",
                    test_code,
                    re.IGNORECASE,
                ):
                    violations.append(
                        "focused litchi-pages body-table hidden-axes integration test must use "
                        f"UID-map message type {PAGES_TABLE_HIDDEN_AXES_UID_MAP_MESSAGE_TYPE}: {test_path}"
                    )
                if re.search(
                    rf"\b(?:MESSAGE_TYPE|message_type|uid_map)[A-Za-z0-9_]*\b"
                    rf"[^;\n]*\b{re.escape(wrong_uid_map[:1])}_?"
                    rf"{re.escape(wrong_uid_map[1:])}\b",
                    test_code,
                    re.IGNORECASE,
                ):
                    violations.append(
                        "focused litchi-pages body-table hidden-axes integration test must not use "
                        f"Numbers table-data message type {PAGES_TABLE_HIDDEN_AXES_WRONG_UID_MAP_MESSAGE_TYPE}: {test_path}"
                    )
    for fuzz_path in PAGES_TABLE_HIDDEN_AXES_FUZZ_SOURCES:
        absolute = root / fuzz_path
        if not absolute.is_file():
            violations.append(
                "focused litchi-pages body-table hidden-axes boundary is missing fuzz target: "
                f"{fuzz_path}"
            )
        elif "fuzz_target!" not in absolute.read_text(encoding="utf-8"):
            violations.append(
                "focused litchi-pages body-table hidden-axes fuzz target is missing fuzz_target! harness: "
                f"{fuzz_path}"
            )
    for corpus in PAGES_TABLE_HIDDEN_AXES_FUZZ_CORPORA:
        if not (root / corpus).is_dir():
            violations.append(
                "focused litchi-pages body-table hidden-axes boundary is missing fuzz corpus: "
                f"{corpus}"
            )

    dedicated_sources = {
        root / path
        for path in PAGES_TABLE_HIDDEN_AXES_IMPLEMENTATION_SOURCES
        if (root / path).is_file()
    }
    helper_root = root / PAGES_TABLE_HIDDEN_AXES_OWNER_HELPER_ROOT
    if helper_root.is_dir():
        dedicated_sources.update(helper_root.rglob("*.rs"))
    export_sources = {
        root / path
        for path in PAGES_TABLE_HIDDEN_AXES_EXPORT_SOURCES
        if (root / path).is_file()
    }
    for path in sorted(dedicated_sources | export_sources):
        dedicated_source = path in dedicated_sources
        source = _mask_rust_cfg_test_items(path.read_text(encoding="utf-8"))
        declarations = [
            (declaration, line_number, True, dedicated_source)
            for declaration, line_number in _rust_public_declarations(source)
        ]
        if dedicated_source:
            declarations.extend(
                (declaration, line_number, False, False)
                for declaration, line_number in _rust_impl_headers(source)
            )
        for declaration, line_number, public_declaration, complete_scope in declarations:
            if not _is_pages_table_hidden_axes_public_declaration(
                declaration, dedicated_source=complete_scope
            ):
                continue
            identifiers = {
                match.group(1) for match in RUST_IDENTIFIER.finditer(declaration)
            }
            if public_declaration and "pub use" in declaration and "*" in declaration:
                violations.append(
                    "focused litchi-pages body-table hidden-axes public API retains a glob re-export: "
                    f"{path.relative_to(root)}:{line_number}"
                )
            for identifier in sorted(identifiers):
                reason = _pages_table_hidden_axes_public_leak(identifier)
                if reason is not None:
                    violations.append(
                        "focused litchi-pages body-table hidden-axes public API exposes "
                        f"{reason} {identifier}: {path.relative_to(root)}:{line_number}"
                    )
                if public_declaration and identifier in PAGES_TABLE_HIDDEN_AXES_FLAT_ALIASES:
                    violations.append(
                        "focused litchi-pages body-table hidden-axes public API retains flat alias "
                        f"{identifier}: {path.relative_to(root)}:{line_number}"
                    )
            for match in PAGES_TABLE_HIDDEN_AXES_PUBLIC_RAW_ID_PARAMETER.finditer(declaration):
                violations.append(
                    "focused litchi-pages body-table hidden-axes public API exposes raw parameter "
                    f"{match.group(0).strip()}: {path.relative_to(root)}:{line_number}"
                )
            for match in RUST_BYTE_SLICE.finditer(declaration):
                byte_slice = re.sub(r"\s+", "", match.group(0))
                violations.append(
                    "focused litchi-pages body-table hidden-axes public API exposes raw byte slice "
                    f"{byte_slice}: {path.relative_to(root)}:{line_number}"
                )

    # A second route in a sibling module defeats the package boundary even if
    # the canonical package/table exports above look correct.
    for path in sorted(source_root.rglob("*.rs")):
        source = _mask_rust_cfg_test_items(path.read_text(encoding="utf-8"))
        for declaration, line_number in _rust_public_declarations(source):
            identifiers = [
                match.group(1) for match in RUST_IDENTIFIER.finditer(declaration)
            ]
            if (
                identifiers[:3] == ["pub", "mod", "body_table_hidden_axes"]
                or (
                    identifiers[:3] == ["pub", "mod", "hidden_axes"]
                    and path != table_path
                )
            ):
                violations.append(
                    "focused litchi-pages body-table hidden-axes public API exposes duplicate module: "
                    f"{path.relative_to(root)}:{line_number}"
                )
            if identifiers[:2] == ["pub", "use"] and "*" in declaration:
                if {"body_table_hidden_axes", "hidden_axes", "package"} & set(identifiers):
                    violations.append(
                        "focused litchi-pages body-table hidden-axes public API retains root aliases via glob: "
                        f"{path.relative_to(root)}:{line_number}"
                    )
            if identifiers[:2] == ["pub", "use"] and "as" in identifiers:
                alias_index = identifiers.index("as")
                target_identifiers = identifiers[2:alias_index]
                target = target_identifiers[-1] if target_identifiers else ""
                alias = (
                    identifiers[alias_index + 1]
                    if alias_index + 1 < len(identifiers)
                    else ""
                )
                if (
                    target in PAGES_TABLE_HIDDEN_AXES_ALIAS_TARGETS
                    or "body_table_hidden_axes" in target_identifiers
                    or "hidden_axes" in target_identifiers
                ) and alias and alias != target:
                    if path == semantic_path and alias in PAGES_TABLE_HIDDEN_AXES_TRANSACTION_TYPES:
                        continue
                    if alias in PAGES_TABLE_HIDDEN_AXES_PUBLIC_NAMES:
                        continue
                    violations.append(
                        "focused litchi-pages body-table hidden-axes public API retains alternate alias "
                        f"{alias} for {target}: {path.relative_to(root)}:{line_number}"
                    )
            if identifiers[:2] == ["pub", "type"] and len(identifiers) >= 4:
                alias = identifiers[2]
                target_identifiers = identifiers[3:]
                target = target_identifiers[-1] if target_identifiers else ""
                if (
                    target in PAGES_TABLE_HIDDEN_AXES_ALIAS_TARGETS
                    or "body_table_hidden_axes" in target_identifiers
                    or "hidden_axes" in target_identifiers
                ) and alias != target and alias not in PAGES_TABLE_HIDDEN_AXES_PUBLIC_NAMES:
                    violations.append(
                        "focused litchi-pages body-table hidden-axes public API retains alternate alias "
                        f"{alias} for {target}: {path.relative_to(root)}:{line_number}"
                    )

    return sorted(set(violations))


# Keep the longer body-table spelling available to callers that use the owner
# terminology from the public API.
audit_pages_body_table_hidden_axes_facade_source_topology = (
    audit_pages_table_hidden_axes_facade_source_topology
)


def audit_pages_table_appearance_resource_source_topology(
    root: Path = ROOT,
) -> list[str]:
    """Require one bounded, prepared Pages appearance transaction."""

    if not _pages_table_appearance_owner_present(root):
        return []
    owner_path = root / PAGES_TABLE_APPEARANCE_OWNER_SOURCE
    owner_source = _mask_rust_cfg_test_items(owner_path.read_text(encoding="utf-8"))
    owner = _mask_rust_non_code(owner_source)
    violations: list[str] = []
    for label, markers in PAGES_TABLE_APPEARANCE_OWNER_MARKER_GROUPS.items():
        alternatives = PAGES_TABLE_APPEARANCE_OWNER_MARKER_ALTERNATIVES.get(label)
        has_markers = all(marker in owner for marker in markers)
        if not has_markers and alternatives is not None:
            has_markers = all(marker in owner for marker in alternatives)
        if not has_markers:
            violations.append(
                "focused litchi-pages body-table appearance owner is missing "
                f"{label} transaction marker: {PAGES_TABLE_APPEARANCE_OWNER_SOURCE}"
            )
    if re.search(
        r"deleted_previews\s*:\s*(?:usize\s*=\s*)?0|deleted_previews\s*=\s*0",
        owner,
    ) is None:
        violations.append(
            "focused litchi-pages body-table appearance owner must preserve previews "
            f"with deleted_previews = 0: {PAGES_TABLE_APPEARANCE_OWNER_SOURCE}"
        )
    for label, pattern in PAGES_TABLE_APPEARANCE_FORBIDDEN_OWNER_PATTERNS:
        match = pattern.search(owner)
        if match is not None:
            line_number = owner.count("\n", 0, match.start()) + 1
            violations.append(
                "focused litchi-pages body-table appearance owner must not perform "
                f"{label}: {PAGES_TABLE_APPEARANCE_OWNER_SOURCE}:{line_number}"
            )
    return sorted(set(violations))


# Longer aliases keep the ratchet discoverable to callers that use the body
# terminology from the public owner name.
audit_iwa_pages_body_table_appearance_source_topology = (
    audit_iwa_pages_table_appearance_source_topology
)
audit_pages_body_table_appearance_facade_source_topology = (
    audit_pages_table_appearance_facade_source_topology
)
audit_pages_body_table_appearance_resource_source_topology = (
    audit_pages_table_appearance_resource_source_topology
)


RETIRED_IWA_PAGES_HEADER_FOOTER_NUMBER_ATTACHMENT_METHODS = frozenset(
    {
        "header_footer_number_attachments",
        "insert_header_footer_number_attachment",
        "update_header_footer_number_attachment",
        "remove_header_footer_number_attachment",
    }
)
PAGES_HEADER_FOOTER_LEGACY_MARKERS = frozenset(
    {
        "legacy_header_footer",
        "header_footer_legacy",
        "legacy_fallback",
        "LegacyFallback",
        "fallback_header_footer",
    }
)


def audit_iwa_pages_header_footer_source_topology(
    root: Path = ROOT,
) -> list[str]:
    """Retire the raw Pages header/footer host after owner activation.

    Header/footer discovery and text mutation currently live on
    ``PagesEditor`` and expose ``TextStorageId``/``PagesHeaderFooterInfo``.
    Keep this audit dormant until the private package owner exists so the
    compatibility host remains an intentional migration baseline.  Activation
    is deliberately item-scoped: unrelated Pages graph readers remain valid,
    while every old discovery/mutation method, public info type, and legacy
    fallback is rejected.  cfg(test) fixtures are masked one item at a time.
    """

    if not _pages_header_footer_owner_present(root):
        return []

    violations: list[str] = []
    source_root = root / IWA_PAGES_SOURCE_ROOT
    if source_root.is_dir():
        for path in sorted(source_root.rglob("*.rs")):
            production_source = _mask_rust_cfg_test_items(
                path.read_text(encoding="utf-8")
            )
            code = _mask_rust_non_code(production_source)
            for declaration, line_number in _rust_public_declarations(
                production_source
            ):
                for method in sorted(RETIRED_IWA_PAGES_HEADER_FOOTER_METHOD_SET):
                    if re.search(
                        rf"\bfn[ \t\r\n]+(?:r#)?{re.escape(method)}\b",
                        declaration,
                    ) is not None:
                        violations.append(
                            "retired litchi-iwa Pages header/footer method "
                            f"{method}: {path.relative_to(root)}:{line_number}"
                        )
            for declaration, line_number in _rust_public_declarations(
                production_source
            ):
                function = RUST_FUNCTION_DECLARATION.search(declaration)
                if function is None:
                    continue
                method = function.group(1)
                if (
                    method in RETIRED_IWA_PAGES_HEADER_FOOTER_NUMBER_ATTACHMENT_METHODS
                    and "HeaderFooterSelector"
                    not in {
                        match.group(1)
                        for match in RUST_IDENTIFIER.finditer(declaration)
                    }
                ):
                    violations.append(
                        "retired litchi-iwa Pages header/footer number-attachment "
                        f"method {method} must accept HeaderFooterSelector: "
                        f"{path.relative_to(root)}:{line_number}"
                    )

            for match in re.finditer(
                rf"(?<![A-Za-z0-9_#]){re.escape(RETIRED_IWA_PAGES_HEADER_FOOTER_INFO_TYPE)}"
                r"(?![A-Za-z0-9_])",
                code,
            ):
                line_number = code.count("\n", 0, match.start()) + 1
                violations.append(
                    "retired litchi-iwa Pages header/footer info type "
                    f"{RETIRED_IWA_PAGES_HEADER_FOOTER_INFO_TYPE}: "
                    f"{path.relative_to(root)}:{line_number}"
                )
            for marker in sorted(PAGES_HEADER_FOOTER_LEGACY_MARKERS):
                for match in re.finditer(
                    rf"(?<![A-Za-z0-9_]){re.escape(marker)}(?![A-Za-z0-9_])",
                    code,
                ):
                    line_number = code.count("\n", 0, match.start()) + 1
                    violations.append(
                        "retired litchi-iwa Pages header/footer legacy fallback "
                        f"{marker}: {path.relative_to(root)}:{line_number}"
                    )
            for match in IWA_PAGES_HEADER_FOOTER_CALL.finditer(code):
                line_start = code.rfind("\n", 0, match.start()) + 1
                line_end = code.find("\n", match.end())
                if line_end < 0:
                    line_end = len(code)
                # A declaration is reported above; this branch catches a
                # differently named compatibility helper calling the old API.
                if re.search(
                    rf"\bfn[ \t\r\n]+{re.escape(match.group('method'))}\b",
                    code[line_start:line_end],
                ):
                    continue
                line_number = code.count("\n", 0, match.start("method")) + 1
                violations.append(
                    "retired litchi-iwa Pages header/footer call "
                    f"{match.group('method')}: {path.relative_to(root)}:{line_number}"
                )

    example_root = root / IWA_PAGES_HEADER_FOOTER_EXAMPLE_ROOT
    if example_root.is_dir():
        for example_path in sorted(example_root.rglob("*.rs")):
            source = _mask_rust_non_code(
                _mask_rust_cfg_test_items(example_path.read_text(encoding="utf-8"))
            )
            for marker in sorted(PAGES_HEADER_FOOTER_LEGACY_MARKERS):
                if re.search(
                    rf"(?<![A-Za-z0-9_]){re.escape(marker)}(?![A-Za-z0-9_])",
                    source,
                ) is not None:
                    line_number = source.count("\n", 0, source.find(marker)) + 1
                    violations.append(
                        "retired litchi-iwa Pages header/footer example legacy "
                        f"fallback {marker}: {example_path.relative_to(root)}:{line_number}"
                    )
            for match in IWA_PAGES_HEADER_FOOTER_CALL.finditer(source):
                line_number = source.count("\n", 0, match.start("method")) + 1
                violations.append(
                    "retired litchi-iwa Pages header/footer example call "
                    f"{match.group('method')}: {example_path.relative_to(root)}:{line_number}"
                )
            if re.search(
                rf"\b{re.escape(RETIRED_IWA_PAGES_HEADER_FOOTER_INFO_TYPE)}\b",
                source,
            ):
                line_number = source.count(
                    "\n", 0, source.find(RETIRED_IWA_PAGES_HEADER_FOOTER_INFO_TYPE)
                ) + 1
                violations.append(
                    "retired litchi-iwa Pages header/footer example info type: "
                    f"{example_path.relative_to(root)}:{line_number}"
                )

    readme_path = root / IWA_PAGES_README
    if readme_path.is_file():
        source = readme_path.read_text(encoding="utf-8")
        for pattern in IWA_PAGES_README_HEADER_FOOTER_CALLS:
            for match in pattern.finditer(source):
                line_number = source.count("\n", 0, match.start("method")) + 1
                violations.append(
                    "retired litchi-iwa Pages header/footer README call "
                    f"{match.group('method')}: {IWA_PAGES_README}:{line_number}"
                )
        if re.search(
            rf"\b{re.escape(RETIRED_IWA_PAGES_HEADER_FOOTER_INFO_TYPE)}\b",
            source,
        ):
            line_number = source.count(
                "\n", 0, source.find(RETIRED_IWA_PAGES_HEADER_FOOTER_INFO_TYPE)
            ) + 1
            violations.append(
                "retired litchi-iwa Pages header/footer README info type: "
                f"{IWA_PAGES_README}:{line_number}"
            )

    return sorted(set(violations))


def _pages_section_text_owner_present(root: Path) -> bool:
    """Return whether the focused Pages section-text owner has landed."""

    return (root / PAGES_SECTION_TEXT_OWNER_SOURCE).is_file()


def audit_iwa_pages_section_text_source_topology(
    root: Path = ROOT,
) -> list[str]:
    """Retire raw Pages section-text methods after owner activation.

    The package owner is the activation token.  Once present, no raw section
    identity, focused fallback bridge, or old example/documentation route may
    remain in production.  Individual ``cfg(test)`` items are masked rather
    than truncating a source file at its first test module.
    """

    if not _pages_section_text_owner_present(root):
        return []

    violations: list[str] = []
    source_root = root / IWA_PAGES_SOURCE_ROOT
    if source_root.is_dir():
        for path in sorted(source_root.rglob("*.rs")):
            # `editor/tests.rs` is included by an outer `#[cfg(test)] mod`
            # declaration and therefore has no item-level attribute of its
            # own.  It is wholly test-only, so keep it outside production
            # retirement scanning while preserving item-level masking for
            # mixed production modules.
            if path == root / IWA_PAGES_EDITOR_TEST_SOURCE:
                continue
            production_source = _mask_rust_cfg_test_items(
                path.read_text(encoding="utf-8")
            )
            code = _mask_rust_non_code(production_source)
            for name, line_number in _rust_function_declarations(production_source):
                if name in RETIRED_IWA_PAGES_SECTION_TEXT_METHOD_SET:
                    violations.append(
                        "retired litchi-iwa Pages section-text method "
                        f"{name}: {path.relative_to(root)}:{line_number}"
                    )

            for name, line_number in _rust_function_declarations(production_source):
                if name in RETIRED_IWA_PAGES_SECTION_TEXT_HELPERS:
                    violations.append(
                        "retired litchi-iwa Pages section-text legacy helper "
                        f"{name}: {path.relative_to(root)}:{line_number}"
                    )

            for type_name in sorted(RETIRED_IWA_PAGES_SECTION_TEXT_TYPES):
                for match in re.finditer(
                    rf"\b(?:struct|enum|type)\s+{re.escape(type_name)}\b", code
                ):
                    line_number = code.count("\n", 0, match.start()) + 1
                    violations.append(
                        "retired litchi-iwa Pages section-text bridge type "
                        f"{type_name}: {path.relative_to(root)}:{line_number}"
                    )

            for marker in sorted(IWA_PAGES_SECTION_TEXT_LEGACY_MARKERS):
                for match in re.finditer(
                    rf"(?<![A-Za-z0-9_]){re.escape(marker)}(?![A-Za-z0-9_])",
                    code,
                ):
                    line_number = code.count("\n", 0, match.start()) + 1
                    # The declarations/helpers above have a more useful
                    # diagnostic; this catches a helper imported or called
                    # from another production module.
                    if marker in RETIRED_IWA_PAGES_SECTION_TEXT_HELPERS:
                        continue
                    violations.append(
                        "retired litchi-iwa Pages section-text legacy fallback "
                        f"{marker}: {path.relative_to(root)}:{line_number}"
                    )

            for match in IWA_PAGES_SECTION_TEXT_CALL.finditer(code):
                line_start = code.rfind("\n", 0, match.start()) + 1
                line_end = code.find("\n", match.end())
                if line_end < 0:
                    line_end = len(code)
                line = code[line_start:line_end]
                # Calls on the focused package are the replacement seam.  A
                # host receiver (including `self`) is the retired raw-ID API.
                if (
                    "Package::" in line
                    or ".package." in line
                    or match.group("receiver") in {"package", "focused_package"}
                ):
                    continue
                if re.search(
                    rf"\bfn[ \t\r\n]+{re.escape(match.group('method'))}\b",
                    line,
                ):
                    continue
                line_number = code.count("\n", 0, match.start("method")) + 1
                violations.append(
                    "retired litchi-iwa Pages section-text call "
                    f"{match.group('method')}: {path.relative_to(root)}:{line_number}"
                )

    example_root = root / IWA_PAGES_SECTION_TEXT_EXAMPLE_ROOT
    if example_root.is_dir():
        for example_path in sorted(example_root.rglob("*.rs")):
            source = _mask_rust_non_code(
                _mask_rust_cfg_test_items(example_path.read_text(encoding="utf-8"))
            )
            for match in IWA_PAGES_SECTION_TEXT_CALL.finditer(source):
                if match.group("receiver") in {"package", "focused_package"}:
                    continue
                line_number = source.count("\n", 0, match.start("method")) + 1
                violations.append(
                    "retired litchi-iwa Pages section-text example call "
                    f"{match.group('method')}: {example_path.relative_to(root)}:{line_number}"
                )
            for marker in sorted(IWA_PAGES_SECTION_TEXT_LEGACY_MARKERS):
                if re.search(
                    rf"(?<![A-Za-z0-9_]){re.escape(marker)}(?![A-Za-z0-9_])",
                    source,
                ):
                    line_number = source.count("\n", 0, source.find(marker)) + 1
                    violations.append(
                        "retired litchi-iwa Pages section-text example legacy "
                        f"fallback {marker}: {example_path.relative_to(root)}:{line_number}"
                    )

    readme_path = root / IWA_PAGES_README
    if readme_path.is_file():
        source = readme_path.read_text(encoding="utf-8")
        for pattern in IWA_PAGES_README_SECTION_TEXT_CALLS:
            for match in pattern.finditer(source):
                line_number = source.count("\n", 0, match.start("method")) + 1
                violations.append(
                    "retired litchi-iwa Pages section-text README call "
                    f"{match.group('method')}: {IWA_PAGES_README}:{line_number}"
                )

    violations.extend(
        _audit_iwa_standalone_retired_routes(
            root,
            ecosystem="Pages",
            label="Pages",
        )
    )
    return sorted(set(violations))


def audit_iwa_pages_footnote_text_source_topology(root: Path = ROOT) -> list[str]:
    """Retire the Pages host footnote-text setter while preserving graph APIs."""

    source_root = root / IWA_PAGES_SOURCE_ROOT
    if not source_root.is_dir():
        return []

    violations: list[str] = []
    for path in sorted(source_root.rglob("*.rs")):
        production_source = _mask_rust_cfg_test_items(
            path.read_text(encoding="utf-8")
        )
        for declaration, line_number in _rust_public_declarations(production_source):
            for method in sorted(RETIRED_IWA_PAGES_FOOTNOTE_TEXT_METHOD_SET):
                if re.search(
                    rf"\bfn[ \t\r\n]+(?:r#)?{re.escape(method)}\b",
                    declaration,
                ) is None:
                    continue
                violations.append(
                    "retired litchi-iwa Pages footnote-text public method "
                    f"{method}: {path.relative_to(root)}:{line_number}"
                )

        code = _mask_rust_non_code(production_source)
        for match in IWA_PAGES_FOOTNOTE_TEXT_CALL.finditer(code):
            line_number = code.count("\n", 0, match.start()) + 1
            violations.append(
                "retired litchi-iwa Pages footnote-text call "
                f"{match.group(0).strip()}: {path.relative_to(root)}:{line_number}"
            )

    example_root = root / IWA_PAGES_FOOTNOTE_TEXT_EXAMPLE_ROOT
    if example_root.is_dir():
        for example_path in sorted(example_root.rglob("*.rs")):
            production_source = _mask_rust_cfg_test_items(
                example_path.read_text(encoding="utf-8")
            )
            code = _mask_rust_non_code(production_source)
            for match in IWA_PAGES_FOOTNOTE_TEXT_CALL.finditer(code):
                line_number = code.count("\n", 0, match.start()) + 1
                violations.append(
                    "retired litchi-iwa Pages footnote-text example call "
                    f"set_body_footnote_text: "
                    f"{example_path.relative_to(root)}:{line_number}"
                )

    return sorted(set(violations))


def _pages_footnote_lifecycle_owner_present(root: Path) -> bool:
    """Return whether the private focused body-footnote owner has landed.

    A package-module declaration can be introduced while an owner is being
    assembled.  Treat the dedicated source file as the activation token so a
    half-landed migration does not turn the dormant ratchet into repository
    noise; once that file exists the private-module and complete-contract
    checks fail closed.
    """

    return (root / PAGES_FOOTNOTE_LIFECYCLE_OWNER_SOURCE).is_file()


def audit_iwa_pages_footnote_lifecycle_source_topology(
    root: Path = ROOT,
) -> list[str]:
    """Retire raw Pages body-footnote lifecycle paths after owner activation.

    The focused package owns the complete lifecycle. Activation retires the
    two host mutators, the public host reader, and the private package
    ingress/publication bridge; graph readers and ordinary-body cleanup remain
    outside this narrow ratchet.
    """

    if not _pages_footnote_lifecycle_owner_present(root):
        return []

    violations: list[str] = []
    source_root = root / IWA_PAGES_SOURCE_ROOT
    if source_root.is_dir():
        for path in sorted(source_root.rglob("*.rs")):
            production_source = _mask_rust_cfg_test_items(
                path.read_text(encoding="utf-8")
            )
            for declaration, line_number in _rust_public_declarations(
                production_source
            ):
                for method in sorted(RETIRED_IWA_PAGES_FOOTNOTE_LIFECYCLE_METHOD_SET):
                    if re.search(
                        rf"\bfn[ \t\r\n]+(?:r#)?{re.escape(method)}\b",
                        declaration,
                    ) is None:
                        continue
                    violations.append(
                        "retired litchi-iwa Pages body-footnote lifecycle public "
                        f"method {method}: {path.relative_to(root)}:{line_number}"
                    )
                for method in sorted(RETIRED_IWA_PAGES_FOOTNOTE_READ_METHOD_SET):
                    if re.search(
                        rf"\bfn[ \t\r\n]+(?:r#)?{re.escape(method)}\b",
                        declaration,
                    ) is None:
                        continue
                    violations.append(
                        "retired litchi-iwa Pages body-footnote public read method "
                        f"{method}: {path.relative_to(root)}:{line_number}"
                    )

            code = _mask_rust_non_code(production_source)
            for match in IWA_PAGES_FOOTNOTE_LIFECYCLE_CALL.finditer(code):
                # Focused Package calls are the replacement route and are
                # allowed to retain the semantic method names. The ratchet
                # targets host PagesEditor compatibility calls only.
                if match.group("receiver") in {"Package", "PagesPackage"}:
                    continue
                line_start = code.rfind("\n", 0, match.start()) + 1
                line_end = code.find("\n", match.end())
                if line_end < 0:
                    line_end = len(code)
                # A declaration has already been handled above; this call
                # branch catches a differently named compatibility helper.
                if re.search(
                    rf"\bfn[ \t\r\n]+{re.escape(match.group('method'))}\b",
                    code[line_start:line_end],
                ):
                    continue
                line_number = code.count("\n", 0, match.start("method")) + 1
                violations.append(
                    "retired litchi-iwa Pages body-footnote lifecycle call "
                    f"{match.group('method')}: {path.relative_to(root)}:{line_number}"
                )
            for match in IWA_PAGES_FOOTNOTE_READ_CALL.finditer(code):
                line_number = code.count("\n", 0, match.start()) + 1
                violations.append(
                    "retired litchi-iwa Pages body-footnote public read call "
                    f"body_footnotes: {path.relative_to(root)}:{line_number}"
                )
            for match in IWA_PAGES_FOOTNOTE_FACADE_HELPER.finditer(code):
                line_number = code.count("\n", 0, match.start("helper")) + 1
                violations.append(
                    "retired litchi-iwa Pages body-footnote facade helper "
                    f"{match.group('helper')}: {path.relative_to(root)}:{line_number}"
                )

    example_root = root / IWA_PAGES_FOOTNOTE_LIFECYCLE_EXAMPLE_ROOT
    if example_root.is_dir():
        for example_path in sorted(example_root.rglob("*.rs")):
            source = _mask_rust_non_code(
                _mask_rust_cfg_test_items(example_path.read_text(encoding="utf-8"))
            )
            for match in IWA_PAGES_FOOTNOTE_LIFECYCLE_CALL.finditer(source):
                if match.group("receiver") in {"Package", "PagesPackage"}:
                    continue
                line_number = source.count("\n", 0, match.start("method")) + 1
                violations.append(
                    "retired litchi-iwa Pages body-footnote lifecycle example "
                    f"call {match.group('method')}: "
                    f"{example_path.relative_to(root)}:{line_number}"
                )
            for match in IWA_PAGES_FOOTNOTE_READ_CALL.finditer(source):
                line_number = source.count("\n", 0, match.start()) + 1
                violations.append(
                    "retired litchi-iwa Pages body-footnote public read example "
                    f"call body_footnotes: {example_path.relative_to(root)}:{line_number}"
                )

    readme_path = root / IWA_PAGES_README
    if readme_path.is_file():
        source = readme_path.read_text(encoding="utf-8")
        for pattern in IWA_PAGES_README_FOOTNOTE_LIFECYCLE_CALLS:
            for match in pattern.finditer(source):
                line_number = source.count("\n", 0, match.start("method")) + 1
                violations.append(
                    "retired litchi-iwa Pages body-footnote lifecycle README "
                    f"call {match.group('method')}: {IWA_PAGES_README}:{line_number}"
                )
        for pattern in IWA_PAGES_README_FOOTNOTE_READ_CALLS:
            for match in pattern.finditer(source):
                line_number = source.count("\n", 0, match.start("method")) + 1
                violations.append(
                    "retired litchi-iwa Pages body-footnote public read README "
                    f"call {match.group('method')}: {IWA_PAGES_README}:{line_number}"
                )

    return sorted(set(violations))


def audit_pages_footnote_text_facade_source_topology(
    root: Path = ROOT,
) -> list[str]:
    """Require the focused Pages package footnote-text edit route."""

    source_root = root / PAGES_SOURCE_ROOT
    if not source_root.is_dir():
        return []

    owner_path = root / PAGES_FOOTNOTE_TEXT_OWNER_SOURCE
    owner_source = (
        _mask_rust_cfg_test_items(owner_path.read_text(encoding="utf-8"))
        if owner_path.is_file()
        else ""
    )
    methods = {
        name for name, _declaration, _line_number in _rust_public_methods_in_impl(
            owner_source, "Package"
        )
    }
    if PAGES_FOOTNOTE_TEXT_PACKAGE_METHOD in methods:
        return []
    return [
        "focused litchi-pages footnote-text public API is missing Package method "
        f"{PAGES_FOOTNOTE_TEXT_PACKAGE_METHOD}: {PAGES_FOOTNOTE_TEXT_OWNER_SOURCE}"
    ]


def audit_pages_footnote_lifecycle_facade_source_topology(
    root: Path = ROOT,
) -> list[str]:
    """Enforce the dormant selector-first body-footnote lifecycle contract."""

    source_root = root / PAGES_SOURCE_ROOT
    if not source_root.is_dir() or not _pages_footnote_lifecycle_owner_present(root):
        return []

    violations: list[str] = []
    semantic_path = root / PAGES_FOOTNOTE_LIFECYCLE_SEMANTIC_SOURCE
    semantic_source = (
        _mask_rust_cfg_test_items(semantic_path.read_text(encoding="utf-8"))
        if semantic_path.is_file()
        else ""
    )
    semantic_exports = _rust_canonical_exports(
        semantic_source,
        frozenset(PAGES_FOOTNOTE_LIFECYCLE_SEMANTIC_TYPES),
    )
    for name in PAGES_FOOTNOTE_LIFECYCLE_SEMANTIC_TYPES:
        if name in semantic_exports:
            continue
        violations.append(
            "focused litchi-pages body-footnote public API is missing semantic "
            f"footnote::body type {name}: "
            f"{PAGES_FOOTNOTE_LIFECYCLE_SEMANTIC_SOURCE}"
        )

    selector_source = semantic_source
    for name in ("Selector", "Position"):
        if name in _rust_canonical_exports(selector_source, frozenset({name})):
            continue
        violations.append(
            "focused litchi-pages body-footnote public API is missing semantic "
            f"selector/{name}: {PAGES_FOOTNOTE_LIFECYCLE_SELECTOR_SOURCE}"
        )

    owner_path = root / PAGES_FOOTNOTE_LIFECYCLE_OWNER_SOURCE
    package_path = root / PAGES_FOOTNOTE_LIFECYCLE_EXPORT_SOURCES[1]
    package_source = (
        _mask_rust_non_code(package_path.read_text(encoding="utf-8"))
        if package_path.is_file()
        else ""
    )
    if PAGES_PACKAGE_FOOTNOTE_LIFECYCLE_MODULE.search(package_source) is None:
        violations.append(
            "focused litchi-pages body-footnote public API is missing private "
            "package owner module: "
            f"{PAGES_FOOTNOTE_LIFECYCLE_EXPORT_SOURCES[1]}"
        )
    for match in PUBLIC_PAGES_PACKAGE_FOOTNOTE_LIFECYCLE_MODULE.finditer(
        package_source
    ):
        line_number = package_source.count("\n", 0, match.start()) + 1
        violations.append(
            "focused litchi-pages body-footnote public API exposes public "
            "package::body_footnote module: "
            f"{PAGES_FOOTNOTE_LIFECYCLE_EXPORT_SOURCES[1]}:{line_number}"
        )
    if not owner_path.is_file():
        violations.append(
            "focused litchi-pages body-footnote public API is missing private "
            f"package owner source: {PAGES_FOOTNOTE_LIFECYCLE_OWNER_SOURCE}"
        )

    dedicated_sources = {
        root / path
        for path in PAGES_FOOTNOTE_LIFECYCLE_IMPLEMENTATION_SOURCES
        if (root / path).is_file()
    }
    helper_root = root / PAGES_FOOTNOTE_LIFECYCLE_OWNER_HELPER_ROOT
    if helper_root.is_dir():
        dedicated_sources.update(helper_root.rglob("*.rs"))
    export_sources = {
        root / path
        for path in PAGES_FOOTNOTE_LIFECYCLE_EXPORT_SOURCES
        if (root / path).is_file()
    }

    owner_parts = [
        _mask_rust_cfg_test_items(path.read_text(encoding="utf-8"))
        for path in sorted(dedicated_sources)
        if path != semantic_path and path.is_file()
    ]
    owner_source = "\n".join(owner_parts)
    canonical_exports = _rust_canonical_exports(
        owner_source,
        frozenset(PAGES_FOOTNOTE_LIFECYCLE_CANONICAL_TYPES),
    )
    for name in PAGES_FOOTNOTE_LIFECYCLE_CANONICAL_TYPES:
        if name in canonical_exports:
            continue
        violations.append(
            "focused litchi-pages body-footnote public API is missing canonical "
            f"package type {name}: {PAGES_FOOTNOTE_LIFECYCLE_OWNER_SOURCE}"
        )

    owner_methods = {
        name
        for source in owner_parts
        for name, _declaration, _line_number in _rust_public_methods_in_impl(
            source, "Package"
        )
    }
    for method in PAGES_FOOTNOTE_LIFECYCLE_PACKAGE_METHODS:
        if method in owner_methods:
            continue
        violations.append(
            "focused litchi-pages body-footnote public API is missing Package "
            f"method {method}: {PAGES_FOOTNOTE_LIFECYCLE_OWNER_SOURCE}"
        )
    for method in sorted(PAGES_FOOTNOTE_LIFECYCLE_FLAT_METHODS & owner_methods):
        violations.append(
            "focused litchi-pages body-footnote public API retains flat Package "
            f"method {method}: {PAGES_FOOTNOTE_LIFECYCLE_OWNER_SOURCE}"
        )

    lib_path = root / PAGES_FOOTNOTE_LIFECYCLE_EXPORT_SOURCES[0]
    lib_source = (
        _mask_rust_cfg_test_items(lib_path.read_text(encoding="utf-8"))
        if lib_path.is_file()
        else ""
    )
    if PUBLIC_PAGES_FOOTNOTE_MODULE.search(_mask_rust_non_code(lib_source)) is None:
        violations.append(
            "focused litchi-pages body-footnote public API is missing canonical "
            f"root footnote module: {PAGES_FOOTNOTE_LIFECYCLE_EXPORT_SOURCES[0]}"
        )
    root_exports = _rust_canonical_exports(
        lib_source, frozenset(PAGES_FOOTNOTE_LIFECYCLE_CANONICAL_TYPES)
    )
    for name in PAGES_FOOTNOTE_LIFECYCLE_CANONICAL_TYPES:
        if name in root_exports:
            continue
        violations.append(
            "focused litchi-pages body-footnote public API is missing root "
            f"re-export {name}: {PAGES_FOOTNOTE_LIFECYCLE_EXPORT_SOURCES[0]}"
        )

    footnote_path = root / PAGES_FOOTNOTE_LIFECYCLE_EXPORT_SOURCES[2]
    footnote_source = (
        _mask_rust_non_code(
            _mask_rust_cfg_test_items(footnote_path.read_text(encoding="utf-8"))
        )
        if footnote_path.is_file()
        else ""
    )
    if PUBLIC_PAGES_FOOTNOTE_BODY_MODULE.search(footnote_source) is None:
        violations.append(
            "focused litchi-pages body-footnote public API is missing canonical "
            f"footnote::body module: {PAGES_FOOTNOTE_LIFECYCLE_EXPORT_SOURCES[2]}"
        )

    if package_path.is_file():
        package_code = _mask_rust_comments(package_source)
        if PAGES_PACKAGE_FOOTNOTE_LIFECYCLE_MODULE.search(package_code) is None:
            violations.append(
                "focused litchi-pages body-footnote public API is missing private "
                f"package owner module: {PAGES_FOOTNOTE_LIFECYCLE_EXPORT_SOURCES[1]}"
            )

    # Inspect the complete focused source tree after masking cfg(test) items.
    # This catches a new sibling's alias or public module without treating
    # source-built fixtures as production API.
    for path in sorted(source_root.rglob("*.rs")):
        production_source = _mask_rust_cfg_test_items(
            path.read_text(encoding="utf-8")
        )
        for declaration, line_number in _rust_public_declarations(production_source):
            identifiers = [
                match.group(1) for match in RUST_IDENTIFIER.finditer(declaration)
            ]
            if identifiers[:3] == ["pub", "mod", "body_footnote"]:
                violations.append(
                    "focused litchi-pages body-footnote public API exposes duplicate "
                    f"body_footnote module: {path.relative_to(root)}:{line_number}"
                )
            if identifiers[:2] == ["pub", "use"] and "*" in declaration:
                if {"body_footnote", "footnote", "package"} & set(identifiers):
                    violations.append(
                        "focused litchi-pages body-footnote public API retains root "
                        "aliases via owner glob: "
                        f"{path.relative_to(root)}:{line_number}"
                    )
            if identifiers[:2] == ["pub", "use"] and "as" in identifiers:
                alias_index = identifiers.index("as")
                target_identifiers = identifiers[2:alias_index]
                alias = (
                    identifiers[alias_index + 1]
                    if alias_index + 1 < len(identifiers)
                    else ""
                )
                target = target_identifiers[-1] if target_identifiers else ""
                if (
                    target in PAGES_FOOTNOTE_LIFECYCLE_ALIAS_TARGETS
                    or "body_footnote" in target_identifiers
                    or ("footnote" in target_identifiers and "body" in target_identifiers)
                ) and alias and alias != target:
                    if path == semantic_path and alias in {
                        "Commit",
                        "Diagnostics",
                        "Edit",
                        "Error",
                        "LimitKind",
                        "Patch",
                    }:
                        continue
                    violations.append(
                        "focused litchi-pages body-footnote public API retains "
                        f"alternate alias {alias} for {target}: "
                        f"{path.relative_to(root)}:{line_number}"
                    )
            if identifiers[:2] == ["pub", "type"] and len(identifiers) >= 4:
                alias = identifiers[2]
                target_identifiers = identifiers[3:]
                target = target_identifiers[-1] if target_identifiers else ""
                if (
                    target in PAGES_FOOTNOTE_LIFECYCLE_ALIAS_TARGETS
                    or "body_footnote" in target_identifiers
                    or ("footnote" in target_identifiers and "body" in target_identifiers)
                ) and alias != target:
                    violations.append(
                        "focused litchi-pages body-footnote public API retains "
                        f"alternate alias {alias} for {target}: "
                        f"{path.relative_to(root)}:{line_number}"
                    )

    for path in sorted(dedicated_sources | export_sources):
        dedicated_source = path in dedicated_sources
        production_source = _mask_rust_cfg_test_items(
            path.read_text(encoding="utf-8")
        )
        declarations = [
            (declaration, line_number, True, dedicated_source)
            for declaration, line_number in _rust_public_declarations(
                production_source
            )
        ]
        if dedicated_source:
            declarations.extend(
                (declaration, line_number, False, False)
                for declaration, line_number in _rust_impl_headers(production_source)
            )
        for (
            declaration,
            line_number,
            public_declaration,
            complete_source_scope,
        ) in declarations:
            if not _is_pages_footnote_lifecycle_public_declaration(
                declaration, dedicated_source=complete_source_scope
            ):
                continue
            identifiers = [
                match.group(1) for match in RUST_IDENTIFIER.finditer(declaration)
            ]
            if (
                public_declaration
                and path in export_sources
                and identifiers[:2] == ["pub", "use"]
                and "*" in declaration
            ):
                violations.append(
                    "focused litchi-pages body-footnote public API retains root "
                    f"aliases via owner glob: {path.relative_to(root)}:{line_number}"
                )
            for match in RUST_IDENTIFIER.finditer(declaration):
                identifier = match.group(1)
                identifier_line = line_number + declaration.count(
                    "\n", 0, match.start(1)
                )
                if public_declaration and identifier in PAGES_FOOTNOTE_LIFECYCLE_FLAT_ALIASES:
                    violations.append(
                        "focused litchi-pages body-footnote public API retains flat "
                        f"alias {identifier}: {path.relative_to(root)}:{identifier_line}"
                    )
                reason = _pages_footnote_lifecycle_public_leak(identifier)
                if reason is not None:
                    violations.append(
                        "focused litchi-pages body-footnote public API exposes "
                        f"{reason} {identifier}: {path.relative_to(root)}:{identifier_line}"
                    )
            for match in RUST_BYTE_SLICE.finditer(declaration):
                byte_slice = re.sub(r"\s+", "", match.group(0))
                byte_slice_line = line_number + declaration.count(
                    "\n", 0, match.start()
                )
                violations.append(
                    "focused litchi-pages body-footnote public API exposes raw byte "
                    f"slice {byte_slice}: {path.relative_to(root)}:{byte_slice_line}"
                )

    return sorted(set(violations))


def _audit_iwa_chart_caption_source_topology(
    root: Path,
    source_path: Path,
    family: str,
    read_functions: tuple[str, ...],
    legacy_rewrite_markers: frozenset[str],
) -> list[str]:
    """Audit one host's focused chart-caption edge without scanning its graph.

    Pages and Numbers still need their broader chart graph readers, including
    generated ``IWorkChartArchive`` decodes in ``graph.rs``.  The caption
    module is a narrower ownership boundary: its selected edge must go
    through the neutral ``caption_edge`` helper, and its production source
    must not retain the old generated/wire patch path.  Masking individual
    ``cfg(test)`` items is
    important here because both modules keep source-built compatibility
    fixtures beside production functions.
    """

    path = root / source_path
    if not path.is_file():
        return [
            f"focused litchi-iwa {family} chart-caption source is missing: "
            f"{source_path}"
        ]

    violations: list[str] = []
    relative = source_path
    production_source = _mask_rust_cfg_test_items(path.read_text(encoding="utf-8"))
    source = _mask_rust_non_code(production_source)

    codec_lib_path = root / IWA_CHART_CAPTION_CODEC_PUBLIC_SOURCE
    codec_impl_path = root / IWA_CHART_CAPTION_CODEC_IMPLEMENTATION_SOURCE
    codec_lib_source = ""
    codec_impl_source = ""
    if not codec_lib_path.is_file():
        violations.append(
            f"focused litchi-iwa {family} chart-caption source is missing the "
            f"hidden neutral {IWA_CHART_CAPTION_CODEC_MODULE} module: "
            f"{IWA_CHART_CAPTION_CODEC_PUBLIC_SOURCE}"
        )
    else:
        codec_lib_source = codec_lib_path.read_text(encoding="utf-8")
        alias = IWA_CHART_CAPTION_CODEC_HIDDEN_ALIAS.search(codec_lib_source)
        if alias is None or not re.search(
            r"\bpub\s+use\s+super\s*::\s*keynote_chart_caption_codec\s*::\s*\*",
            alias.group("body") if alias is not None else "",
        ):
            violations.append(
                f"focused litchi-iwa {family} chart-caption source requires the "
                f"#[doc(hidden)] neutral {IWA_CHART_CAPTION_CODEC_MODULE} alias: "
                f"{IWA_CHART_CAPTION_CODEC_PUBLIC_SOURCE}"
            )
    if not codec_impl_path.is_file():
        violations.append(
            f"focused litchi-iwa {family} chart-caption source is missing the strict "
            f"codec implementation: {IWA_CHART_CAPTION_CODEC_IMPLEMENTATION_SOURCE}"
        )
    else:
        codec_impl_source = _mask_rust_non_code(
            _mask_rust_cfg_test_items(codec_impl_path.read_text(encoding="utf-8"))
        )
        for api in IWA_CHART_CAPTION_CODEC_REQUIRED_APIS:
            if re.search(
                rf"(?m)^\s*pub\s+fn\s+{re.escape(api)}\b",
                codec_impl_source,
            ) is None:
                violations.append(
                    f"focused litchi-iwa {family} chart-caption neutral codec is "
                    f"missing strict API {api}: "
                    f"{IWA_CHART_CAPTION_CODEC_IMPLEMENTATION_SOURCE}"
                )

    helper_path = root / IWA_CHART_CAPTION_CODEC_HELPER_SOURCE
    helper_source = ""
    if not helper_path.is_file():
        violations.append(
            f"focused litchi-iwa {family} chart-caption source is missing the "
            f"shared caption_edge helper: {IWA_CHART_CAPTION_CODEC_HELPER_SOURCE}"
        )
    else:
        helper_source = _mask_rust_non_code(
            _mask_rust_cfg_test_items(helper_path.read_text(encoding="utf-8"))
        )
        neutral_helper = re.search(
            r"\blitchi_iwa_protos\b[ \t\r\n]*::[ \t\r\n]*"
            r"chart_caption_codec\b",
            helper_source,
        )
        if neutral_helper is None:
            line_number = 1
            violations.append(
                f"focused litchi-iwa {family} chart-caption helper must route through "
                f"neutral chart_caption_codec: {IWA_CHART_CAPTION_CODEC_HELPER_SOURCE}:"
                f"{line_number}"
            )
        else:
            helper_functions = _rust_top_level_function_bodies(helper_source)
            for helper_name, codec_api in IWA_CHART_CAPTION_EDGE_API_TARGETS.items():
                helper_body = helper_functions.get(helper_name)
                if helper_body is None:
                    violations.append(
                        f"focused litchi-iwa {family} chart-caption helper is missing "
                        f"{helper_name}: {IWA_CHART_CAPTION_CODEC_HELPER_SOURCE}"
                    )
                    continue
                body, body_offset = helper_body
                if re.search(
                    rf"(?<![A-Za-z0-9_#]){IWA_CHART_CAPTION_CODEC_MODULE}"
                    rf"[ \t\r\n]*::[ \t\r\n]*{re.escape(codec_api)}"
                    rf"[ \t\r\n]*\(",
                    body,
                ) is None:
                    line_number = helper_source.count("\n", 0, body_offset) + 1
                    violations.append(
                        f"focused litchi-iwa {family} chart-caption helper {helper_name} "
                        f"must call strict {IWA_CHART_CAPTION_CODEC_MODULE}::{codec_api}: "
                        f"{IWA_CHART_CAPTION_CODEC_HELPER_SOURCE}:{line_number}"
                    )

    edge_import = re.search(
        r"(?m)^[ \t]*(?:pub(?:\([^()]*\))?[ \t\r\n]+)?use[ \t\r\n]+"
        r"(?:crate|self|super)[ \t\r\n]*::[ \t\r\n]*charts"
        r"[ \t\r\n]*::[ \t\r\n]*caption_edge\b",
        source,
    )
    if edge_import is None:
        violations.append(
            f"focused litchi-iwa {family} chart-caption source must use the shared "
            f"caption_edge route: {relative}"
        )
    else:
        for name in sorted(IWA_CHART_CAPTION_EDGE_API_NAMES):
            if re.search(
                rf"(?<![A-Za-z0-9_:#.])(?:r#)?{re.escape(name)}"
                r"[ \t\r\n]*\(",
                source,
            ) is None:
                line_number = source.count("\n", 0, edge_import.start()) + 1
                violations.append(
                    f"focused litchi-iwa {family} chart-caption source must call "
                    f"shared {name}: {relative}:{line_number}"
                )

    # These are deliberately checked only in the caption source and shared
    # edge helper.  Generated decodes in pages/.../charts/graph.rs and
    # numbers/.../sheet_charts/graph.rs are broader chart ownership and are
    # outside this focused edge ratchet.  The named graph/theme functions in
    # the caption modules are the other explicit exception: they remain the
    # compatibility owner for chart discovery and theme decoding.  Everything
    # else is the selected-edge boundary and must stay generated-free.
    forbidden_source = _rust_mask_named_function_bodies(
        source, IWA_CHART_CAPTION_ALLOWED_GRAPH_THEME_FUNCTIONS
    )
    generated_type = re.search(
        r"(?<![A-Za-z0-9_#])(?:r#)?IWorkChartArchive\b", forbidden_source
    )
    if generated_type is not None:
        line_number = source.count("\n", 0, generated_type.start()) + 1
        violations.append(
            f"focused litchi-iwa {family} chart-caption source retains generated "
            f"IWorkChartArchive type: {relative}:{line_number}"
        )
    for label, pattern in IWA_CHART_CAPTION_GENERATED_DECODE_PATTERNS:
        for match in pattern.finditer(forbidden_source):
            line_number = source.count("\n", 0, match.start()) + 1
            violations.append(
                f"focused litchi-iwa {family} chart-caption source retains generated "
                f"{label}: {relative}:{line_number}"
            )
    for marker in sorted(IWA_CHART_CAPTION_MANUAL_WIRE_MARKERS):
        marker_match = re.search(
            rf"(?<![A-Za-z0-9_]){re.escape(marker)}(?![A-Za-z0-9_])",
            forbidden_source,
        )
        if marker_match is None:
            continue
        line_number = source.count("\n", 0, marker_match.start()) + 1
        violations.append(
            f"focused litchi-iwa {family} chart-caption source retains manual "
            f"wire marker {marker}: {relative}:{line_number}"
        )
    for marker in sorted(IWA_CHART_CAPTION_LEGACY_CODEC_MARKERS):
        marker_match = re.search(
            rf"(?<![A-Za-z0-9_]){re.escape(marker)}(?![A-Za-z0-9_])",
            forbidden_source,
        )
        if marker_match is None:
            continue
        line_number = source.count("\n", 0, marker_match.start()) + 1
        violations.append(
            f"focused litchi-iwa {family} chart-caption source retains legacy "
            f"{marker}: {relative}:{line_number}"
        )
    for marker in sorted(legacy_rewrite_markers):
        marker_match = re.search(
            rf"(?<![A-Za-z0-9_]){re.escape(marker)}(?![A-Za-z0-9_])",
            forbidden_source,
        )
        if marker_match is None:
            continue
        line_number = source.count("\n", 0, marker_match.start()) + 1
        violations.append(
            f"focused litchi-iwa {family} chart-caption source retains caption-local "
            f"rewrite helper {marker}: {relative}:{line_number}"
        )

    for name in read_functions:
        if re.search(
            rf"(?<![A-Za-z0-9_#])(?:r#)?{re.escape(name)}\b", source
        ) is None:
            violations.append(
                f"focused litchi-iwa {family} chart-caption source is missing "
                f"caption reader {name}: {relative}"
            )

    # A helper is part of this edge's reachability boundary.  Keep the same
    # source-authority restrictions there, but do not walk the entire host
    # graph: graph.rs intentionally remains a compatibility owner.
    if helper_source:
        helper_type = re.search(
            r"(?<![A-Za-z0-9_#])(?:r#)?IWorkChartArchive\b", helper_source
        )
        if helper_type is not None:
            line_number = helper_source.count("\n", 0, helper_type.start()) + 1
            violations.append(
                f"focused litchi-iwa {family} chart-caption helper retains generated "
                f"IWorkChartArchive type: {IWA_CHART_CAPTION_CODEC_HELPER_SOURCE}:"
                f"{line_number}"
            )
        for label, pattern in IWA_CHART_CAPTION_GENERATED_DECODE_PATTERNS:
            for match in pattern.finditer(helper_source):
                line_number = helper_source.count("\n", 0, match.start()) + 1
                violations.append(
                    f"focused litchi-iwa {family} chart-caption helper retains generated "
                    f"{label}: {IWA_CHART_CAPTION_CODEC_HELPER_SOURCE}:{line_number}"
                )
        for marker in sorted(IWA_CHART_CAPTION_LEGACY_CODEC_MARKERS):
            marker_match = re.search(
                rf"(?<![A-Za-z0-9_]){re.escape(marker)}(?![A-Za-z0-9_])",
                helper_source,
            )
            if marker_match is None:
                continue
            line_number = helper_source.count("\n", 0, marker_match.start()) + 1
            violations.append(
                f"focused litchi-iwa {family} chart-caption helper retains legacy "
                f"{marker}: {IWA_CHART_CAPTION_CODEC_HELPER_SOURCE}:{line_number}"
            )

    return sorted(set(violations))


def audit_iwa_pages_chart_caption_source_topology(root: Path = ROOT) -> list[str]:
    """Require Pages chart-caption edge access through the neutral codec seam."""

    return _audit_iwa_chart_caption_source_topology(
        root,
        IWA_PAGES_CHART_CAPTION_SOURCE,
        "Pages",
        IWA_PAGES_CHART_CAPTION_READ_FUNCTIONS,
        IWA_PAGES_CHART_CAPTION_LEGACY_REWRITE_MARKERS,
    )


def audit_iwa_numbers_chart_caption_source_topology(root: Path = ROOT) -> list[str]:
    """Require Numbers chart-caption edge access through the neutral codec seam."""

    return _audit_iwa_chart_caption_source_topology(
        root,
        IWA_NUMBERS_CHART_CAPTION_SOURCE,
        "Numbers",
        IWA_NUMBERS_CHART_CAPTION_READ_FUNCTIONS,
        IWA_NUMBERS_CHART_CAPTION_LEGACY_REWRITE_MARKERS,
    )


def audit_iwa_pages_drawable_order_source_topology(root: Path = ROOT) -> list[str]:
    """Require the Pages drawable-order owner to use the strict neutral codec.

    This intentionally examines only ``editor/drawable_order.rs``.  Pages
    shape/chart/media graph builders elsewhere still have compatibility reads
    of ``TP.DrawablesZOrderArchive`` and are outside this focused migration
    boundary.  Test fixtures are masked item-by-item so a cfg(test) decoder
    cannot conceal a later production import or helper.
    """

    path = root / IWA_PAGES_DRAWABLE_ORDER_SOURCE
    if not path.is_file():
        # The focused body-order module is retired.  The generic Pages
        # editor still owns reachability and creation, which use the shared
        # codec directly from ``editor.rs`` and do not require this module.
        return []

    production_source = _mask_rust_cfg_test_items(
        path.read_text(encoding="utf-8")
    )
    source = _mask_rust_non_code(production_source)
    violations: list[str] = []

    if IWA_PAGES_DRAWABLE_ORDER_CODEC_ROUTE.search(source) is None:
        violations.append(
            "focused litchi-iwa Pages drawable-order source must route through "
            f"neutral {IWA_PAGES_DRAWABLE_ORDER_CODEC_MODULE}: "
            f"{IWA_PAGES_DRAWABLE_ORDER_SOURCE}"
        )
    if IWA_PAGES_DRAWABLE_ORDER_CODEC_DECODE.search(source) is None:
        violations.append(
            "focused litchi-iwa Pages drawable-order source is missing strict "
            f"{IWA_PAGES_DRAWABLE_ORDER_CODEC_MODULE} decode route: "
            f"{IWA_PAGES_DRAWABLE_ORDER_SOURCE}"
        )
    if IWA_PAGES_DRAWABLE_ORDER_CODEC_REWRITE.search(source) is None:
        violations.append(
            "focused litchi-iwa Pages drawable-order source is missing strict "
            f"{IWA_PAGES_DRAWABLE_ORDER_CODEC_MODULE} rewrite route: "
            f"{IWA_PAGES_DRAWABLE_ORDER_SOURCE}"
        )

    for marker in sorted(IWA_PAGES_DRAWABLE_ORDER_GENERATED_MARKERS):
        marker_pattern = re.compile(
            rf"(?<![A-Za-z0-9_#]){re.escape(marker)}(?![A-Za-z0-9_])"
        )
        match = marker_pattern.search(source)
        if match is None:
            continue
        line_number = source.count("\n", 0, match.start()) + 1
        violations.append(
            "focused litchi-iwa Pages drawable-order source retains generated "
            f"marker {marker}: {IWA_PAGES_DRAWABLE_ORDER_SOURCE}:{line_number}"
        )

    generated_decode = IWA_PAGES_DRAWABLE_ORDER_GENERATED_DECODE.search(source)
    if generated_decode is not None:
        line_number = source.count("\n", 0, generated_decode.start()) + 1
        violations.append(
            "focused litchi-iwa Pages drawable-order source retains generated "
            "archive/Prost decode: "
            f"{IWA_PAGES_DRAWABLE_ORDER_SOURCE}:{line_number}"
        )

    for marker in sorted(IWA_PAGES_DRAWABLE_ORDER_RAW_HELPER_MARKERS):
        match = re.search(
            rf"(?<![A-Za-z0-9_#]){re.escape(marker)}(?![A-Za-z0-9_])",
            source,
        )
        if match is None:
            continue
        line_number = source.count("\n", 0, match.start()) + 1
        violations.append(
            "focused litchi-iwa Pages drawable-order source retains legacy raw "
            f"helper marker {marker}: {IWA_PAGES_DRAWABLE_ORDER_SOURCE}:{line_number}"
        )

    return sorted(set(violations))


def audit_iwa_pages_drawable_order_retirement_source_topology(
    root: Path = ROOT,
) -> list[str]:
    """Keep the retired Pages body drawable-order host surface deleted.

    ``litchi-pages`` owns selector-first body ordering now.  The compatibility
    host may continue to use the neutral codec for generic reachability and
    drawable creation, so this ratchet only targets the removed module,
    ``PagesEditor`` method names, and their executable calls.
    """

    source_root = root / IWA_PAGES_SOURCE_ROOT
    if not source_root.is_dir():
        return []

    violations: set[str] = set()
    retired_module = root / RETIRED_IWA_PAGES_DRAWABLE_ORDER_MODULE
    if retired_module.exists():
        violations.add(
            "retired litchi-iwa Pages drawable-order module returned: "
            f"{RETIRED_IWA_PAGES_DRAWABLE_ORDER_MODULE}"
        )

    method_pattern = re.compile(
        r"(?<![A-Za-z0-9_#])(?:r#)?(?:"
        + "|".join(
            re.escape(name)
            for name in sorted(
                RETIRED_IWA_PAGES_DRAWABLE_ORDER_METHOD_SET,
                key=len,
                reverse=True,
            )
        )
        + r")(?![A-Za-z0-9_])"
    )
    for path in sorted(source_root.rglob("*.rs")):
        # Child test modules are included by a surrounding cfg(test) module
        # and therefore do not carry an attribute for the item masker to see.
        # Keep this production-only ratchet from treating their compatibility
        # fixtures as live host methods.
        if path.name == "tests.rs" or "tests" in path.parts:
            continue
        raw_source = path.read_text(encoding="utf-8")
        production_source = _mask_rust_cfg_test_items(raw_source)
        code = _mask_rust_non_code(production_source)
        module_match = IWA_PAGES_DRAWABLE_ORDER_MODULE_DECLARATION.search(code)
        if module_match is not None:
            line_number = code.count("\n", 0, module_match.start()) + 1
            violations.add(
                "retired litchi-iwa Pages drawable-order module declaration: "
                f"{path.relative_to(root)}:{line_number}"
            )

        declaration_spans = {
            (match.start(1), match.end(1))
            for match in RUST_FUNCTION_DECLARATION.finditer(code)
            if match.group(1) in RETIRED_IWA_PAGES_DRAWABLE_ORDER_METHOD_SET
        }
        for match in method_pattern.finditer(code):
            name = match.group(0).removeprefix("r#")
            line_number = code.count("\n", 0, match.start()) + 1
            if any(
                start <= match.start() < end for start, end in declaration_spans
            ):
                violations.add(
                    "retired litchi-iwa Pages drawable-order method returned "
                    f"{name}: {path.relative_to(root)}:{line_number}"
                )
            else:
                violations.add(
                    "retired litchi-iwa Pages drawable-order production call "
                    f"{name}: {path.relative_to(root)}:{line_number}"
                )

    return sorted(violations)


def audit_iwa_pages_document_source_topology(
    root: Path = ROOT,
) -> list[str]:
    """Keep the retired Pages reader and host compatibility surfaces deleted."""

    violations: list[str] = []
    retired_source = root / RETIRED_IWA_PAGES_DOCUMENT_SOURCE
    if retired_source.exists():
        violations.append(
            "retired litchi-iwa Pages document reader source returned: "
            + str(RETIRED_IWA_PAGES_DOCUMENT_SOURCE)
        )

    module_path = root / IWA_PAGES_MODULE_SOURCE
    if module_path.is_file():
        module_source = _mask_rust_non_code(
            module_path.read_text(encoding="utf-8")
        )
        for match in IWA_PAGES_DOCUMENT_MODULE.finditer(module_source):
            line_number = module_source.count("\n", 0, match.start()) + 1
            violations.append(
                "retired litchi-iwa Pages document reader module "
                f"{match.group(1)}: {IWA_PAGES_MODULE_SOURCE}:{line_number}"
            )
        for match in IWA_PAGES_DOCUMENT_LOCAL_REEXPORT.finditer(module_source):
            line_number = module_source.count("\n", 0, match.start()) + 1
            violations.append(
                "retired litchi-iwa Pages document reader local re-export "
                f"{match.group('module')}: {IWA_PAGES_MODULE_SOURCE}:{line_number}"
            )

    workspace_sources = root / WORKSPACE_CRATES_ROOT
    if workspace_sources.is_dir():
        for path in sorted(workspace_sources.glob("*/src/**/*.rs")):
            raw_source = path.read_text(encoding="utf-8")
            for declaration, line_number in _rust_public_declarations(raw_source):
                for match in RUST_IDENTIFIER.finditer(declaration):
                    name = match.group(1)
                    if name not in RETIRED_IWA_PAGES_DOCUMENT_TYPE_SET:
                        continue
                    identifier_line = line_number + declaration.count(
                        "\n", 0, match.start(1)
                    )
                    violations.append(
                        "retired Pages document reader workspace public name "
                        f"{name}: {path.relative_to(root)}:{identifier_line}"
                    )
            for name, line_number in _rust_doc_identifier_occurrences(
                raw_source, RETIRED_IWA_PAGES_DOCUMENT_TYPE_SET
            ):
                violations.append(
                    "retired Pages document reader workspace public rustdoc "
                    f"{name}: {path.relative_to(root)}:{line_number}"
                )

    host_source_root = root / IWA_HOST_SOURCE_ROOT
    if host_source_root.is_dir():
        for path in sorted(host_source_root.rglob("*.rs")):
            raw_source = path.read_text(encoding="utf-8")
            source = _mask_rust_non_code(raw_source)
            focused_aliases: set[str] = set()
            focused_modules = {"litchi_pages"}
            focused_imports = re.finditer(
                r"^[ \t]*(?:pub(?:\([^()]*\))?[ \t\r\n]+)?"
                r"use[ \t\r\n]+(?P<body>[^;]*\blitchi_pages\b[^;]*);",
                source,
                re.MULTILINE,
            )
            for imported in focused_imports:
                body = imported.group("body")
                module_alias = re.search(
                    r"\blitchi_pages\b[ \t\r\n]+as[ \t\r\n]+"
                    r"(?:r#)?([A-Za-z_][A-Za-z0-9_]*)",
                    body,
                )
                if module_alias is not None:
                    focused_modules.add(module_alias.group(1))
                    if re.match(r"^[ \t]*pub\b", imported.group(0)):
                        line_number = source.count("\n", 0, imported.start()) + 1
                        violations.append(
                            "retired litchi-iwa Pages document reader focused host "
                            f"facade {module_alias.group(1)}: "
                            f"{path.relative_to(root)}:{line_number}"
                        )
                self_alias = re.search(
                    r"(?<![A-Za-z0-9_#])(?:r#)?self[ \t\r\n]+as"
                    r"[ \t\r\n]+(?:r#)?([A-Za-z_][A-Za-z0-9_]*)",
                    body,
                )
                if self_alias is not None:
                    focused_modules.add(self_alias.group(1))
                    if re.match(r"^[ \t]*pub\b", imported.group(0)):
                        line_number = source.count("\n", 0, imported.start()) + 1
                        violations.append(
                            "retired litchi-iwa Pages document reader focused host "
                            f"facade {self_alias.group(1)}: "
                            f"{path.relative_to(root)}:{line_number}"
                        )
                if "*" in body:
                    focused_aliases.update(IWA_PAGES_FOCUSED_READER_TYPES)
                    if re.match(r"^[ \t]*pub\b", imported.group(0)):
                        line_number = source.count("\n", 0, imported.start()) + 1
                        violations.append(
                            "retired litchi-iwa Pages document reader focused host "
                            f"facade glob: {path.relative_to(root)}:{line_number}"
                        )
                for name in IWA_PAGES_FOCUSED_READER_TYPES:
                    named = re.search(
                        rf"(?<![A-Za-z0-9_#])(?:r#)?{name}\b"
                        rf"(?:[ \t\r\n]+as[ \t\r\n]+(?:r#)?"
                        rf"(?P<alias>[A-Za-z_][A-Za-z0-9_]*))?",
                        body,
                    )
                    if named is not None:
                        focused_aliases.add(named.group("alias") or name)

            type_aliases = tuple(
                re.finditer(
                    r"^[ \t]*(?:pub(?:\([^()]*\))?[ \t\r\n]+)?type"
                    r"[ \t\r\n]+(?:r#)?(?P<alias>[A-Za-z_][A-Za-z0-9_]*)"
                    r"[^=;]*=[ \t\r\n]*(?P<target>[^;]+);",
                    source,
                    re.MULTILINE,
                )
            )
            changed = True
            while changed:
                changed = False
                for alias in type_aliases:
                    identifiers = {
                        match.group(1)
                        for match in RUST_IDENTIFIER.finditer(alias.group("target"))
                    }
                    focused_target = bool(identifiers & focused_aliases) or (
                        bool(identifiers & focused_modules)
                        and bool(identifiers & IWA_PAGES_FOCUSED_READER_TYPES)
                    )
                    if focused_target and alias.group("alias") not in focused_aliases:
                        focused_aliases.add(alias.group("alias"))
                        changed = True

            for declaration, line_number in _rust_public_declarations(raw_source):
                identifiers = {
                    match.group(1) for match in RUST_IDENTIFIER.finditer(declaration)
                }
                exposed = sorted(identifiers & focused_aliases)
                if identifiers & focused_modules:
                    exposed.extend(
                        sorted(
                            IWA_PAGES_FOCUSED_READER_TYPES & identifiers
                            - set(exposed)
                        )
                    )
                for name in exposed:
                    identifier = next(
                        match
                        for match in RUST_IDENTIFIER.finditer(declaration)
                        if match.group(1) == name
                    )
                    identifier_line = line_number + declaration.count(
                        "\n", 0, identifier.start(1)
                    )
                    violations.append(
                        "retired litchi-iwa Pages document reader focused host "
                        f"facade {name}: {path.relative_to(root)}:{identifier_line}"
                    )

    caller_paths: set[Path] = set()
    for caller_root in (
        Path("crates/litchi-iwa/src"),
        Path("crates/litchi-iwa/tests"),
        Path("crates/litchi-iwa/examples"),
    ):
        caller_path = root / caller_root
        if caller_path.is_dir():
            caller_paths.update(caller_path.rglob("*.rs"))
    for path in sorted(caller_paths):
        raw_source = path.read_text(encoding="utf-8")
        source = _mask_rust_non_code(raw_source)
        for match in RUST_IDENTIFIER.finditer(source):
            name = match.group(1)
            if name not in RETIRED_IWA_PAGES_DOCUMENT_TYPE_SET:
                continue
            line_number = source.count("\n", 0, match.start(1)) + 1
            violations.append(
                "retired litchi-iwa Pages document reader type usage "
                f"{name}: {path.relative_to(root)}:{line_number}"
            )
        for name, line_number in _rust_doc_identifier_occurrences(
            raw_source, RETIRED_IWA_PAGES_DOCUMENT_TYPE_SET
        ):
            violations.append(
                "retired litchi-iwa Pages document reader rustdoc reference "
                f"{name}: {path.relative_to(root)}:{line_number}"
            )

    readme_path = root / IWA_PAGES_README
    if readme_path.is_file():
        source = readme_path.read_text(encoding="utf-8")
        for match in RUST_IDENTIFIER.finditer(source):
            name = match.group(1)
            if name not in RETIRED_IWA_PAGES_DOCUMENT_TYPE_SET:
                continue
            line_number = source.count("\n", 0, match.start(1)) + 1
            violations.append(
                "retired litchi-iwa Pages document reader README reference "
                f"{name}: {IWA_PAGES_README}:{line_number}"
            )

    return sorted(set(violations))


def audit_iwa_numbers_document_source_topology(
    root: Path = ROOT,
) -> list[str]:
    """Keep the retired Numbers reader and host compatibility surfaces deleted."""

    violations: list[str] = []
    retired_source = root / RETIRED_IWA_NUMBERS_DOCUMENT_SOURCE
    if retired_source.exists():
        violations.append(
            "retired litchi-iwa Numbers document reader source returned: "
            + str(RETIRED_IWA_NUMBERS_DOCUMENT_SOURCE)
        )
    retired_sheet_source = root / RETIRED_IWA_NUMBERS_SHEET_SOURCE
    if retired_sheet_source.exists():
        violations.append(
            "retired litchi-iwa Numbers sheet reader source returned: "
            + str(RETIRED_IWA_NUMBERS_SHEET_SOURCE)
        )

    module_path = root / IWA_NUMBERS_MODULE_SOURCE
    if module_path.is_file():
        module_source = _mask_rust_non_code(
            module_path.read_text(encoding="utf-8")
        )
        for match in IWA_NUMBERS_READER_MODULE.finditer(module_source):
            line_number = module_source.count("\n", 0, match.start()) + 1
            violations.append(
                "retired litchi-iwa Numbers reader module "
                f"{match.group('module')}: {IWA_NUMBERS_MODULE_SOURCE}:{line_number}"
            )
        for match in IWA_NUMBERS_READER_LOCAL_REEXPORT.finditer(module_source):
            line_number = module_source.count("\n", 0, match.start()) + 1
            violations.append(
                "retired litchi-iwa Numbers reader local re-export "
                f"{match.group('module')}: {IWA_NUMBERS_MODULE_SOURCE}:{line_number}"
            )

    workspace_sources = root / WORKSPACE_CRATES_ROOT
    if workspace_sources.is_dir():
        for path in sorted(workspace_sources.rglob("*.rs")):
            raw_source = path.read_text(encoding="utf-8")
            if not any(
                name in raw_source for name in RETIRED_IWA_NUMBERS_READER_TYPE_SET
            ):
                continue
            source = _mask_rust_non_code(raw_source)
            for match in RUST_IDENTIFIER.finditer(source):
                name = match.group(1)
                if name not in RETIRED_IWA_NUMBERS_READER_TYPE_SET:
                    continue
                line_number = source.count("\n", 0, match.start(1)) + 1
                violations.append(
                    "retired Numbers document reader workspace type usage "
                    f"{name}: {path.relative_to(root)}:{line_number}"
                )
            for declaration, line_number in _rust_public_declarations(raw_source):
                for match in RUST_IDENTIFIER.finditer(declaration):
                    name = match.group(1)
                    if name not in RETIRED_IWA_NUMBERS_READER_TYPE_SET:
                        continue
                    identifier_line = line_number + declaration.count(
                        "\n", 0, match.start(1)
                    )
                    violations.append(
                        "retired Numbers document reader workspace public name "
                        f"{name}: {path.relative_to(root)}:{identifier_line}"
                    )
            for name, line_number in _rust_doc_identifier_occurrences(
                raw_source, RETIRED_IWA_NUMBERS_READER_TYPE_SET
            ):
                violations.append(
                    "retired Numbers document reader workspace public rustdoc "
                    f"{name}: {path.relative_to(root)}:{line_number}"
                )

    host_source_root = root / IWA_HOST_SOURCE_ROOT
    if host_source_root.is_dir():
        for path in sorted(host_source_root.rglob("*.rs")):
            raw_source = path.read_text(encoding="utf-8")
            source = _mask_rust_non_code(raw_source)
            focused_aliases: set[str] = set()
            focused_modules = {"litchi_numbers"}
            focused_imports = re.finditer(
                r"^[ \t]*(?:pub(?:\([^()]*\))?[ \t\r\n]+)?"
                r"use[ \t\r\n]+(?P<body>[^;]*\blitchi_numbers\b[^;]*);",
                source,
                re.MULTILINE,
            )
            for imported in focused_imports:
                body = imported.group("body")
                module_alias = re.search(
                    r"\blitchi_numbers\b[ \t\r\n]+as[ \t\r\n]+"
                    r"(?:r#)?([A-Za-z_][A-Za-z0-9_]*)",
                    body,
                )
                if module_alias is not None:
                    focused_modules.add(module_alias.group(1))
                    if re.match(r"^[ \t]*pub\b", imported.group(0)):
                        line_number = source.count("\n", 0, imported.start()) + 1
                        violations.append(
                            "retired litchi-iwa Numbers document reader focused host "
                            f"facade {module_alias.group(1)}: "
                            f"{path.relative_to(root)}:{line_number}"
                        )
                self_alias = re.search(
                    r"(?<![A-Za-z0-9_#])(?:r#)?self[ \t\r\n]+as"
                    r"[ \t\r\n]+(?:r#)?([A-Za-z_][A-Za-z0-9_]*)",
                    body,
                )
                if self_alias is not None:
                    focused_modules.add(self_alias.group(1))
                    if re.match(r"^[ \t]*pub\b", imported.group(0)):
                        line_number = source.count("\n", 0, imported.start()) + 1
                        violations.append(
                            "retired litchi-iwa Numbers document reader focused host "
                            f"facade {self_alias.group(1)}: "
                            f"{path.relative_to(root)}:{line_number}"
                        )
                focused_module = re.search(
                    r"\blitchi_numbers\b[ \t\r\n]*::[ \t\r\n]*"
                    r"(?:\{[ \t\r\n]*)?(?:r#)?(?P<module>document|package)\b"
                    r"(?:[ \t\r\n]+as[ \t\r\n]+(?:r#)?"
                    r"(?P<alias>[A-Za-z_][A-Za-z0-9_]*))?",
                    body,
                )
                if focused_module is not None:
                    alias = focused_module.group("alias") or focused_module.group(
                        "module"
                    )
                    focused_modules.add(alias)
                    if re.match(r"^[ \t]*pub\b", imported.group(0)):
                        line_number = source.count("\n", 0, imported.start()) + 1
                        violations.append(
                            "retired litchi-iwa Numbers document reader focused host "
                            f"facade {alias}: {path.relative_to(root)}:{line_number}"
                        )
                if "*" in body:
                    focused_aliases.update(IWA_NUMBERS_FOCUSED_READER_TYPES)
                    if re.match(r"^[ \t]*pub\b", imported.group(0)):
                        line_number = source.count("\n", 0, imported.start()) + 1
                        violations.append(
                            "retired litchi-iwa Numbers document reader focused host "
                            f"facade glob: {path.relative_to(root)}:{line_number}"
                        )
                for name in IWA_NUMBERS_FOCUSED_READER_TYPES:
                    named = re.search(
                        rf"(?<![A-Za-z0-9_#])(?:r#)?{name}\b"
                        rf"(?:[ \t\r\n]+as[ \t\r\n]+(?:r#)?"
                        rf"(?P<alias>[A-Za-z_][A-Za-z0-9_]*))?",
                        body,
                    )
                    if named is not None:
                        focused_aliases.add(named.group("alias") or name)

            type_aliases = tuple(
                re.finditer(
                    r"^[ \t]*(?:pub(?:\([^()]*\))?[ \t\r\n]+)?type"
                    r"[ \t\r\n]+(?:r#)?(?P<alias>[A-Za-z_][A-Za-z0-9_]*)"
                    r"[^=;]*=[ \t\r\n]*(?P<target>[^;]+);",
                    source,
                    re.MULTILINE,
                )
            )
            changed = True
            while changed:
                changed = False
                for alias in type_aliases:
                    identifiers = {
                        match.group(1)
                        for match in RUST_IDENTIFIER.finditer(alias.group("target"))
                    }
                    focused_target = bool(identifiers & focused_aliases) or (
                        bool(identifiers & focused_modules)
                        and bool(identifiers & IWA_NUMBERS_FOCUSED_READER_TYPES)
                    )
                    if focused_target and alias.group("alias") not in focused_aliases:
                        focused_aliases.add(alias.group("alias"))
                        changed = True

            for declaration, line_number in _rust_public_declarations(raw_source):
                identifiers = {
                    match.group(1) for match in RUST_IDENTIFIER.finditer(declaration)
                }
                exposed = sorted(identifiers & focused_aliases)
                if identifiers & focused_modules:
                    exposed.extend(
                        sorted(
                            IWA_NUMBERS_FOCUSED_READER_TYPES
                            & identifiers
                            - set(exposed)
                        )
                    )
                for name in exposed:
                    identifier = next(
                        match
                        for match in RUST_IDENTIFIER.finditer(declaration)
                        if match.group(1) == name
                    )
                    identifier_line = line_number + declaration.count(
                        "\n", 0, identifier.start(1)
                    )
                    violations.append(
                        "retired litchi-iwa Numbers document reader focused host "
                        f"facade {name}: {path.relative_to(root)}:{identifier_line}"
                    )

    readme_path = root / IWA_NUMBERS_README
    if readme_path.is_file():
        source = readme_path.read_text(encoding="utf-8")
        for match in RUST_IDENTIFIER.finditer(source):
            name = match.group(1)
            if name not in RETIRED_IWA_NUMBERS_READER_TYPE_SET:
                continue
            line_number = source.count("\n", 0, match.start(1)) + 1
            violations.append(
                "retired litchi-iwa Numbers document reader README reference "
                f"{name}: {IWA_NUMBERS_README}:{line_number}"
            )

    return sorted(set(violations))


def audit_numbers_document_public_api(root: Path = ROOT) -> list[str]:
    """Keep the focused Numbers reader public API archive-free and semantic."""

    violations: list[str] = []
    for relative in NUMBERS_DOCUMENT_PUBLIC_API_SOURCES:
        path = root / relative
        if not path.is_file():
            continue
        source = path.read_text(encoding="utf-8")
        dedicated_source = relative == NUMBERS_SOURCE_ROOT / "document.rs"
        for declaration, line_number in _rust_public_declarations(source):
            identifiers = {
                match.group(1) for match in RUST_IDENTIFIER.finditer(declaration)
            }
            if not dedicated_source and not (
                identifiers & NUMBERS_DOCUMENT_PUBLIC_MARKERS
            ):
                continue
            for match in RUST_IDENTIFIER.finditer(declaration):
                identifier = match.group(1)
                reason = _iwork_public_leak(identifier)
                if reason is None:
                    continue
                identifier_line = line_number + declaration.count(
                    "\n", 0, match.start(1)
                )
                violations.append(
                    "focused litchi-numbers document reader public API exposes "
                    f"{reason} {identifier}: "
                    f"{path.relative_to(root)}:{identifier_line}"
                )

        if not dedicated_source:
            continue
        doc_regions = [
            *re.finditer(r"^[ \t]*//[/!][^\r\n]*", source, re.MULTILINE),
            *re.finditer(r"/\*(?:\*|!)[\s\S]*?\*/", source),
            *re.finditer(r"#\s*\[\s*doc\s*=\s*[^\]]*\]", source),
        ]
        for region in doc_regions:
            for match in RUST_IDENTIFIER.finditer(region.group(0)):
                identifier = match.group(1)
                if not identifier[:1].isupper():
                    continue
                if identifier == "Archive":
                    continue
                reason = _iwork_public_leak(identifier)
                if reason is None:
                    words = [
                        word.lower() for word in CAMEL_CASE_WORD.findall(identifier)
                    ]
                    if "native" in words and any(
                        word in {"id", "identifier", "object"} for word in words
                    ):
                        reason = "native object"
                if reason is None:
                    continue
                offset = region.start() + match.start(1)
                line_number = source.count("\n", 0, offset) + 1
                violations.append(
                    "focused litchi-numbers document reader rustdoc exposes "
                    f"{reason} {identifier}: "
                    f"{path.relative_to(root)}:{line_number}"
                )

    return sorted(set(violations))


