def audit_iwa_keynote_chart_title_source_topology(root: Path = ROOT) -> list[str]:
    """Keep the retired chart-title compatibility shell out of litchi-iwa."""

    path = root / IWA_KEYNOTE_CHART_TITLE_SOURCE
    violations: list[str] = []
    if path.is_file():
        violations.append(
            "retired litchi-iwa Keynote chart-title source was restored: "
            f"{IWA_KEYNOTE_CHART_TITLE_SOURCE}"
        )

    module_path = root / RETIRED_IWA_KEYNOTE_CHART_TITLE_MODULE_SOURCE
    if module_path.is_file():
        module_source = _mask_rust_non_code(
            _mask_rust_cfg_test_items(module_path.read_text(encoding="utf-8"))
        )
        for match in RETIRED_IWA_KEYNOTE_CHART_TITLE_MODULE.finditer(module_source):
            line_number = module_source.count("\n", 0, match.start()) + 1
            violations.append(
                "retired litchi-iwa Keynote chart-title module declaration: "
                f"{RETIRED_IWA_KEYNOTE_CHART_TITLE_MODULE_SOURCE}:{line_number}"
            )

    source_root = root / IWA_KEYNOTE_SOURCE_ROOT
    source_paths = sorted(source_root.rglob("*.rs")) if source_root.is_dir() else []
    for source_path in source_paths:
        if source_path.name == "tests.rs" or "tests" in source_path.parts:
            continue
        production_source = _mask_rust_cfg_test_items(
            source_path.read_text(encoding="utf-8")
        )
        source = _mask_rust_non_code(production_source)
        relative = source_path.relative_to(root)
        for name, line_number in _rust_function_declarations(production_source):
            if name in RETIRED_IWA_KEYNOTE_CHART_TITLE_METHODS:
                violations.append(
                    "retired litchi-iwa Keynote chart-title host wrapper/helper "
                    f"{name}: {relative}:{line_number}"
                )

        for match in IWA_KEYNOTE_CHART_TITLE_RAW_ID_CALL.finditer(source):
            line_start = source.rfind("\n", 0, match.start()) + 1
            line_end = source.find("\n", match.end())
            if line_end < 0:
                line_end = len(source)
            if re.search(
                rf"\bfn[ \t\r\n]+{re.escape(match.group('method'))}\b",
                source[line_start:line_end],
            ):
                continue
            line_number = source.count("\n", 0, match.start("method")) + 1
            violations.append(
                "retired litchi-iwa Keynote chart-title raw-ID call "
                f"{match.group('method')}: {relative}:{line_number}"
            )

        if source_path != path:
            continue
        for match in IWA_KEYNOTE_CHART_TITLE_RAW_ID_PARAMETER.finditer(source):
            line_number = source.count("\n", 0, match.start()) + 1
            violations.append(
                "retired litchi-iwa Keynote chart-title raw identifier parameter "
                f"{match.group(0).strip()}: {relative}:{line_number}"
            )
        for match in IWA_KEYNOTE_CHART_TITLE_IDENTIFIER_POSITION_FALLBACK.finditer(
            source
        ):
            line_number = source.count("\n", 0, match.start()) + 1
            violations.append(
                "retired litchi-iwa Keynote chart-title identifier-to-position "
                f"fallback {match.group(0).strip()}: {relative}:{line_number}"
            )

    return sorted(set(violations))


def _keynote_chart_legend_boundary_active(root: Path) -> bool:
    """Return whether the focused owner crossed its package-module seam."""

    owner_path = root / KEYNOTE_CHART_LEGEND_OWNER_SOURCE
    package_path = root / KEYNOTE_CHART_LEGEND_EXPORT_SOURCES[0]
    if not owner_path.is_file() or not package_path.is_file():
        return False
    package_source = _mask_rust_non_code(
        _mask_rust_cfg_test_items(package_path.read_text(encoding="utf-8"))
    )
    return re.search(
        rf"(?m)^(?:pub(?:\([^()]*\))?\s+)?mod\s+"
        rf"{re.escape(KEYNOTE_CHART_LEGEND_PACKAGE_MODULE)}\s*;",
        package_source,
    ) is not None


def audit_keynote_chart_legend_visibility_facade_source_topology(
    root: Path = ROOT,
) -> list[str]:
    """Require the selector-first, generated-free focused legend facade.

    This audit remains dormant until the owner and private package module are
    wired together, so historical checkouts continue to pass while a
    migration is being staged. Once active, it checks only public Rust
    declarations and explicit re-exports; private graph identifiers are
    intentionally outside this boundary scan.
    """

    if not _keynote_chart_legend_boundary_active(root):
        return []

    violations: list[str] = []
    owner_path = root / KEYNOTE_CHART_LEGEND_OWNER_SOURCE
    package_path, lib_path = (
        root / path for path in KEYNOTE_CHART_LEGEND_EXPORT_SOURCES
    )

    if not owner_path.is_file():
        violations.append(
            "focused litchi-keynote chart-legend visibility public API is missing "
            f"private package owner source: {KEYNOTE_CHART_LEGEND_OWNER_SOURCE}"
        )
    if not package_path.is_file():
        violations.append(
            "focused litchi-keynote chart-legend visibility public API is missing "
            f"package export source: {KEYNOTE_CHART_LEGEND_EXPORT_SOURCES[0]}"
        )
    if not lib_path.is_file():
        violations.append(
            "focused litchi-keynote chart-legend visibility public API is missing "
            f"crate export source: {KEYNOTE_CHART_LEGEND_EXPORT_SOURCES[1]}"
        )

    package_source = (
        _mask_rust_cfg_test_items(package_path.read_text(encoding="utf-8"))
        if package_path.is_file()
        else ""
    )
    package_code = _mask_rust_non_code(package_source)
    module_matches = list(
        re.finditer(
            rf"(?m)^(?P<indent>\s*)(?P<public>pub(?:\([^()]*\))?\s+)?"
            rf"mod\s+{re.escape(KEYNOTE_CHART_LEGEND_PACKAGE_MODULE)}\s*;",
            package_code,
        )
    )
    if not module_matches:
        violations.append(
            "focused litchi-keynote chart-legend visibility public API is missing "
            f"private package owner module: {KEYNOTE_CHART_LEGEND_EXPORT_SOURCES[0]}"
        )
    elif any(match.group("public") for match in module_matches):
        line_number = package_code.count("\n", 0, module_matches[0].start()) + 1
        violations.append(
            "focused litchi-keynote chart-legend visibility owner module must remain "
            f"private: {KEYNOTE_CHART_LEGEND_EXPORT_SOURCES[0]}:{line_number}"
        )

    owner_source = (
        _mask_rust_cfg_test_items(owner_path.read_text(encoding="utf-8"))
        if owner_path.is_file()
        else ""
    )
    owner_methods = {
        name: declaration
        for name, declaration, _line in _rust_public_methods_in_impl(
            owner_source, "Package"
        )
    }
    for name in sorted(KEYNOTE_CHART_LEGEND_PACKAGE_METHODS):
        declaration = owner_methods.get(name)
        if declaration is None:
            violations.append(
                "focused litchi-keynote chart-legend visibility Package method is "
                f"missing {name}: {KEYNOTE_CHART_LEGEND_OWNER_SOURCE}"
            )
            continue
        if name == "apply_slide_chart_legend":
            required = "ChartLegendVisibilityPatch"
            if re.search(rf"\b{re.escape(required)}\b", declaration) is None:
                violations.append(
                    "focused litchi-keynote chart-legend visibility apply method must "
                    f"accept {required}: {KEYNOTE_CHART_LEGEND_OWNER_SOURCE}"
                )
        else:
            for selector in ("SlideSelector", "ChartSelector"):
                if re.search(rf"\b{selector}\b", declaration) is None:
                    violations.append(
                        "focused litchi-keynote chart-legend visibility Package method "
                        f"{name} must accept selector-first {selector}: "
                        f"{KEYNOTE_CHART_LEGEND_OWNER_SOURCE}"
                    )
        if re.search(r"\bu64\b", declaration):
            violations.append(
                "focused litchi-keynote chart-legend visibility Package method must "
                f"not expose u64: {name}: {KEYNOTE_CHART_LEGEND_OWNER_SOURCE}"
            )
        raw_id = KEYNOTE_CHART_LEGEND_RAW_ID_TOKEN.search(declaration)
        if raw_id is not None:
            violations.append(
                "focused litchi-keynote chart-legend visibility Package method must "
                f"not expose raw identifier {raw_id.group(0)}: "
                f"{name}: {KEYNOTE_CHART_LEGEND_OWNER_SOURCE}"
            )

    owner_declarations = _rust_public_declarations(owner_source)
    for declaration, line_number in owner_declarations:
        for match in KEYNOTE_CHART_LEGEND_RAW_ID_TOKEN.finditer(declaration):
            violations.append(
                "focused litchi-keynote chart-legend visibility public API exposes "
                f"raw identifier {match.group(0)}: "
                f"{KEYNOTE_CHART_LEGEND_OWNER_SOURCE}:{line_number}"
            )
        for match in RUST_BYTE_SLICE.finditer(declaration):
            raw_slice = re.sub(r"\s+", "", match.group(0))
            violations.append(
                "focused litchi-keynote chart-legend visibility public API exposes "
                f"raw byte slice {raw_slice}: "
                f"{KEYNOTE_CHART_LEGEND_OWNER_SOURCE}:{line_number}"
            )
        if re.search(
            r"\b(?:prost|prost_types|buffa|kn\w*|tsch?\w*|tsd\w*|"
            r"Archive|RawMessage|IWorkPackage|ComponentCatalog|WireView)\b",
            declaration,
        ):
            violations.append(
                "focused litchi-keynote chart-legend visibility public API exposes "
                f"generated/physical type: {KEYNOTE_CHART_LEGEND_OWNER_SOURCE}:"
                f"{line_number}"
            )

    for path in (package_path, lib_path):
        if not path.is_file():
            continue
        source = _mask_rust_cfg_test_items(path.read_text(encoding="utf-8"))
        exported = _rust_canonical_exports(source, KEYNOTE_CHART_LEGEND_CANONICAL_TYPES)
        for name in sorted(KEYNOTE_CHART_LEGEND_CANONICAL_TYPES - exported):
            violations.append(
                "focused litchi-keynote chart-legend visibility public API is missing "
                f"canonical type {name}: {path.relative_to(root)}"
            )
        for declaration, line_number in _rust_public_declarations(source):
            identifiers = {
                match.group(1) for match in RUST_IDENTIFIER.finditer(declaration)
            }
            if not (
                "slide_chart_legend" in declaration
                or identifiers & KEYNOTE_CHART_LEGEND_CANONICAL_TYPES
            ):
                continue
            for match in KEYNOTE_CHART_LEGEND_RAW_ID_TOKEN.finditer(declaration):
                violations.append(
                    "focused litchi-keynote chart-legend visibility public API exposes "
                    f"raw identifier {match.group(0)}: {path.relative_to(root)}:"
                    f"{line_number}"
                )
            for match in RUST_BYTE_SLICE.finditer(declaration):
                raw_slice = re.sub(r"\s+", "", match.group(0))
                violations.append(
                    "focused litchi-keynote chart-legend visibility public API exposes "
                    f"raw byte slice {raw_slice}: "
                    f"{path.relative_to(root)}:{line_number}"
                )
            if re.search(
                r"\b(?:prost|prost_types|buffa|kn\w*|tsch?\w*|tsd\w*|"
                r"Archive|RawMessage|IWorkPackage|ComponentCatalog|WireView)\b",
                declaration,
            ):
                violations.append(
                    "focused litchi-keynote chart-legend visibility public API exposes "
                    f"generated/physical type: {path.relative_to(root)}:{line_number}"
                )

    return sorted(set(violations))


def audit_iwa_keynote_chart_legend_source_topology(
    root: Path = ROOT,
) -> list[str]:
    """Retire only the raw Keynote chart-legend visibility host path."""

    if not _keynote_chart_legend_boundary_active(root):
        return []

    source_root = root / IWA_KEYNOTE_SOURCE_ROOT
    violations: list[str] = []
    if source_root.is_dir():
        paths = sorted(source_root.rglob("*.rs"))
    else:
        paths = []
    for path in paths:
        if path.name == "tests.rs" or "tests" in path.parts:
            continue
        source = _mask_rust_cfg_test_items(path.read_text(encoding="utf-8"))
        code = _mask_rust_non_code(source)
        for name, line_number in _rust_function_declarations(code):
            if name not in IWA_KEYNOTE_CHART_LEGEND_LEGACY_METHODS:
                continue
            violations.append(
                "retired litchi-iwa Keynote chart-legend visibility raw-ID method "
                f"{name}: {path.relative_to(root)}:{line_number}"
            )
        for match in IWA_KEYNOTE_CHART_LEGEND_LEGACY_CALL.finditer(code):
            line_start = code.rfind("\n", 0, match.start()) + 1
            line_end = code.find("\n", match.end())
            if line_end < 0:
                line_end = len(code)
            if re.search(
                rf"\bfn[ \t\r\n]+{re.escape(match.group('method'))}\b",
                code[line_start:line_end],
            ):
                # The declaration already has a focused method finding above;
                # keep the production audit concise without hiding calls in
                # unrelated function bodies.
                continue
            line_number = code.count("\n", 0, match.start()) + 1
            violations.append(
                "retired litchi-iwa Keynote chart-legend visibility raw-ID call "
                f"{match.group('method')}: {path.relative_to(root)}:{line_number}"
            )
        for match in KEYNOTE_CHART_LEGEND_DIRECT_HELPER.finditer(code):
            line_number = code.count("\n", 0, match.start()) + 1
            violations.append(
                "retired litchi-iwa Keynote chart-legend visibility direct helper "
                f"{match.group(0)}: {path.relative_to(root)}:{line_number}"
            )

    examples = root / Path("crates/litchi-iwa/examples")
    if examples.is_dir():
        for path in sorted(examples.rglob("*.rs")):
            code = _mask_rust_non_code(
                _mask_rust_cfg_test_items(path.read_text(encoding="utf-8"))
            )
            for match in IWA_KEYNOTE_CHART_LEGEND_LEGACY_CALL.finditer(code):
                line_number = code.count("\n", 0, match.start()) + 1
                violations.append(
                    "retired litchi-iwa Keynote chart-legend visibility example "
                    f"retains raw-ID call {match.group('method')}: "
                    f"{path.relative_to(root)}:{line_number}"
                )

    return sorted(set(violations))


def _keynote_chart_arrangement_owner_present(root: Path) -> bool:
    """Return whether the focused chart-arrangement owner is wired."""

    owner_path = root / KEYNOTE_CHART_ARRANGEMENT_OWNER_SOURCE
    package_path = root / KEYNOTE_CHART_ARRANGEMENT_EXPORT_SOURCES[0]
    package_source = (
        _mask_rust_non_code(
            _mask_rust_cfg_test_items(package_path.read_text(encoding="utf-8"))
        )
        if package_path.is_file()
        else ""
    )
    return owner_path.is_file() and re.search(
        rf"(?m)^(?:pub(?:[ \t]*\([^()]*\))?[ \t]+)?mod[ \t]+"
        rf"{re.escape(KEYNOTE_CHART_ARRANGEMENT_PACKAGE_MODULE)}\s*;",
        package_source,
    ) is not None


def _chart_arrangement_all_owners_present(root: Path) -> bool:
    """Return whether Keynote, Numbers, and Pages owners are all wired."""

    if not _keynote_chart_arrangement_owner_present(root):
        return False
    for owner_path, package_path, module_name in (
        (
            NUMBERS_CHART_ARRANGEMENT_OWNER_SOURCE,
            NUMBERS_PACKAGE_SOURCE,
            NUMBERS_CHART_ARRANGEMENT_PACKAGE_MODULE,
        ),
        (
            PAGES_BODY_CHART_ARRANGEMENT_OWNER_SOURCE,
            PAGES_PACKAGE_SOURCE,
            PAGES_BODY_CHART_ARRANGEMENT_PACKAGE_MODULE,
        ),
    ):
        package = root / package_path
        if not (root / owner_path).is_file() or not package.is_file():
            return False
        source = _mask_rust_cfg_test_items(package.read_text(encoding="utf-8"))
        if not _rust_root_level_module_declarations(
            source,
            frozenset({module_name}),
        ):
            return False
    return True


def _chart_arrangement_check_codec(root: Path) -> list[str]:
    """Require the neutral private, Buffa-backed chart-arrangement boundary."""

    codec_path = root / CHART_ARRANGEMENT_CODEC_SOURCE
    retired_codec_path = root / RETIRED_KEYNOTE_CHART_ARRANGEMENT_CODEC_SOURCE
    public_path = root / CHART_ARRANGEMENT_CODEC_PUBLIC_SOURCE
    violations: list[str] = []
    if retired_codec_path.is_file():
        violations.append(
            "retired Keynote-specific chart-arrangement codec source must remain "
            f"deleted: {RETIRED_KEYNOTE_CHART_ARRANGEMENT_CODEC_SOURCE}"
        )
    if not codec_path.is_file():
        return [
            "neutral chart-arrangement codec source is missing: "
            f"{CHART_ARRANGEMENT_CODEC_SOURCE}"
        ]

    raw_codec = codec_path.read_text(encoding="utf-8")
    codec = _mask_rust_non_code(_mask_rust_cfg_test_items(raw_codec))
    codec_attributes = _mask_rust_non_code(raw_codec)

    for api in CHART_ARRANGEMENT_CODEC_REQUIRED_APIS:
        if re.search(
            rf"\b(?:pub\s+)?(?:fn|struct|enum|type)\s+{re.escape(api)}\b",
            codec,
        ) is None:
            violations.append(
                "neutral chart-arrangement codec is missing strict API "
                f"{api}: {CHART_ARRANGEMENT_CODEC_SOURCE}"
            )

    def has_marker(marker: str | tuple[str, ...]) -> bool:
        if isinstance(marker, tuple):
            return any(has_marker(item) for item in marker)
        return marker in codec

    for label, markers in CHART_ARRANGEMENT_CODEC_REQUIRED_MARKER_GROUPS.items():
        if not all(has_marker(marker) for marker in markers):
            violations.append(
                "neutral chart-arrangement codec is missing "
                f"{label} marker: {CHART_ARRANGEMENT_CODEC_SOURCE}"
            )

    if re.search(r"\b(?:prost|prost_types)\b", codec) is not None:
        violations.append(
            "neutral chart-arrangement codec must use Buffa rather "
            f"than Prost: {CHART_ARRANGEMENT_CODEC_SOURCE}"
        )
    for declaration, line_number in _rust_public_declarations(codec):
        if re.search(
            rf"\b{re.escape(CHART_ARRANGEMENT_CODEC_GENERATED_MODULE)}\b"
            r"|\bprojection\s*::",
            declaration,
        ):
            violations.append(
                "neutral chart-arrangement codec must not expose Buffa "
                f"generated types: {CHART_ARRANGEMENT_CODEC_SOURCE}:{line_number}"
            )
    if _rust_root_generated_public_leaks(
        codec,
        frozenset({CHART_ARRANGEMENT_CODEC_GENERATED_MODULE}),
    ):
        violations.append(
            "neutral chart-arrangement codec must not expose Buffa "
            f"generated aliases: {CHART_ARRANGEMENT_CODEC_SOURCE}"
        )

    if not public_path.is_file():
        violations.append(
            "neutral chart-arrangement codec public module source is "
            f"missing: {CHART_ARRANGEMENT_CODEC_PUBLIC_SOURCE}"
        )
        return sorted(set(violations))

    raw_public = public_path.read_text(encoding="utf-8")
    public = _mask_rust_cfg_test_items(raw_public)
    public_code = _mask_rust_non_code(public)
    if not _rust_root_level_matches(public, CHART_ARRANGEMENT_CODEC_HIDDEN_MODULE):
        violations.append(
            "neutral chart-arrangement codec module must be hidden: "
            f"{CHART_ARRANGEMENT_CODEC_PUBLIC_SOURCE}"
        )
    retired_module_declarations = _rust_root_level_module_declarations(
        public,
        frozenset({RETIRED_KEYNOTE_CHART_ARRANGEMENT_CODEC_MODULE}),
    )
    for _, _, _, _, line_number in retired_module_declarations:
        violations.append(
            "retired Keynote-specific chart-arrangement codec module must remain "
            f"deleted: {CHART_ARRANGEMENT_CODEC_PUBLIC_SOURCE}:{line_number}"
        )
    generated_declarations = _rust_root_level_module_declarations(
        public,
        frozenset({CHART_ARRANGEMENT_CODEC_GENERATED_MODULE}),
    )
    if not generated_declarations:
        violations.append(
            "neutral chart-arrangement codec is missing its private "
            f"Buffa generated module: {CHART_ARRANGEMENT_CODEC_PUBLIC_SOURCE}"
        )
    for module, visibility, shape, body, line_number in generated_declarations:
        if visibility is not None:
            violations.append(
                "neutral chart-arrangement codec generated module must "
                f"remain private: {CHART_ARRANGEMENT_CODEC_PUBLIC_SOURCE}:{line_number}"
            )
        if shape == "invalid" or (
            shape == "inline" and not _rust_generated_module_include_is_valid(body)
        ):
            violations.append(
                "neutral chart-arrangement codec generated module has "
                f"invalid include shape: {CHART_ARRANGEMENT_CODEC_PUBLIC_SOURCE}:{line_number}"
            )
    if _rust_root_generated_public_leaks(
        public,
        frozenset({CHART_ARRANGEMENT_CODEC_GENERATED_MODULE}),
    ):
        violations.append(
            "neutral chart-arrangement codec must not re-export Buffa "
            f"generated types: {CHART_ARRANGEMENT_CODEC_PUBLIC_SOURCE}"
        )
    if re.search(
        r"(?m)#\s*\[\s*cfg\s*\(\s*test\s*\)\s*\]", codec_attributes
    ) is None:
        violations.append(
            "neutral chart-arrangement codec is missing cfg(test) "
            f"coverage: {CHART_ARRANGEMENT_CODEC_SOURCE}"
        )
    elif re.search(r"(?m)#\s*\[\s*test\s*\]", codec_attributes) is None:
        violations.append(
            "neutral chart-arrangement codec is missing #[test] "
            f"coverage: {CHART_ARRANGEMENT_CODEC_SOURCE}"
        )
    return sorted(set(violations))


def audit_chart_arrangement_codec_source_topology(
    root: Path = ROOT,
) -> list[str]:
    """Require the neutral chart-arrangement codec and private Buffa view."""

    if not _chart_arrangement_all_owners_present(root):
        return []
    return _chart_arrangement_check_codec(root)


def _audit_focused_chart_arrangement_owner_source_topology(
    root: Path,
    *,
    label: str,
    owner_source: Path,
    package_source: Path,
    public_source: Path,
    module_name: str,
    methods: tuple[str, ...],
    selector_types: dict[str, tuple[str, ...]],
    method_markers: dict[str, tuple[str, ...]],
    owner_markers: tuple[str, ...],
    lazy_codec_markers: tuple[str, ...],
    canonical_types: tuple[str, ...],
) -> list[str]:
    """Audit one focused chart-arrangement package owner.

    The ratchet is deliberately limited to the public package seam and a few
    stable ownership markers.  Native graph identifiers and wire helpers may
    occur in the private implementation, but the selector-first methods must
    admit semantic selectors, route through bounded discovery, and verify the
    selected candidate locally before publication.
    """

    owner_path = root / owner_source
    package_path = root / package_source
    public_path = root / public_source
    violations: list[str] = []
    if not owner_path.is_file():
        return [
            f"focused {label} owner source is missing: {owner_source}"
        ]
    if not package_path.is_file():
        violations.append(
            f"focused {label} package source is missing: {package_source}"
        )
    if not public_path.is_file():
        violations.append(
            f"focused {label} crate export source is missing: {public_source}"
        )

    owner_source_text = _mask_rust_cfg_test_items(
        owner_path.read_text(encoding="utf-8")
    )
    owner_code = _mask_rust_non_code(owner_source_text)
    package_source_text = (
        _mask_rust_cfg_test_items(package_path.read_text(encoding="utf-8"))
        if package_path.is_file()
        else ""
    )
    package_code = _mask_rust_non_code(package_source_text)
    public_source_text = (
        _mask_rust_cfg_test_items(public_path.read_text(encoding="utf-8"))
        if public_path.is_file()
        else ""
    )
    public_code = _mask_rust_non_code(public_source_text)

    module_declarations = _rust_root_level_module_declarations(
        package_source_text,
        frozenset({module_name}),
    )
    if not module_declarations:
        violations.append(
            f"focused {label} package owner module is missing: {package_source}"
        )
    for _, visibility, _, _, line_number in module_declarations:
        if visibility is not None:
            violations.append(
                f"focused {label} package owner module must remain private: "
                f"{package_source}:{line_number}"
            )

    public_declarations = _rust_public_declarations(owner_source_text)
    method_declarations: dict[str, tuple[str, int]] = {}
    for name in methods:
        for declaration, line_number in public_declarations:
            if re.search(
                rf"\bfn[ \t\r\n]+(?:r#)?{re.escape(name)}\b",
                declaration,
            ):
                method_declarations[name] = (declaration, line_number)
                break
        declaration_record = method_declarations.get(name)
        if declaration_record is None:
            violations.append(
                f"focused {label} package API is missing public method {name}: "
                f"{owner_source}"
            )
            continue
        declaration, line_number = declaration_record
        expected_selectors = selector_types.get(name, ())
        for selector in expected_selectors:
            if re.search(rf"\b{re.escape(selector)}\b", declaration) is None:
                violations.append(
                    f"focused {label} selector API {name} must accept {selector}: "
                    f"{owner_source}:{line_number}"
                )
        if re.search(
            r"&\s*\[\s*u8\s*\]|\b(?:u64|u32|i64|i32)\b",
            declaration,
        ):
            violations.append(
                f"focused {label} public method {name} exposes a raw native/wire "
                f"parameter: {owner_source}:{line_number}"
            )
        body = _rust_any_function_body(owner_source_text, name)
        if body is None:
            violations.append(
                f"focused {label} package API method {name} has no inspectable body: "
                f"{owner_source}:{line_number}"
            )
            continue
        for marker in method_markers.get(name, ()):
            if re.search(rf"\b{re.escape(marker)}\b", body) is None:
                violations.append(
                    f"focused {label} package API method {name} is missing "
                    f"ownership marker {marker}: {owner_source}:{line_number}"
                )

    for marker in owner_markers:
        if re.search(rf"\b{re.escape(marker)}\b", owner_code) is None:
            violations.append(
                f"focused {label} owner is missing admission/locality marker "
                f"{marker}: {owner_source}"
            )
    for marker in lazy_codec_markers:
        if re.search(rf"\b{re.escape(marker)}\b", owner_code) is None:
            violations.append(
                f"focused {label} owner is missing lazy Buffa codec marker "
                f"{marker}: {owner_source}"
            )
    if re.search(r"\bPackage\s*::\s*from_bytes\s*\(", owner_code):
        violations.append(
            f"focused {label} owner must not reparse through Package::from_bytes: "
            f"{owner_source}"
        )
    if re.search(r"\b(?:prost|prost_types)\b", owner_code):
        violations.append(
            f"focused {label} owner must use the neutral Buffa codec rather than Prost: "
            f"{owner_source}"
        )

    if public_path.is_file():
        for name in canonical_types:
            if re.search(rf"\b{re.escape(name)}\b", public_code) is None:
                violations.append(
                    f"focused {label} crate export is missing {name}: {public_source}"
                )
        if re.search(r"\bChartArrangement\b", public_code) is None:
            violations.append(
                f"focused {label} crate export is missing semantic ChartArrangement: "
                f"{public_source}"
            )

    return sorted(set(violations))


def audit_numbers_chart_arrangement_owner_source_topology(
    root: Path = ROOT,
) -> list[str]:
    """Require the selector-first Numbers chart-arrangement package owner."""

